static uint32_t rtcore_context_float_to_u32(float value) {
  uint32_t word = 0;
  memcpy(&word, &value, sizeof(word));
  return word;
}

static float rtcore_context_u32_to_float(uint32_t word) {
  float value = 0.0f;
  memcpy(&value, &word, sizeof(value));
  return value;
}

static uint64_t rtcore_context_u64(uint32_t lo, uint32_t hi) {
  return (uint64_t)lo | ((uint64_t)hi << 32);
}

static void rtcore_context_store_u64(rtcore_v03_compact_context_image *image,
                                     unsigned lo_word, uint64_t value) {
  image->words[lo_word] = (uint32_t)value;
  image->words[lo_word + 1] = (uint32_t)(value >> 32);
}

static const char *rtcore_v03_context_test_mutation() {
  const char *value = getenv("VULKAN_SIM_RTCORE_TEST_CONTEXT_IMAGE_MUTATION");
  return value == NULL ? "" : value;
}

namespace {
static bool rtcore_publication_context_window_matches_lane(
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    ptx_thread_info *thread);
}

static void rtcore_apply_v03_context_test_mutation(
    rtcore_v03_compact_context_image *image) {
  const char *mode = rtcore_v03_context_test_mutation();
  if (strcmp(mode, "invalid_layout") == 0) {
    image->words[RTCORE_CONTEXT_W_HEADER] &= ~(0xffu << 16);
  } else if (strcmp(mode, "missing_trace_valid") == 0) {
    image->words[RTCORE_CONTEXT_W_HEADER] &= ~(0xffu << 24);
  } else if (strcmp(mode, "invalid_pipeline_profile") == 0) {
    image->words[RTCORE_CONTEXT_W_PIPELINE_PROFILE] = 0;
  } else if (strcmp(mode, "invalid_bvh_profile") == 0) {
    image->words[RTCORE_CONTEXT_W_BVH_FORMAT_PROFILE] = 0;
  } else if (strcmp(mode, "mutate_ray_tmin") == 0) {
    const float ray_tmin = rtcore_context_u32_to_float(
        image->words[RTCORE_CONTEXT_W_RAY_TMIN]);
    image->words[RTCORE_CONTEXT_W_RAY_TMIN] =
        rtcore_context_float_to_u32(ray_tmin + 0.25f);
  } else if (strcmp(mode, "mutate_sbt_offset") == 0) {
    image->words[RTCORE_CONTEXT_W_SBT_OFFSET] += 1;
  } else if (strcmp(mode, "mutate_sbt_hit_stride") == 0) {
    image->words[RTCORE_CONTEXT_W_SBT_HIT_STRIDE] += 32;
  }
}

static bool rtcore_context_sbt_region_valid(uint64_t base, uint32_t stride,
                                            uint32_t size) {
  if (base == 0) {
    return stride == 0 && size == 0;
  }
  return stride != 0 && size != 0 && size >= stride;
}

static bool rtcore_publish_v03_compact_context_image(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    uint64_t top_level_as,
    uint32_t ray_flags, uint32_t cull_mask, uint32_t sbt_record_offset,
    uint32_t sbt_record_stride, uint32_t miss_index, float3 ray_origin,
    float ray_tmin, float3 ray_direction, float ray_tmax) {
  if (thread == NULL || context_ptr == 0 || (context_ptr % 64) != 0 ||
      !rtcore_publication_context_window_matches_lane(
          context_ptr, handoff_window_base, thread)) {
    return false;
  }

  const vulkan_kernel_metadata &metadata = thread->get_kernel().vulkan_metadata;
  const uint64_t launch_context_count =
      (uint64_t)metadata.launch_width * metadata.launch_height *
      metadata.launch_depth;
  if (launch_context_count == 0 ||
      launch_context_count > RTCORE_MAX_CONTEXTS_PER_TRACE_SITE ||
      metadata.launch_width > RTCORE_MAX_LAUNCH_WIDTH ||
      metadata.launch_height > RTCORE_MAX_LAUNCH_HEIGHT ||
      metadata.launch_depth != 1) {
    return false;
  }
  if (metadata.hit_sbt_stride > 0xffffffffull ||
      metadata.hit_sbt_size > 0xffffffffull ||
      metadata.miss_sbt_stride > 0xffffffffull ||
      metadata.miss_sbt_size > 0xffffffffull ||
      metadata.callable_sbt_stride > 0xffffffffull ||
      metadata.callable_sbt_size > 0xffffffffull) {
    return false;
  }

  rtcore_v03_compact_context_image image;
  memset(&image, 0, sizeof(image));
  image.words[RTCORE_CONTEXT_W_HEADER] =
      RTCORE_CONTEXT_STATE_READY_FOR_SUBMIT |
      (RTCORE_CONTEXT_LAYOUT_V03_COMPACT_320B << 16) |
      (RTCORE_CONTEXT_VALID_TRACE_INPUT << 24);
  rtcore_context_store_u64(&image, RTCORE_CONTEXT_W_AS_REF_LO,
                           top_level_as);
  image.words[RTCORE_CONTEXT_W_RAY_ORIGIN_X] =
      rtcore_context_float_to_u32(ray_origin.x);
  image.words[RTCORE_CONTEXT_W_RAY_ORIGIN_Y] =
      rtcore_context_float_to_u32(ray_origin.y);
  image.words[RTCORE_CONTEXT_W_RAY_ORIGIN_Z] =
      rtcore_context_float_to_u32(ray_origin.z);
  image.words[RTCORE_CONTEXT_W_RAY_TMIN] =
      rtcore_context_float_to_u32(ray_tmin);
  image.words[RTCORE_CONTEXT_W_RAY_DIRECTION_X] =
      rtcore_context_float_to_u32(ray_direction.x);
  image.words[RTCORE_CONTEXT_W_RAY_DIRECTION_Y] =
      rtcore_context_float_to_u32(ray_direction.y);
  image.words[RTCORE_CONTEXT_W_RAY_DIRECTION_Z] =
      rtcore_context_float_to_u32(ray_direction.z);
  image.words[RTCORE_CONTEXT_W_RAY_TMAX] =
      rtcore_context_float_to_u32(ray_tmax);
  image.words[RTCORE_CONTEXT_W_RAY_FLAGS] = ray_flags;
  image.words[RTCORE_CONTEXT_W_CULL_MASK] = cull_mask;
  image.words[RTCORE_CONTEXT_W_SBT_OFFSET] = sbt_record_offset;
  image.words[RTCORE_CONTEXT_W_SBT_STRIDE] = sbt_record_stride;
  image.words[RTCORE_CONTEXT_W_MISS_INDEX] = miss_index;
  rtcore_context_store_u64(
      &image, RTCORE_CONTEXT_W_SBT_HIT_BASE_LO,
      (uint64_t)(uintptr_t)metadata.hit_sbt_device_addr);
  image.words[RTCORE_CONTEXT_W_SBT_HIT_STRIDE] =
      (uint32_t)metadata.hit_sbt_stride;
  image.words[RTCORE_CONTEXT_W_SBT_HIT_SIZE] =
      (uint32_t)metadata.hit_sbt_size;
  rtcore_context_store_u64(
      &image, RTCORE_CONTEXT_W_SBT_MISS_BASE_LO,
      (uint64_t)(uintptr_t)metadata.miss_sbt_device_addr);
  image.words[RTCORE_CONTEXT_W_SBT_MISS_STRIDE] =
      (uint32_t)metadata.miss_sbt_stride;
  image.words[RTCORE_CONTEXT_W_SBT_MISS_SIZE] =
      (uint32_t)metadata.miss_sbt_size;
  rtcore_context_store_u64(
      &image, RTCORE_CONTEXT_W_SBT_CALLABLE_BASE_LO,
      (uint64_t)(uintptr_t)metadata.callable_sbt_device_addr);
  image.words[RTCORE_CONTEXT_W_SBT_CALLABLE_STRIDE] =
      (uint32_t)metadata.callable_sbt_stride;
  image.words[RTCORE_CONTEXT_W_SBT_CALLABLE_SIZE] =
      (uint32_t)metadata.callable_sbt_size;
  image.words[RTCORE_CONTEXT_W_PIPELINE_PROFILE] =
      RTCORE_PIPELINE_PROFILE_V03_CUSTOM_SYNC;
  image.words[RTCORE_CONTEXT_W_BVH_FORMAT_PROFILE] =
      RTCORE_BVH_FORMAT_VULKAN_SIM_GEN_RT;
  rtcore_apply_v03_context_test_mutation(&image);

  memory_space *memory = thread->get_global_memory();
  memory->write_simulator_backing((mem_addr_t)context_ptr, sizeof(image),
                                  &image);
  if (strcmp(rtcore_v03_context_test_mutation(),
             "mutate_ray_tmin_via_global_store") == 0) {
    const float mutated_tmin = ray_tmin + 0.25f;
    memory->write((mem_addr_t)context_ptr +
                      RTCORE_CONTEXT_W_RAY_TMIN * sizeof(uint32_t),
                  sizeof(mutated_tmin), &mutated_tmin, thread, pI);
  }
  printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT "
         "compact-context-publication (%s:%u), "
         "source=context_abi_byte_image, context_ptr=0x%llx, "
         "context_bytes=%zu, context_layout_version=%u, valid_flags=0x%02x, "
         "as_ref=0x%llx, sbt_hit_base=0x%llx, sbt_hit_stride=%u, "
         "sbt_hit_size=%u, sbt_miss_base=0x%llx, sbt_miss_stride=%u, "
         "sbt_miss_size=%u, pipeline_profile_id=%u, "
         "bvh_format_profile_id=%u, mutation=%s\n",
         pI->source_file(), pI->source_line(), context_ptr, sizeof(image),
         (image.words[RTCORE_CONTEXT_W_HEADER] >> 16) & 0xffu,
         (image.words[RTCORE_CONTEXT_W_HEADER] >> 24) & 0xffu,
         (unsigned long long)top_level_as,
         (unsigned long long)(uintptr_t)metadata.hit_sbt_device_addr,
         (uint32_t)metadata.hit_sbt_stride,
         (uint32_t)metadata.hit_sbt_size,
         (unsigned long long)(uintptr_t)metadata.miss_sbt_device_addr,
         (uint32_t)metadata.miss_sbt_stride,
         (uint32_t)metadata.miss_sbt_size,
         image.words[RTCORE_CONTEXT_W_PIPELINE_PROFILE],
         image.words[RTCORE_CONTEXT_W_BVH_FORMAT_PROFILE],
         rtcore_v03_context_test_mutation());
  fflush(stdout);
  return true;
}

static bool rtcore_decode_v03_compact_context_image(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned long long context_ptr,
    rtcore_v03_compact_context_decoded *decoded) {
  if (thread == NULL || decoded == NULL || context_ptr == 0 ||
      (context_ptr % 64) != 0) {
    return false;
  }

  rtcore_v03_compact_context_image image;
  memset(&image, 0, sizeof(image));
  thread->get_global_memory()->read_simulator_backing(
      (mem_addr_t)context_ptr, sizeof(image), &image);
  const uint32_t header = image.words[RTCORE_CONTEXT_W_HEADER];
  decoded->context_state = header & 0xffu;
  decoded->recursion_depth = (header >> 8) & 0xffu;
  decoded->context_layout_version = (header >> 16) & 0xffu;
  decoded->valid_flags = (header >> 24) & 0xffu;
  decoded->as_handle_or_traversable_ref = rtcore_context_u64(
      image.words[RTCORE_CONTEXT_W_AS_REF_LO],
      image.words[RTCORE_CONTEXT_W_AS_REF_HI]);
  decoded->ray_origin.x = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_ORIGIN_X]);
  decoded->ray_origin.y = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_ORIGIN_Y]);
  decoded->ray_origin.z = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_ORIGIN_Z]);
  decoded->ray_tmin = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_TMIN]);
  decoded->ray_direction.x = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_DIRECTION_X]);
  decoded->ray_direction.y = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_DIRECTION_Y]);
  decoded->ray_direction.z = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_DIRECTION_Z]);
  decoded->ray_tmax = rtcore_context_u32_to_float(
      image.words[RTCORE_CONTEXT_W_RAY_TMAX]);
  decoded->ray_flags = image.words[RTCORE_CONTEXT_W_RAY_FLAGS];
  decoded->cull_mask = image.words[RTCORE_CONTEXT_W_CULL_MASK];
  decoded->sbt_offset = image.words[RTCORE_CONTEXT_W_SBT_OFFSET];
  decoded->sbt_stride = image.words[RTCORE_CONTEXT_W_SBT_STRIDE];
  decoded->miss_index = image.words[RTCORE_CONTEXT_W_MISS_INDEX];
  decoded->sbt_hit_base = rtcore_context_u64(
      image.words[RTCORE_CONTEXT_W_SBT_HIT_BASE_LO],
      image.words[RTCORE_CONTEXT_W_SBT_HIT_BASE_HI]);
  decoded->sbt_hit_stride = image.words[RTCORE_CONTEXT_W_SBT_HIT_STRIDE];
  decoded->sbt_hit_size = image.words[RTCORE_CONTEXT_W_SBT_HIT_SIZE];
  decoded->sbt_miss_base = rtcore_context_u64(
      image.words[RTCORE_CONTEXT_W_SBT_MISS_BASE_LO],
      image.words[RTCORE_CONTEXT_W_SBT_MISS_BASE_HI]);
  decoded->sbt_miss_stride = image.words[RTCORE_CONTEXT_W_SBT_MISS_STRIDE];
  decoded->sbt_miss_size = image.words[RTCORE_CONTEXT_W_SBT_MISS_SIZE];
  decoded->sbt_callable_base = rtcore_context_u64(
      image.words[RTCORE_CONTEXT_W_SBT_CALLABLE_BASE_LO],
      image.words[RTCORE_CONTEXT_W_SBT_CALLABLE_BASE_HI]);
  decoded->sbt_callable_stride =
      image.words[RTCORE_CONTEXT_W_SBT_CALLABLE_STRIDE];
  decoded->sbt_callable_size =
      image.words[RTCORE_CONTEXT_W_SBT_CALLABLE_SIZE];
  decoded->pipeline_profile_id =
      image.words[RTCORE_CONTEXT_W_PIPELINE_PROFILE];
  decoded->bvh_format_profile_id =
      image.words[RTCORE_CONTEXT_W_BVH_FORMAT_PROFILE];

  const bool header_valid =
      decoded->context_state == RTCORE_CONTEXT_STATE_READY_FOR_SUBMIT &&
      decoded->context_layout_version ==
          RTCORE_CONTEXT_LAYOUT_V03_COMPACT_320B &&
      (decoded->valid_flags & RTCORE_CONTEXT_VALID_TRACE_INPUT) != 0 &&
      (decoded->valid_flags & ~0x07u) == 0 &&
      image.words[RTCORE_CONTEXT_W_RESERVED_PREFIX] == 0;
  const bool trace_input_valid =
      decoded->as_handle_or_traversable_ref != 0 &&
      image.words[RTCORE_CONTEXT_W_RESERVED_TRACE] == 0 &&
      (decoded->cull_mask & 0xffffff00u) == 0;
  const bool sbt_valid =
      rtcore_context_sbt_region_valid(decoded->sbt_hit_base,
                                      decoded->sbt_hit_stride,
                                      decoded->sbt_hit_size) &&
      rtcore_context_sbt_region_valid(decoded->sbt_miss_base,
                                      decoded->sbt_miss_stride,
                                      decoded->sbt_miss_size) &&
      rtcore_context_sbt_region_valid(decoded->sbt_callable_base,
                                      decoded->sbt_callable_stride,
                                      decoded->sbt_callable_size);
  const bool profile_valid =
      decoded->pipeline_profile_id ==
          RTCORE_PIPELINE_PROFILE_V03_CUSTOM_SYNC &&
      decoded->bvh_format_profile_id ==
          RTCORE_BVH_FORMAT_VULKAN_SIM_GEN_RT;
  decoded->valid = header_valid && trace_input_valid && sbt_valid &&
                   profile_valid;

  printf("GPGPU-Sim PTX: RT_SUBMIT compact-context-decode (%s:%u), "
         "source=context_abi_byte_image, context_ptr=0x%llx, valid=%u, "
         "header_valid=%u, trace_input_valid=%u, sbt_valid=%u, "
         "profile_valid=%u, context_state=%u, context_layout_version=%u, "
         "valid_flags=0x%02x, as_ref=0x%llx, ray_tmin=%g, ray_tmax=%g, "
         "ray_flags=%u, cull_mask=%u, sbt_offset=%u, sbt_stride=%u, "
         "miss_index=%u, sbt_hit_base=0x%llx, sbt_hit_stride=%u, "
         "sbt_hit_size=%u, sbt_miss_base=0x%llx, sbt_miss_stride=%u, "
         "sbt_miss_size=%u, pipeline_profile_id=%u, "
         "bvh_format_profile_id=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         decoded->valid ? 1 : 0, header_valid ? 1 : 0,
         trace_input_valid ? 1 : 0, sbt_valid ? 1 : 0,
         profile_valid ? 1 : 0, decoded->context_state,
         decoded->context_layout_version, decoded->valid_flags,
         (unsigned long long)decoded->as_handle_or_traversable_ref,
         decoded->ray_tmin, decoded->ray_tmax, decoded->ray_flags,
         decoded->cull_mask, decoded->sbt_offset, decoded->sbt_stride,
         decoded->miss_index, (unsigned long long)decoded->sbt_hit_base,
         decoded->sbt_hit_stride, decoded->sbt_hit_size,
         (unsigned long long)decoded->sbt_miss_base,
         decoded->sbt_miss_stride, decoded->sbt_miss_size,
         decoded->pipeline_profile_id, decoded->bvh_format_profile_id);
  fflush(stdout);
  return decoded->valid;
}

namespace {

namespace functional_engine = rtcore::v04::functional_engine;
namespace functional_driver = rtcore::v04::functional_driver;
namespace private_frontier = rtcore::v04::private_frontier;
namespace request_owner = rtcore::v04::request_owner;
namespace root_node_packet = rtcore::v04::root_node_packet;

static const unsigned kRtcoreV04FunctionalOnlyLaneCapacity = 32;

struct rtcore_v04_functional_only_lane_record {
  bool valid;
  bool initial_output_consumed;
  bool completion_words_valid;
  unsigned thread_uid;
  unsigned long long context_ptr;
  unsigned long long handoff_window_base;
  unsigned sbt_record_offset;
  unsigned sbt_record_stride;
  unsigned miss_index;
  unsigned token_id;
  unsigned token_allocator_generation;
  unsigned window_generation;
  std::array<uint32_t, rtcore::abi_v04::kWordCount> trace_input_words;
  std::array<uint32_t, rtcore::abi_v04::kWordCount> completion_words;
  request_owner::lane_binding_v0 request_binding;
  functional_engine::state_v0 engine_state;
  functional_engine::output_v0 engine_output;

  rtcore_v04_functional_only_lane_record()
      : valid(false),
        initial_output_consumed(false),
        completion_words_valid(false),
        thread_uid(0),
        context_ptr(0),
        handoff_window_base(0),
        sbt_record_offset(0),
        sbt_record_stride(0),
        miss_index(0),
        token_id(0),
        token_allocator_generation(0),
        window_generation(0),
        trace_input_words(),
        completion_words(),
        request_binding(),
        engine_state(),
        engine_output() {}
};

struct rtcore_v04_functional_only_warp_record {
  bool valid;
  unsigned owner_hw_sid;
  unsigned warp_uid;
  unsigned warp_id;
  unsigned static_inst_uid;
  unsigned active_mask;
  unsigned bound_lane_mask;
  unsigned resident_warp_slot;
  unsigned resident_generation;
  unsigned completion_transaction_generation;
  bool completion_published;
  bool completion_consumed;
  rtcore_v04_functional_only_lane_record
      lane[kRtcoreV04FunctionalOnlyLaneCapacity];

  rtcore_v04_functional_only_warp_record()
      : valid(false),
        owner_hw_sid(0),
        warp_uid(0),
        warp_id(0),
        static_inst_uid(0),
        active_mask(0),
        bound_lane_mask(0),
        resident_warp_slot(0),
        resident_generation(0),
        completion_transaction_generation(0),
        completion_published(false),
        completion_consumed(false),
        lane() {}
};

struct rtcore_v04_functional_only_resubmit_stage {
  bool valid;
  unsigned previous_warp_uid;
  request_owner::mask_shrink_plan_v0 owner_plan;
  rtcore_v04_functional_only_warp_record next_record;

  rtcore_v04_functional_only_resubmit_stage()
      : valid(false), previous_warp_uid(0), owner_plan(), next_record() {}
};

struct rtcore_v04_functional_only_initial_stage {
  bool valid;
  bool owner_plan_precommitted;
  unsigned finalized_lane_mask;
  request_owner::new_warp_plan_v0 owner_plan;
  rtcore_v04_functional_only_warp_record record;

  rtcore_v04_functional_only_initial_stage()
      : valid(false), owner_plan_precommitted(false), finalized_lane_mask(0),
        owner_plan(), record() {}
};

typedef std::pair<unsigned, unsigned> rtcore_v04_functional_only_warp_key;

static std::map<unsigned, request_owner::allocator_state_v0>
    g_rtcore_v04_functional_only_owner_allocators;
static std::map<rtcore_v04_functional_only_warp_key,
                rtcore_v04_functional_only_warp_record>
    g_rtcore_v04_functional_only_live_warps;
static std::map<unsigned, rtcore_v04_functional_only_initial_stage>
    g_rtcore_v04_functional_only_initial_stages;
static std::map<unsigned, rtcore_v04_functional_only_resubmit_stage>
    g_rtcore_v04_functional_only_resubmit_stages;

static void rtcore_v04_functional_only_record_lane_or_abort(
    rtcore::v04::conservation::event_kind event,
    const request_owner::lane_binding_v0 &binding,
    unsigned operation_seq, unsigned commit_epoch,
    unsigned transport_id, unsigned item_id, unsigned item_count,
    unsigned detail_kind) {
  rtcore::v04::conservation::lane_event_v0 record = {};
  record.owner =
      request_owner::make_private_frontier_owner(binding);
  record.operation_seq = operation_seq;
  record.commit_epoch = commit_epoch;
  record.transport_id = transport_id;
  record.item_id = static_cast<uint16_t>(item_id);
  record.item_count = static_cast<uint16_t>(item_count);
  record.event = event;
  record.detail_kind = static_cast<uint8_t>(detail_kind);
  if (!rtcore::v04::conservation::emit_lane_event(record)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_CONSERVATION_FAULT "
            "driver=functional_only owner_hw_sid=%u "
            "request_identity=0x%08x generation=%u lane_id=%u "
            "operation_seq=%u event=%s\n",
            binding.owner_hw_sid, binding.packed_request_key,
            binding.request_generation, binding.lane_id,
            operation_seq,
            rtcore::v04::conservation::event_name(event));
    fflush(stderr);
    abort();
  }
}

static void rtcore_v04_functional_only_record_warp_or_abort(
    rtcore::v04::conservation::event_kind event,
    const rtcore_v04_functional_only_warp_record &warp,
    unsigned event_warp_uid, unsigned lane_mask) {
  rtcore::v04::conservation::warp_event_v0 record = {};
  record.owner_hw_sid = warp.owner_hw_sid;
  record.warp_uid = event_warp_uid;
  record.warp_id = warp.warp_id;
  record.resident_warp_slot = warp.resident_warp_slot;
  record.resident_generation = warp.resident_generation;
  record.completion_transaction_generation =
      warp.completion_transaction_generation;
  record.active_mask = warp.active_mask;
  record.lane_mask = lane_mask;
  record.event = event;
  if (!rtcore::v04::conservation::emit_warp_event(record)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_CONSERVATION_FAULT "
            "driver=functional_only owner_hw_sid=%u warp_uid=%u "
            "warp_id=%u resident_generation=%u "
            "completion_generation=%u event=%s\n",
            warp.owner_hw_sid, event_warp_uid, warp.warp_id,
            warp.resident_generation,
            warp.completion_transaction_generation,
            rtcore::v04::conservation::event_name(event));
    fflush(stderr);
    abort();
  }
}

static request_owner::allocator_state_v0 &rtcore_v04_functional_only_allocator(
    unsigned owner_hw_sid) {
  request_owner::allocator_state_v0 &allocator =
      g_rtcore_v04_functional_only_owner_allocators[owner_hw_sid];
  if (!allocator.initialized) {
    request_owner::initialize_allocator(&allocator);
  }
  return allocator;
}

static private_frontier::region_binding_v0
rtcore_v04_functional_only_private_region(unsigned owner_hw_sid) {
  private_frontier::region_binding_v0 region = {};
  region.profile_id = private_frontier::kLayoutProfileId;
  region.slot_count = request_owner::kRequestControlCapacity;
  region.private_region_base =
      UINT64_C(0xfe00000000000000) +
      static_cast<uint64_t>(owner_hw_sid) * UINT64_C(0x1000000);
  return region;
}

static bool rtcore_v04_functional_only_read_raw_payload(
    void *opaque,
    const rtcore::v04::typed_blas::as_decode_context_v0 &decode_context,
    uint64_t address, uint16_t byte_count, uint8_t *bytes) {
  ptx_thread_info *thread = static_cast<ptx_thread_info *>(opaque);
  const char *failure = "unvalidated";
  if (thread == NULL || bytes == NULL ||
      !VulkanRayTracing::validateV04TypedPayloadBinding(decode_context, address,
                                                        byte_count, &failure)) {
    return false;
  }
  return thread->get_global_memory()->read_vulkan_buffer(
      static_cast<mem_addr_t>(address), byte_count, bytes);
}

static bool rtcore_v04_functional_only_prepare_instance(
    void *, const rtcore::v04::fetch_target::operation_packet_v0 &packet,
    rtcore::v04::typed_instance::enter_input_v0 *input) {
  const char *failure = "unvalidated";
  return VulkanRayTracing::buildV04TypedInstanceEnterInput(packet, input,
                                                           &failure);
}

static bool rtcore_v04_functional_only_resolve_parent(
    void *,
    const rtcore::v04::typed_blas::as_decode_context_v0 &decode_context,
    uint32_t build_generation, uint64_t payload_offset,
    uint8_t payload_kind,
    rtcore::v04::short_stack::parent_edge_v0 *parent) {
  const char *failure = "unvalidated";
  const bool resolved =
      VulkanRayTracing::resolveV04GenRtReplayParent(
      decode_context, build_generation, payload_offset, payload_kind,
      parent,
      &failure);
  if (!resolved) {
    fprintf(
        stderr,
        "GPGPU-Sim RTCORE_V04_FUNCTIONAL_PARENT_LOOKUP_FAULT "
        "as_type=%u object_id=%llu generation=%u "
        "build_generation=%u payload_offset=0x%llx "
        "payload_kind=%u fault=%s\n",
        static_cast<unsigned>(decode_context.as_object.as_type),
        static_cast<unsigned long long>(
            decode_context.as_object.object_id),
        decode_context.as_object.generation, build_generation,
        static_cast<unsigned long long>(payload_offset),
        static_cast<unsigned>(payload_kind), failure);
    fflush(stderr);
  }
  return resolved;
}

static functional_engine::provider_v0 rtcore_v04_functional_only_provider(
    ptx_thread_info *thread) {
  functional_engine::provider_v0 provider = {};
  provider.context = thread;
  provider.read_raw_payload = rtcore_v04_functional_only_read_raw_payload;
  provider.prepare_instance_enter = rtcore_v04_functional_only_prepare_instance;
  provider.resolve_parent_edge =
      rtcore_v04_functional_only_resolve_parent;
  return provider;
}

static bool rtcore_v04_functional_only_short_stack_enabled() {
  return rtcore_candidate_gate_state_for(
             "VULKAN_SIM_RTCORE_ABI_V04_GENRT_SHORT_STACK_REPLAY") ==
         RTCORE_CANDIDATE_GATE_ENABLED;
}

static bool rtcore_v04_ray_input_debug_enabled() {
  const char *value = getenv("VULKAN_SIM_RTCORE_V04_RAY_INPUT_DEBUG");
  return value != NULL && value[0] != '\0' && strcmp(value, "0") != 0;
}

static uint32_t rtcore_v04_ray_input_debug_bits(float value) {
  uint32_t bits = 0;
  memcpy(&bits, &value, sizeof(bits));
  return bits;
}

static functional_engine::root_input_v0 rtcore_v04_functional_only_root_input(
    const root_node_packet::lane_input_v0 &lane_input,
    const request_owner::lane_binding_v0 &request_binding) {
  functional_engine::root_input_v0 root = {};
  root.owner = request_owner::make_private_frontier_owner(request_binding);
  root.private_region =
      rtcore_v04_functional_only_private_region(root.owner.owner_hw_sid);
  root.root_reference = lane_input.target_reference;
  root.ray_policy = lane_input.ray_policy;
  root.private_operands = lane_input.private_operands;
  root.raw_payload_base_address = lane_input.raw_payload_base_address;
  root.root_build_generation = lane_input.root_build_generation;
  root.short_stack_replay_enabled =
      rtcore_v04_functional_only_short_stack_enabled() ? 1 : 0;
  return root;
}

static bool rtcore_v04_global384_profile_selected(bool *selected);
static bool rtcore_v04_global384_validate_preissued_owner_plan(
    const root_node_packet::warp_input_v0 &input,
    request_owner::new_warp_plan_v0 *plan);
static bool rtcore_v04_global384_consume_preissued_owner_plan(
    const root_node_packet::warp_input_v0 &input);

static bool rtcore_v04_functional_only_prepare_initial(
    const root_node_packet::warp_input_v0 &input,
    ptx_thread_info *const *lane_threads) {
  const rtcore_v04_functional_only_warp_key key =
      std::make_pair(input.owner_hw_sid, input.warp_id);
  if (g_rtcore_v04_functional_only_live_warps.find(key) !=
          g_rtcore_v04_functional_only_live_warps.end() ||
      g_rtcore_v04_functional_only_initial_stages.find(input.warp_uid) !=
          g_rtcore_v04_functional_only_initial_stages.end()) {
    return false;
  }

  request_owner::new_warp_plan_v0 plan = {};
  bool global384 = false;
  if (!rtcore_v04_global384_profile_selected(&global384)) {
    return false;
  }
  if (global384) {
    if (!rtcore_v04_global384_validate_preissued_owner_plan(input, &plan)) {
      return false;
    }
  } else {
    request_owner::allocator_state_v0 &allocator =
        rtcore_v04_functional_only_allocator(input.owner_hw_sid);
    request_owner::warp_identity_v0 identity = {};
    identity.owner_hw_sid = input.owner_hw_sid;
    identity.warp_uid = input.warp_uid;
    identity.warp_id = input.warp_id;
    identity.active_mask = input.active_mask;
    if (request_owner::prepare_new_warp(allocator, identity, &plan) !=
        request_owner::kStatusOk) {
      return false;
    }
  }

  rtcore_v04_functional_only_initial_stage stage;
  stage.valid = true;
  stage.owner_plan_precommitted = global384;
  stage.owner_plan = plan;
  rtcore_v04_functional_only_warp_record &record = stage.record;
  record.valid = true;
  record.owner_hw_sid = input.owner_hw_sid;
  record.warp_uid = input.warp_uid;
  record.warp_id = input.warp_id;
  record.static_inst_uid = input.static_inst_uid;
  record.active_mask = input.active_mask;
  record.bound_lane_mask = input.active_mask;
  record.resident_warp_slot = plan.resident_warp_slot;
  record.completion_transaction_generation = 1;
  for (unsigned lane = 0; lane < kRtcoreV04FunctionalOnlyLaneCapacity; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((input.active_mask & lane_mask) == 0) continue;
    if (lane_threads[lane] == NULL || !input.lanes[lane].valid ||
        !input.lanes[lane].v04_trace_input_valid) {
      return false;
    }
    rtcore_v04_functional_only_lane_record &lane_record = record.lane[lane];
    lane_record.valid = true;
    lane_record.thread_uid = lane_threads[lane]->get_uid();
    lane_record.context_ptr = input.lanes[lane].context_ptr;
    lane_record.handoff_window_base = input.lanes[lane].handoff_window_base;
    lane_record.sbt_record_offset = input.lanes[lane].sbt_record_offset;
    lane_record.sbt_record_stride = input.lanes[lane].sbt_record_stride;
    lane_record.miss_index = input.lanes[lane].miss_index;
    lane_record.trace_input_words = input.lanes[lane].v04_trace_input_words;
    lane_record.request_binding = plan.lane_bindings[lane];
    const functional_engine::root_input_v0 root =
        rtcore_v04_functional_only_root_input(input.lanes[lane],
                                              lane_record.request_binding);
    const functional_engine::status_kind status = functional_engine::run_new(
        root, rtcore_v04_functional_only_provider(lane_threads[lane]),
        &lane_record.engine_state, &lane_record.engine_output);
    if (status != functional_engine::kStatusOk) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_FAULT "
              "phase=initial owner_hw_sid=%u warp_uid=%u warp_id=%u "
              "lane_id=%u status=%s driver_unit=%s driver_status=%s\n",
              input.owner_hw_sid, input.warp_uid, input.warp_id, lane,
              functional_engine::status_name(status),
              functional_engine::driver_unit_name(
                  static_cast<functional_engine::driver_unit_kind>(
                      lane_record.engine_state.last_driver_unit)),
              functional_driver::status_name(
                  static_cast<functional_driver::status_kind>(
                      lane_record.engine_state.last_driver_status)));
      fflush(stderr);
      return false;
    }
  }
  g_rtcore_v04_functional_only_initial_stages.insert(
      std::make_pair(input.warp_uid, stage));
  if (global384 &&
      !rtcore_v04_global384_consume_preissued_owner_plan(input)) {
    g_rtcore_v04_functional_only_initial_stages.erase(input.warp_uid);
    return false;
  }
  printf(
      "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_INITIAL_STAGE "
      "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
      "resident_warp_slot=%u owner_state_committed=%u "
      "timing_state_mutated=0\n",
      input.owner_hw_sid, input.warp_uid, input.warp_id, input.active_mask,
      record.resident_warp_slot, stage.owner_plan_precommitted ? 1u : 0u);
  fflush(stdout);
  return true;
}

static bool rtcore_v04_functional_only_prepare_resubmit(
    const root_node_packet::warp_input_v0 &input,
    ptx_thread_info *const *lane_threads, unsigned previous_warp_uid,
    unsigned previous_active_mask) {
  const rtcore_v04_functional_only_warp_key key =
      std::make_pair(input.owner_hw_sid, input.warp_id);
  std::map<rtcore_v04_functional_only_warp_key,
           rtcore_v04_functional_only_warp_record>::const_iterator live =
      g_rtcore_v04_functional_only_live_warps.find(key);
  if (live == g_rtcore_v04_functional_only_live_warps.end() ||
      !live->second.valid ||
      live->second.warp_uid != previous_warp_uid ||
      live->second.active_mask != previous_active_mask ||
      !live->second.completion_published ||
      !live->second.completion_consumed ||
      input.warp_uid == previous_warp_uid ||
      (input.active_mask & ~previous_active_mask) != 0 ||
      g_rtcore_v04_functional_only_resubmit_stages.find(input.warp_uid) !=
          g_rtcore_v04_functional_only_resubmit_stages.end()) {
    return false;
  }

  request_owner::allocator_state_v0 &allocator =
      rtcore_v04_functional_only_allocator(input.owner_hw_sid);
  rtcore_v04_functional_only_resubmit_stage stage;
  stage.valid = true;
  stage.previous_warp_uid = previous_warp_uid;
  if (request_owner::prepare_mask_shrink(
          allocator, live->second.resident_warp_slot,
          input.owner_hw_sid, previous_warp_uid, input.warp_uid,
          input.warp_id, input.active_mask, &stage.owner_plan) !=
      request_owner::kStatusOk) {
    return false;
  }
  stage.next_record = live->second;
  stage.next_record.warp_uid = input.warp_uid;
  stage.next_record.static_inst_uid = input.static_inst_uid;
  stage.next_record.active_mask = input.active_mask;
  if (stage.next_record.completion_transaction_generation == ~0u) {
    return false;
  }
  stage.next_record.completion_transaction_generation++;
  stage.next_record.completion_published = false;
  stage.next_record.completion_consumed = false;

  for (unsigned lane = 0; lane < kRtcoreV04FunctionalOnlyLaneCapacity;
       ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((input.active_mask & lane_mask) == 0) {
      stage.next_record.lane[lane] =
          rtcore_v04_functional_only_lane_record();
      continue;
    }
    rtcore_v04_functional_only_lane_record &lane_record =
        stage.next_record.lane[lane];
    if (!lane_record.valid || lane_threads[lane] == NULL ||
        !input.lanes[lane].v04_trace_input_valid ||
        lane_record.thread_uid != lane_threads[lane]->get_uid() ||
        lane_record.context_ptr != input.lanes[lane].context_ptr ||
        lane_record.handoff_window_base !=
            input.lanes[lane].handoff_window_base) {
      return false;
    }
    const uint32_t trace_input_mask =
        rtcore::abi_v04::shadow::trace_input_owned_word_mask();
    for (unsigned word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
      if ((trace_input_mask & (uint32_t{1} << word)) != 0 &&
          lane_record.trace_input_words[word] !=
              input.lanes[lane].v04_trace_input_words[word]) {
        return false;
      }
    }
    lane_record.request_binding = stage.owner_plan.lane_bindings[lane];
    lane_record.initial_output_consumed = false;
    lane_record.completion_words_valid = false;
    lane_record.completion_words.fill(0);
    std::array<uint32_t, rtcore::abi_v04::kWordCount>
        shader_return_words = {};
    const uint64_t lane_slot_base =
        lane_record.handoff_window_base +
        static_cast<uint64_t>(lane) * rtcore::abi_v04::kLaneSlotBytes;
    lane_threads[lane]->get_global_memory()->read_simulator_backing(
        static_cast<mem_addr_t>(lane_slot_base),
        sizeof(shader_return_words), shader_return_words.data());
    const functional_engine::status_kind status =
        functional_engine::resume(
            &lane_record.engine_state,
            lane_record.engine_state.boundary_reason,
            shader_return_words,
            rtcore_v04_functional_only_provider(lane_threads[lane]),
            &lane_record.engine_output);
    if (status != functional_engine::kStatusOk) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_FAULT "
              "phase=resubmit owner_hw_sid=%u previous_warp_uid=%u "
              "warp_uid=%u warp_id=%u lane_id=%u status=%s "
              "driver_unit=%s driver_status=%s\n",
              input.owner_hw_sid, previous_warp_uid, input.warp_uid,
              input.warp_id, lane,
              functional_engine::status_name(status),
              functional_engine::driver_unit_name(
                  static_cast<functional_engine::driver_unit_kind>(
                      lane_record.engine_state.last_driver_unit)),
              functional_driver::status_name(
                  static_cast<functional_driver::status_kind>(
                      lane_record.engine_state.last_driver_status)));
      fflush(stderr);
      return false;
    }
  }
  g_rtcore_v04_functional_only_resubmit_stages.insert(
      std::make_pair(input.warp_uid, stage));
  printf("GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_RESUBMIT_STAGE "
         "owner_hw_sid=%u previous_warp_uid=%u warp_uid=%u warp_id=%u "
         "previous_active_mask=0x%08x next_active_mask=0x%08x "
         "timing_state_mutated=0\n",
         input.owner_hw_sid, previous_warp_uid, input.warp_uid,
         input.warp_id, previous_active_mask, input.active_mask);
  fflush(stdout);
  return true;
}

}  // namespace

namespace {
static bool rtcore_v04_global384_profile_selected(bool *selected) {
  if (selected == NULL) return false;
  rtcore::v04::private_storage::profile_kind profile =
      rtcore::v04::private_storage::kProfileLegacyShared832;
  const rtcore::v04::private_storage::status_kind status =
      rtcore::v04::private_storage::process_profile(&profile);
  if (status != rtcore::v04::private_storage::kStatusOk) return false;
  *selected = profile == rtcore::v04::private_storage::kProfileGlobal384;
  return true;
}
}

extern "C" bool rtcore_prepare_v04_root_node_packet_before_functional(
    const ptx_instruction *instruction, ptx_thread_info *const *lane_threads,
    unsigned owner_hw_sid, unsigned warp_uid, unsigned dynamic_warp_id,
    unsigned warp_id, unsigned active_mask, unsigned long long issue_cycle) {
  namespace root_packet = rtcore::v04::root_node_packet;
  namespace private_frontier = rtcore::v04::private_frontier;
  namespace fetch_target = rtcore::v04::fetch_target;
  namespace functional_driver = rtcore::v04::functional_driver;
  namespace result_semantic = rtcore::v04::result_semantic;
  namespace typed_blas = rtcore::v04::typed_blas;
  namespace typed_node = rtcore::v04::typed_node;
  if (!rtcore_v04_root_node_input_gate_active()) {
    return true;
  }
  if (!rtcore_v04_functional_node_driver_configuration_valid()) return false;
  if (instruction == NULL || lane_threads == NULL || active_mask == 0 ||
      instruction->op != RT_CORE_OP ||
      instruction->rt_subop != RT_CORE_SUBOP_SUBMIT ||
      instruction->get_num_operands() != 3) {
    return false;
  }

  unsigned previous_warp_uid = 0;
  unsigned previous_active_mask = 0;
  unsigned resident_generation = 0;
  unsigned resident_occupancy = 0;
  const bool functional_only =
      rtcore_v04_functional_only_engine_gate_active();
  const bool resident_live =
      (rtcore_v04_continuation_lifecycle_gate_active() ||
       functional_only) &&
      rtcore_query_resident_rt_warp_record(
          owner_hw_sid, warp_id, &previous_warp_uid,
          &previous_active_mask, &resident_generation,
          &resident_occupancy);
  const bool global384_preissued_initial =
      resident_live &&
      warp_uid == previous_warp_uid && active_mask == previous_active_mask &&
      rtcore_validate_v04_global384_resident_warp_shell(
          owner_hw_sid, warp_uid, warp_id, active_mask,
          instruction->uid(), resident_generation);
  bool global384_profile = false;
  if (!rtcore_v04_global384_profile_selected(&global384_profile)) {
    return false;
  }
  if (resident_live && !functional_only && !global384_preissued_initial) {
    const bool retained_resubmit =
        warp_uid != previous_warp_uid &&
        (active_mask & ~previous_active_mask) == 0;
    printf("GPGPU-Sim RTCORE_V04_ROOT_PACKET_PREFUNCTIONAL_ROUTE "
           "owner_hw_sid=%u previous_warp_uid=%u warp_uid=%u "
           "warp_id=%u previous_active_mask=0x%08x "
           "next_active_mask=0x%08x resident_generation=%u "
           "resident_occupancy=%u route=%s\n",
           owner_hw_sid, previous_warp_uid, warp_uid, warp_id,
           previous_active_mask, active_mask, resident_generation,
           resident_occupancy,
           retained_resubmit ? "retained_state_resubmit"
                             : "invalid_resident_collision");
    fflush(stdout);
    return retained_resubmit;
  }
  if (resident_live && !global384_preissued_initial &&
      (warp_uid == previous_warp_uid ||
       (active_mask & ~previous_active_mask) != 0)) {
    return false;
  }
  const bool global384_resubmit =
      global384_profile && resident_live && functional_only &&
      !global384_preissued_initial && warp_uid != previous_warp_uid &&
      active_mask != 0 && (active_mask & ~previous_active_mask) == 0;
  if (global384_resubmit) {
    if (!rtcore_validate_v04_global384_resubmit_live_before_functional(
            instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
            previous_warp_uid, warp_uid, warp_id, previous_active_mask,
            active_mask, resident_generation) ||
        !rtcore_consume_v04_global384_resubmit_handoff_acquire_before_functional(
            owner_hw_sid, dynamic_warp_id, previous_warp_uid, warp_id,
            previous_active_mask, active_mask, resident_generation,
            warp_uid)) {
      return false;
    }
  }
  if (global384_preissued_initial &&
      !rtcore_validate_v04_global384_first_submit_live_bind_before_functional(
          instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
          warp_uid, warp_id, active_mask)) {
    return false;
  }
  if (global384_preissued_initial) {
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_FIRST_SUBMIT_PREFUNCTIONAL "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
           "resident_generation=%u live_bind=validated "
           "initial_handoff_acquire=validated input_source=l1d_response_bytes "
           "result=ready\n",
           owner_hw_sid, warp_uid, warp_id, active_mask,
           resident_generation);
    fflush(stdout);
  }

  root_packet::warp_input_v0 input = {};
  input.valid = true;
  input.owner_hw_sid = owner_hw_sid;
  input.warp_uid = warp_uid;
  input.warp_id = warp_id;
  input.static_inst_uid = instruction->uid();
  input.active_mask = active_mask;
  const operand_info &context_operand = instruction->operand_lookup(1);
  const operand_info &handoff_operand = instruction->operand_lookup(2);

  for (unsigned lane = 0; lane < root_packet::kLaneCapacity; ++lane) {
    if ((active_mask & (1u << lane)) == 0) continue;
    ptx_thread_info *thread = lane_threads[lane];
    if (thread == NULL) return false;
    const ptx_reg_t context_value = thread->get_operand_value(
        context_operand, context_operand, B64_TYPE, thread, 1);
    const ptx_reg_t handoff_value = thread->get_operand_value(
        handoff_operand, handoff_operand, B64_TYPE, thread, 1);
    rtcore_v03_compact_context_decoded context;
    if (context_value.u64 == 0 || handoff_value.u64 == 0 ||
        (context_value.u64 & 63u) != 0 ||
        (handoff_value.u64 & 127u) != 0 ||
        !rtcore_decode_v03_compact_context_image(
            instruction, thread, context_value.u64, &context)) {
      return false;
    }

    root_packet::lane_input_v0 &lane_input = input.lanes[lane];
    lane_input.valid = true;
    lane_input.lane_id = static_cast<uint8_t>(lane);
    lane_input.thread_uid = thread->get_uid();
    lane_input.context_ptr = context_value.u64;
    lane_input.handoff_window_base = handoff_value.u64;
    rtcore::abi_v04::shadow::trace_input_values retained_trace_input = {};
    bool retained_trace_input_authority = false;
    if (functional_only || global384_preissued_initial) {
      std::array<uint8_t, rtcore::abi_v04::kLaneSlotBytes>
          acquired_handoff_image = {};
      const unsigned char *acquired_handoff_bytes = NULL;
      unsigned acquired_handoff_byte_count = 0;
      if (global384_preissued_initial) {
        if (!rtcore_copy_v04_global384_initial_handoff_acquire_lane_before_functional(
                owner_hw_sid, dynamic_warp_id, warp_uid, warp_id,
                active_mask, resident_generation, lane,
                acquired_handoff_image.data(), acquired_handoff_image.size())) {
          return false;
        }
        acquired_handoff_bytes = acquired_handoff_image.data();
        acquired_handoff_byte_count = acquired_handoff_image.size();
      }
      lane_input.v04_trace_input_valid =
          rtcore_validate_v04_shadow_trace_input(
              instruction, thread, context_value.u64,
              handoff_value.u64, lane, context, owner_hw_sid,
              dynamic_warp_id, warp_uid, warp_id, resident_generation,
              acquired_handoff_bytes,
              acquired_handoff_byte_count,
              &lane_input.v04_trace_input_words);
      if (!lane_input.v04_trace_input_valid) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_ROOT_PACKET_INPUT_FAULT "
                "reason=V04_SHADOW_TRACE_INPUT_MISMATCH "
                "phase=root_prefunctional owner_hw_sid=%u warp_uid=%u "
                "warp_id=%u lane=%u traversal_consumed=0\n",
                owner_hw_sid, warp_uid, warp_id, lane);
        fflush(stderr);
        return false;
      }
      if (global384_preissued_initial) {
        if (!rtcore::abi_v04::shadow::unpack_trace_input_words(
                lane_input.v04_trace_input_words,
                &retained_trace_input)) {
          return false;
        }
        retained_trace_input_authority = true;
      }
    }

    const uint64_t effective_traversable_reference =
        retained_trace_input_authority
            ? retained_trace_input.traversable_reference
            : context.as_handle_or_traversable_ref;
    const float effective_ray_origin[3] = {
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.world_ray_origin_fp32[0])
            : context.ray_origin.x,
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.world_ray_origin_fp32[1])
            : context.ray_origin.y,
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.world_ray_origin_fp32[2])
            : context.ray_origin.z,
    };
    const float effective_ray_direction[3] = {
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.world_ray_direction_fp32[0])
            : context.ray_direction.x,
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.world_ray_direction_fp32[1])
            : context.ray_direction.y,
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.world_ray_direction_fp32[2])
            : context.ray_direction.z,
    };
    const float effective_ray_tmin =
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(retained_trace_input.ray_tmin_fp32)
            : context.ray_tmin;
    const float effective_ray_tmax =
        retained_trace_input_authority
            ? rtcore_context_u32_to_float(
                  retained_trace_input.launch_ray_tmax_fp32)
            : context.ray_tmax;
    lane_input.sbt_record_offset =
        retained_trace_input_authority
            ? retained_trace_input.sbt_record_offset
            : context.sbt_offset;
    lane_input.sbt_record_stride =
        retained_trace_input_authority
            ? retained_trace_input.sbt_record_stride
            : context.sbt_stride;
    lane_input.miss_index = retained_trace_input_authority
                                ? retained_trace_input.miss_index
                                : context.miss_index;

    rtcore_tlas_binding_snapshot tlas = {};
    const char *capture_failure = "unvalidated";
    if (!VulkanRayTracing::captureTlasBinding(
            effective_traversable_reference, &tlas,
            &capture_failure) ||
        !tlas.valid || !tlas.live || !tlas.root_descriptor_valid ||
        tlas.root_build_generation == 0 ||
        tlas.root_bvh_profile_id != typed_blas::kGenRtDerivedProfileId ||
        tlas.root_payload_format_id != typed_blas::kGenRtPayloadFormatId ||
        tlas.root_payload_kind != typed_blas::kInternalPayloadKind ||
        tlas.root_payload_offset > tlas.size_bytes ||
        uint64_t{64} > tlas.size_bytes - tlas.root_payload_offset ||
        tlas.device_base_address >
            UINT64_MAX - tlas.root_payload_offset) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_ROOT_PACKET_INPUT_FAULT "
              "reason=%s owner_hw_sid=%u warp_uid=%u warp_id=%u lane=%u "
              "as_ref=0x%llx\n",
              capture_failure, owner_hw_sid, warp_uid, warp_id, lane,
              (unsigned long long)effective_traversable_reference);
      fflush(stderr);
      return false;
    }

    lane_input.raw_payload_base_address =
        tlas.device_base_address + tlas.root_payload_offset;
    lane_input.root_build_generation =
        tlas.root_build_generation;
    lane_input.target_reference.payload_offset =
        tlas.root_payload_offset;
    memcpy(&lane_input.target_reference.near_t_bits, &effective_ray_tmin,
           sizeof(effective_ray_tmin));
    lane_input.target_reference.build_generation =
        tlas.root_build_generation;
    lane_input.target_reference.payload_byte_count = 64;
    lane_input.target_reference.payload_kind = tlas.root_payload_kind;
    lane_input.target_reference.level = typed_node::kLevelTlas;
    lane_input.target_reference.source_kind =
        fetch_target::kTargetReferenceRootCompatibilityProxy;
    lane_input.target_reference.proxy_delegated = 1;

    private_frontier::root_private_operands_v0 &operands =
        lane_input.private_operands;
    operands.mutable_ray.origin[0] = effective_ray_origin[0];
    operands.mutable_ray.origin[1] = effective_ray_origin[1];
    operands.mutable_ray.origin[2] = effective_ray_origin[2];
    operands.mutable_ray.direction[0] = effective_ray_direction[0];
    operands.mutable_ray.direction[1] = effective_ray_direction[1];
    operands.mutable_ray.direction[2] = effective_ray_direction[2];
    for (unsigned axis = 0; axis < 3; ++axis) {
      const float direction = operands.mutable_ray.direction[axis];
      operands.mutable_ray.inverse_direction[axis] =
          rtcore::v04::canonical_ray::inverse_direction(direction);
    }
    operands.mutable_ray.t_min = effective_ray_tmin;
    operands.mutable_ray.t_max = effective_ray_tmax;
    operands.decode_context.bvh_format_profile_id =
        tlas.root_bvh_profile_id;
    operands.decode_context.as_object.object_id = tlas.object_id;
    operands.decode_context.as_object.generation = tlas.generation;
    operands.decode_context.as_object.as_type = 1;
    operands.decode_context.device_base = tlas.device_base_address;
    operands.decode_context.device_range_bytes = tlas.size_bytes;
    operands.committed_hit.valid = 0;
    lane_input.ray_policy.ray_flags = retained_trace_input_authority
                                          ? retained_trace_input.ray_flags
                                          : context.ray_flags;
    lane_input.ray_policy.cull_mask =
        static_cast<uint8_t>(retained_trace_input_authority
                                 ? retained_trace_input.cull_mask
                                 : context.cull_mask);
    if (rtcore_v04_ray_input_debug_enabled()) {
      printf(
          "GPGPU-Sim RTCORE_V04_RAY_INPUT_DEBUG "
          "phase=%s owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
          "thread_uid=%u context_ptr=0x%llx "
          "origin=(%.9g,%.9g,%.9g) direction=(%.9g,%.9g,%.9g) "
          "tmin=%.9g tmax=%.9g "
          "origin_bits=(0x%08x,0x%08x,0x%08x) "
          "direction_bits=(0x%08x,0x%08x,0x%08x) "
          "tmin_bits=0x%08x tmax_bits=0x%08x\n",
          global384_preissued_initial
              ? "initial_l1d_authority"
              : (resident_live ? "resubmit" : "initial"),
          owner_hw_sid,
          warp_uid, warp_id, lane, thread->get_uid(),
          (unsigned long long)context_value.u64,
          operands.mutable_ray.origin[0], operands.mutable_ray.origin[1],
          operands.mutable_ray.origin[2],
          operands.mutable_ray.direction[0],
          operands.mutable_ray.direction[1],
          operands.mutable_ray.direction[2],
          operands.mutable_ray.t_min, operands.mutable_ray.t_max,
          rtcore_v04_ray_input_debug_bits(operands.mutable_ray.origin[0]),
          rtcore_v04_ray_input_debug_bits(operands.mutable_ray.origin[1]),
          rtcore_v04_ray_input_debug_bits(operands.mutable_ray.origin[2]),
          rtcore_v04_ray_input_debug_bits(
              operands.mutable_ray.direction[0]),
          rtcore_v04_ray_input_debug_bits(
              operands.mutable_ray.direction[1]),
          rtcore_v04_ray_input_debug_bits(
              operands.mutable_ray.direction[2]),
          rtcore_v04_ray_input_debug_bits(operands.mutable_ray.t_min),
          rtcore_v04_ray_input_debug_bits(operands.mutable_ray.t_max));
      fflush(stdout);
    }
  }

  if (functional_only) {
    const bool prepared =
        resident_live && !global384_preissued_initial
            ? rtcore_v04_functional_only_prepare_resubmit(
                  input, lane_threads, previous_warp_uid,
                  previous_active_mask)
            : rtcore_v04_functional_only_prepare_initial(input, lane_threads);
    return prepared;
  }

  if (rtcore_v04_functional_node_driver_gate_active()) {
    for (unsigned lane = 0; lane < root_packet::kLaneCapacity; ++lane) {
      if ((active_mask & (1u << lane)) == 0) continue;
      ptx_thread_info *thread = lane_threads[lane];
      const root_packet::lane_input_v0 &lane_input = input.lanes[lane];
      fetch_target::reservation_input_v0 packet_input = {};
      packet_input.owner.owner_hw_sid = owner_hw_sid;
      packet_input.owner.resident_warp_id = warp_id;
      packet_input.owner.request_identity = lane_input.thread_uid;
      packet_input.owner.generation = 1;
      packet_input.owner.private_slot_id = lane;
      packet_input.owner.lane_id = static_cast<uint8_t>(lane);
      packet_input.target_reference = lane_input.target_reference;
      packet_input.forwarded_ray_policy = lane_input.ray_policy;
      packet_input.raw_payload_base_address =
          lane_input.raw_payload_base_address;
      packet_input.target_operation_seq = 1;
      packet_input.raw_payload_bytes =
          fetch_target::kNodeRawPayloadBytes;
      packet_input.target_kind = fetch_target::kTargetNode;
      packet_input.required_operand_mask = static_cast<uint8_t>(
          fetch_target::kOperandTargetReferenceValid |
          fetch_target::kOperandRawPayloadValid |
          fetch_target::kOperandMutableRayValid |
          fetch_target::kOperandRayPolicyValid |
          fetch_target::kOperandDecodeContextValid |
          fetch_target::kOperandCommittedHitValid);
      packet_input.forwarded_operand_mask =
          fetch_target::kOperandRayPolicyValid;

      uint8_t raw_payload[fetch_target::kNodeRawPayloadBytes] = {};
      thread->get_global_memory()->read_simulator_backing(
          static_cast<mem_addr_t>(lane_input.raw_payload_base_address),
          sizeof(raw_payload), raw_payload);
      fetch_target::operation_packet_v0 packet = {};
      const uint64_t local_identity =
          (static_cast<uint64_t>(warp_uid) << 6) |
          static_cast<uint64_t>(lane + 1);
      const fetch_target::status_kind packet_status =
          fetch_target::build_ready_node_operation_packet(
              packet_input, local_identity, local_identity, 1,
              lane_input.private_operands, raw_payload, &packet);
      functional_driver::node_execution_v0 execution = {};
      const functional_driver::status_kind driver_status =
          packet_status == fetch_target::kStatusOk
              ? functional_driver::execute_one_node(packet, &execution)
              : functional_driver::kStatusInvalidOperationPacket;
      if (driver_status != functional_driver::kStatusOk ||
          !execution.valid ||
          execution.operator_invocation_count != 1 ||
          !result_semantic::validate_node_commit_plan(
              execution.semantic_plan, packet,
              execution.operator_result)) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_FUNCTIONAL_NODE_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                "packet_status=%s driver_status=%s invocations=%u\n",
                owner_hw_sid, warp_uid, warp_id, lane,
                fetch_target::status_name(packet_status),
                functional_driver::status_name(driver_status),
                execution.operator_invocation_count);
        fflush(stderr);
        return false;
      }
      printf("GPGPU-Sim RTCORE_V04_FUNCTIONAL_NODE_ROUTE "
             "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
             "packet_reservation_id=%llu target_operation_seq=%u "
             "operator_invocations=1 route=%s next_target=%u "
             "frontier_count=%u timing_state_mutated=0 "
             "legacy_authority=0\n",
             owner_hw_sid, warp_uid, warp_id, lane,
             (unsigned long long)packet.reservation_id,
             packet.target_operation_seq,
             result_semantic::node_route_name(
                 static_cast<result_semantic::node_route_kind>(
                     execution.semantic_plan.route_kind)),
             execution.semantic_plan.next_target_kind,
             execution.semantic_plan.frontier_count);
      fflush(stdout);
    }
    return true;
  }

  const char *failure_reason = "unvalidated";
  if (!rtcore_admit_v04_root_node_packet(
          &input, issue_cycle, &failure_reason)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_ROOT_PACKET_ADMISSION_FAULT "
            "reason=%s owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "active_mask=0x%08x\n",
            failure_reason != NULL ? failure_reason : "unknown",
            owner_hw_sid, warp_uid, warp_id, active_mask);
    fflush(stderr);
    return false;
  }
  if (global384_preissued_initial &&
      !rtcore_v04_global384_consume_preissued_owner_plan(input)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_ROOT_PACKET_ADMISSION_FAULT "
            "reason=GLOBAL384_PREISSUED_PLAN_CONSUME_FAILED "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "active_mask=0x%08x\n",
            owner_hw_sid, warp_uid, warp_id, active_mask);
    fflush(stderr);
    return false;
  }
  return true;
}

extern "C" bool rtcore_finalize_v04_root_node_packet_after_functional(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask) {
  if (!rtcore_v04_functional_only_engine_gate_active()) {
    return true;
  }
  std::map<unsigned, rtcore_v04_functional_only_initial_stage>::iterator stage =
      g_rtcore_v04_functional_only_initial_stages.find(warp_uid);
  if (stage == g_rtcore_v04_functional_only_initial_stages.end()) {
    return true;
  }
  const rtcore_v04_functional_only_warp_record &record = stage->second.record;
  const unsigned finalized_lane_mask = stage->second.finalized_lane_mask;
  const bool identity_matches =
      stage->second.valid && record.valid &&
      record.owner_hw_sid == owner_hw_sid && record.warp_uid == warp_uid &&
      record.warp_id == warp_id && record.active_mask == active_mask;
  printf(
      "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_INITIAL_STAGE_DISCARD "
      "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
      "finalized_lane_mask=0x%08x identity_matches=%u "
      "owner_state_committed=0 timing_state_mutated=0\n",
      owner_hw_sid, warp_uid, warp_id, active_mask, finalized_lane_mask,
      identity_matches ? 1u : 0u);
  fflush(stdout);
  g_rtcore_v04_functional_only_initial_stages.erase(stage);
  return false;
}

static std::map<ptx_thread_info *,
                rtcore_trace_invocation_publication_source_shadow>
    g_rtcore_trace_invocation_publication_source_shadow;
static unsigned long long
    g_rtcore_trace_invocation_publication_source_next_seq = 0;

static bool rtcore_env_flag_enabled(const char *name) {
  const char *value = getenv(name);
  return value != NULL && value[0] != '\0' && strcmp(value, "0") != 0;
}

enum rtcore_path_mode_policy {
  RTCORE_PATH_MODE_POLICY_CUSTOM = 0,
  RTCORE_PATH_MODE_POLICY_LEGACY,
  RTCORE_PATH_MODE_POLICY_INVALID,
};

static char rtcore_ascii_lower(char value) {
  return value >= 'A' && value <= 'Z' ? value - 'A' + 'a' : value;
}

static bool rtcore_path_mode_is(const char *mode, const char *value) {
  if (mode == NULL || value == NULL) {
    return false;
  }
  while (*mode != '\0' && *value != '\0') {
    if (rtcore_ascii_lower(*mode) != rtcore_ascii_lower(*value)) {
      return false;
    }
    ++mode;
    ++value;
  }
  return *mode == '\0' && *value == '\0';
}

static bool rtcore_rt_env_value_is_explicit_false(const char *value) {
  return value != NULL && value[0] != '\0' &&
         (strcmp(value, "0") == 0 || rtcore_path_mode_is(value, "false") ||
          rtcore_path_mode_is(value, "off") ||
          rtcore_path_mode_is(value, "no") ||
          rtcore_path_mode_is(value, "disabled") ||
          rtcore_path_mode_is(value, "disable") ||
          rtcore_path_mode_is(value, "deny") ||
          rtcore_path_mode_is(value, "denied"));
}

static bool rtcore_rt_env_value_is_explicit_true(const char *value) {
  return value != NULL && value[0] != '\0' &&
         (strcmp(value, "1") == 0 || rtcore_path_mode_is(value, "true") ||
          rtcore_path_mode_is(value, "on") ||
          rtcore_path_mode_is(value, "yes") ||
          rtcore_path_mode_is(value, "allow") ||
          rtcore_path_mode_is(value, "allowed") ||
          rtcore_path_mode_is(value, "enabled") ||
          rtcore_path_mode_is(value, "enable") ||
          rtcore_path_mode_is(value, "default"));
}

enum rtcore_v04_shadow_gate_state {
  RTCORE_V04_SHADOW_GATE_DISABLED = 0,
  RTCORE_V04_SHADOW_GATE_ENABLED,
  RTCORE_V04_SHADOW_GATE_INVALID,
};

static rtcore_v04_shadow_gate_state rtcore_v04_shadow_gate(const char *name) {
  const rtcore_candidate_gate_state state =
      rtcore_candidate_gate_state_for(name);
  if (state == RTCORE_CANDIDATE_GATE_DISABLED) {
    return RTCORE_V04_SHADOW_GATE_DISABLED;
  }
  if (state == RTCORE_CANDIDATE_GATE_ENABLED) {
    return RTCORE_V04_SHADOW_GATE_ENABLED;
  }
  return RTCORE_V04_SHADOW_GATE_INVALID;
}

static const char *rtcore_v04_shadow_publication_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_PUBLICATION";
}

static const char *rtcore_v04_shadow_consumer_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_CONSUMER";
}

static const char *rtcore_v04_shadow_boundary_publication_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_BOUNDARY_PUBLICATION";
}

static const char *rtcore_v04_live_handoff_publication_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_LIVE_HANDOFF_PUBLICATION";
}

static const char *rtcore_v04_tlas_binding_enforcement_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_TLAS_BINDING_ENFORCEMENT";
}

static const char *rtcore_v04_shadow_shader_return_publication_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_SHADER_RETURN_PUBLICATION";
}

static const char *rtcore_v04_shadow_shader_return_consumer_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_SHADER_RETURN_CONSUMER";
}

static const char *rtcore_v04_functional_shader_return_authority_gate_name() {
  return "VULKAN_SIM_RTCORE_ABI_V04_FUNCTIONAL_SHADER_RETURN_AUTHORITY";
}

static bool rtcore_v04_functional_only_configuration_valid(
    const ptx_instruction *pI, bool shadow_consumer_enabled,
    bool boundary_publication_enabled, bool live_publication_enabled,
    bool tlas_binding_enforcement_enabled) {
  if (!rtcore_v04_functional_only_engine_gate_active()) {
    return true;
  }

  static const char *const required_gates[] = {
      "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_PUBLICATION",
      "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_SHADER_RETURN_PUBLICATION",
      "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_SHADER_RETURN_CONSUMER",
      "VULKAN_SIM_RTCORE_ABI_V04_FUNCTIONAL_SHADER_RETURN_AUTHORITY",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_NODE_CANDIDATE_KERNEL",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_NODE_CHILD_ROUTE_KERNEL",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_STACK_PUSH_REMAINDER_KERNEL",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_STACK_POP_NEXT_KERNEL",
      "VULKAN_SIM_RTCORE_ABI_V04_PRIVATE_FRONTIER_OWNER_LAYOUT",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_INSTANCE_BOUNDARY_SEED",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_BLAS_DECODE_CONTEXT_BRIDGE",
      "VULKAN_SIM_RTCORE_ABI_V04_PRODUCER_BACKED_BLAS_ROOT_DESCRIPTOR",
      "VULKAN_SIM_RTCORE_ABI_V04_PRODUCER_BACKED_INSTANCE_BLAS_REFERENCE_TABLE",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_INSTANCE_ENTER_TRANSITION_KERNEL",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_PRIMITIVE_CANDIDATE_KERNEL",
      "VULKAN_SIM_RTCORE_ABI_V04_TYPED_PROCEDURAL_BOUNDARY_SEED",
      "VULKAN_SIM_RTCORE_ABI_V04_SHADER_BUILTIN_CONSUMER",
  };
  const char *reason = NULL;
  const char *failed_gate = "none";
  for (unsigned i = 0;
       i < sizeof(required_gates) / sizeof(required_gates[0]); ++i) {
    const rtcore_candidate_gate_state state =
        rtcore_candidate_gate_state_for(required_gates[i]);
    if (state != RTCORE_CANDIDATE_GATE_ENABLED) {
      failed_gate = required_gates[i];
      reason = state == RTCORE_CANDIDATE_GATE_INVALID
                   ? "V04_FUNCTIONAL_ONLY_REQUIRED_GATE_INVALID"
                   : "V04_FUNCTIONAL_ONLY_REQUIRED_GATE_DISABLED";
      break;
    }
  }
  if (reason == NULL &&
      (!shadow_consumer_enabled || !boundary_publication_enabled ||
       !live_publication_enabled || !tlas_binding_enforcement_enabled)) {
    reason = "V04_FUNCTIONAL_ONLY_PUBLIC_ABI_CHAIN_INCOMPLETE";
  }
  const rtcore_candidate_gate_state request_owner_state =
      rtcore_candidate_gate_state_for(
          "VULKAN_SIM_RTCORE_ABI_V04_REQUEST_OWNER_BINDING");
  const rtcore_candidate_gate_state private_live_init_state =
      rtcore_candidate_gate_state_for(
          "VULKAN_SIM_RTCORE_ABI_V04_PRIVATE_FRONTIER_LIVE_INIT");
  if (reason == NULL &&
      (request_owner_state != RTCORE_CANDIDATE_GATE_DISABLED ||
       private_live_init_state != RTCORE_CANDIDATE_GATE_DISABLED)) {
    reason = request_owner_state == RTCORE_CANDIDATE_GATE_INVALID ||
                     private_live_init_state ==
                         RTCORE_CANDIDATE_GATE_INVALID
                 ? "V04_FUNCTIONAL_ONLY_TIMING_OWNERSHIP_GATE_INVALID"
                 : "V04_FUNCTIONAL_ONLY_TIMING_OWNERSHIP_CONFLICT";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "failed_gate=%s, shadow_consumer=%u, boundary_publication=%u, "
         "live_publication=%u, tlas_binding=%u, "
         "request_owner_binding=%u, private_frontier_live_init=%u\n",
         pI->source_file(), pI->source_line(), reason, failed_gate,
         shadow_consumer_enabled ? 1u : 0u,
         boundary_publication_enabled ? 1u : 0u,
         live_publication_enabled ? 1u : 0u,
         tlas_binding_enforcement_enabled ? 1u : 0u,
         request_owner_state == RTCORE_CANDIDATE_GATE_ENABLED ? 1u : 0u,
         private_live_init_state == RTCORE_CANDIDATE_GATE_ENABLED ? 1u
                                                                  : 0u);
  fflush(stdout);
  return false;
}

static bool rtcore_v04_shadow_consumer_configuration_valid(
    const ptx_instruction *pI, bool *consumer_enabled) {
  const rtcore_v04_shadow_gate_state consumer_state =
      rtcore_v04_shadow_gate(rtcore_v04_shadow_consumer_gate_name());
  const rtcore_v04_shadow_gate_state publication_state =
      rtcore_v04_shadow_gate(rtcore_v04_shadow_publication_gate_name());
  if (consumer_enabled != NULL) {
    *consumer_enabled = consumer_state == RTCORE_V04_SHADOW_GATE_ENABLED;
  }
  const char *reason = NULL;
  if (consumer_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_SHADOW_CONSUMER_GATE_INVALID";
  } else if (consumer_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             publication_state != RTCORE_V04_SHADOW_GATE_ENABLED) {
    reason = publication_state == RTCORE_V04_SHADOW_GATE_INVALID
                 ? "V04_SHADOW_PUBLICATION_GATE_INVALID"
                 : "V04_SHADOW_PUBLICATION_GATE_REQUIRED";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "consumer_gate=%s, publication_gate=%s\n",
         pI->source_file(), pI->source_line(), reason,
         getenv(rtcore_v04_shadow_consumer_gate_name()) != NULL
             ? getenv(rtcore_v04_shadow_consumer_gate_name())
             : "<unset>",
         getenv(rtcore_v04_shadow_publication_gate_name()) != NULL
             ? getenv(rtcore_v04_shadow_publication_gate_name())
             : "<unset>");
  fflush(stdout);
  return false;
}

static bool rtcore_v04_shadow_boundary_publication_configuration_valid(
    const ptx_instruction *pI, bool shadow_consumer_enabled,
    bool *boundary_publication_enabled) {
  const rtcore_v04_shadow_gate_state boundary_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_shadow_boundary_publication_gate_name());
  if (boundary_publication_enabled != NULL) {
    *boundary_publication_enabled =
        boundary_state == RTCORE_V04_SHADOW_GATE_ENABLED;
  }
  const char *reason = NULL;
  if (boundary_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_SHADOW_BOUNDARY_PUBLICATION_GATE_INVALID";
  } else if (boundary_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !shadow_consumer_enabled) {
    reason = "V04_SHADOW_TRACE_INPUT_CONSUMER_REQUIRED";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "boundary_publication_gate=%s, shadow_consumer_enabled=%u\n",
         pI->source_file(), pI->source_line(), reason,
         getenv(rtcore_v04_shadow_boundary_publication_gate_name()) != NULL
             ? getenv(rtcore_v04_shadow_boundary_publication_gate_name())
             : "<unset>",
         shadow_consumer_enabled ? 1u : 0u);
  fflush(stdout);
  return false;
}

static bool rtcore_v04_live_handoff_publication_configuration_valid(
    const ptx_instruction *pI, bool boundary_publication_enabled,
    bool *live_publication_enabled) {
  const rtcore_v04_shadow_gate_state live_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_live_handoff_publication_gate_name());
  if (live_publication_enabled != NULL) {
    *live_publication_enabled =
        live_state == RTCORE_V04_SHADOW_GATE_ENABLED;
  }
  const bool memory_path_enabled =
      rtcore_env_flag_enabled(
          "VULKAN_SIM_RTCORE_REPLAY_MEMORY_UNIT_REQUEST_OFFER") &&
      rtcore_env_flag_enabled(
          "VULKAN_SIM_RTCORE_REPLAY_MEMORY_UNIT_L1D_CLIENT") &&
      rtcore_env_flag_enabled(
          "VULKAN_SIM_RTCORE_REPLAY_MEMORY_UNIT_RESPONSE_WAIT");
  const char *reason = NULL;
  if (live_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_LIVE_HANDOFF_PUBLICATION_GATE_INVALID";
  } else if (live_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !boundary_publication_enabled) {
    reason = "V04_SHADOW_BOUNDARY_PUBLICATION_REQUIRED";
  } else if (live_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !memory_path_enabled) {
    reason = "V04_LIVE_HANDOFF_MEMORY_UNIT_PATH_REQUIRED";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "live_handoff_publication_gate=%s, "
         "boundary_publication_enabled=%u, memory_path_enabled=%u\n",
         pI->source_file(), pI->source_line(), reason,
         getenv(rtcore_v04_live_handoff_publication_gate_name()) != NULL
             ? getenv(rtcore_v04_live_handoff_publication_gate_name())
             : "<unset>",
         boundary_publication_enabled ? 1u : 0u,
         memory_path_enabled ? 1u : 0u);
  fflush(stdout);
  return false;
}

static bool rtcore_v04_tlas_binding_enforcement_configuration_valid(
    const ptx_instruction *pI, bool boundary_publication_enabled,
    bool *tlas_binding_enforcement_enabled) {
  const rtcore_v04_shadow_gate_state enforcement_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_tlas_binding_enforcement_gate_name());
  if (tlas_binding_enforcement_enabled != NULL) {
    *tlas_binding_enforcement_enabled =
        enforcement_state == RTCORE_V04_SHADOW_GATE_ENABLED;
  }
  const char *reason = NULL;
  if (enforcement_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_TLAS_BINDING_ENFORCEMENT_GATE_INVALID";
  } else if (enforcement_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !boundary_publication_enabled) {
    reason = "V04_SHADOW_BOUNDARY_PUBLICATION_REQUIRED";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "tlas_binding_enforcement_gate=%s, "
         "boundary_publication_enabled=%u\n",
         pI->source_file(), pI->source_line(), reason,
         getenv(rtcore_v04_tlas_binding_enforcement_gate_name()) != NULL
             ? getenv(rtcore_v04_tlas_binding_enforcement_gate_name())
             : "<unset>",
         boundary_publication_enabled ? 1u : 0u);
  fflush(stdout);
  return false;
}

static bool rtcore_v04_shadow_shader_return_configuration_valid(
    const ptx_instruction *pI, bool boundary_publication_enabled) {
  const rtcore_v04_shadow_gate_state publication_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_shadow_shader_return_publication_gate_name());
  const rtcore_v04_shadow_gate_state consumer_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_shadow_shader_return_consumer_gate_name());
  const char *reason = NULL;
  if (publication_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_SHADOW_SHADER_RETURN_PUBLICATION_GATE_INVALID";
  } else if (consumer_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_SHADOW_SHADER_RETURN_CONSUMER_GATE_INVALID";
  } else if (publication_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !boundary_publication_enabled) {
    reason = "V04_SHADOW_BOUNDARY_PUBLICATION_REQUIRED";
  } else if (consumer_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             publication_state != RTCORE_V04_SHADOW_GATE_ENABLED) {
    reason = "V04_SHADOW_SHADER_RETURN_PUBLICATION_REQUIRED";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "shader_return_publication_gate=%s, "
         "shader_return_consumer_gate=%s, "
         "boundary_publication_enabled=%u\n",
         pI->source_file(), pI->source_line(), reason,
         getenv(rtcore_v04_shadow_shader_return_publication_gate_name()) !=
                 NULL
             ? getenv(
                   rtcore_v04_shadow_shader_return_publication_gate_name())
             : "<unset>",
         getenv(rtcore_v04_shadow_shader_return_consumer_gate_name()) != NULL
             ? getenv(rtcore_v04_shadow_shader_return_consumer_gate_name())
             : "<unset>",
         boundary_publication_enabled ? 1u : 0u);
  fflush(stdout);
  return false;
}

static bool rtcore_v04_functional_shader_return_configuration_valid(
    const ptx_instruction *pI, bool shadow_consumer_enabled,
    bool boundary_publication_enabled, bool live_publication_enabled,
    bool tlas_binding_enforcement_enabled) {
  const rtcore_v04_shadow_gate_state authority_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_functional_shader_return_authority_gate_name());
  const rtcore_v04_shadow_gate_state return_publication_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_shadow_shader_return_publication_gate_name());
  const rtcore_v04_shadow_gate_state return_consumer_state =
      rtcore_v04_shadow_gate(
          rtcore_v04_shadow_shader_return_consumer_gate_name());
  const char *reason = NULL;
  if (authority_state == RTCORE_V04_SHADOW_GATE_INVALID) {
    reason = "V04_FUNCTIONAL_SHADER_RETURN_AUTHORITY_GATE_INVALID";
  } else if (authority_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !shadow_consumer_enabled) {
    reason = "V04_SHADOW_TRACE_INPUT_CONSUMER_REQUIRED";
  } else if (authority_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !boundary_publication_enabled) {
    reason = "V04_SHADOW_BOUNDARY_PUBLICATION_REQUIRED";
  } else if (authority_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !live_publication_enabled) {
    reason = "V04_LIVE_HANDOFF_PUBLICATION_REQUIRED";
  } else if (authority_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             !tlas_binding_enforcement_enabled) {
    reason = "V04_TLAS_BINDING_ENFORCEMENT_REQUIRED";
  } else if (authority_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             return_publication_state != RTCORE_V04_SHADOW_GATE_ENABLED) {
    reason = "V04_SHADOW_SHADER_RETURN_PUBLICATION_REQUIRED";
  } else if (authority_state == RTCORE_V04_SHADOW_GATE_ENABLED &&
             return_consumer_state != RTCORE_V04_SHADOW_GATE_ENABLED) {
    reason = "V04_SHADOW_SHADER_RETURN_CONSUMER_REQUIRED";
  }
  if (reason == NULL) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), reason=%s, "
         "functional_shader_return_authority_gate=%s, "
         "shadow_consumer_enabled=%u, boundary_publication_enabled=%u, "
         "live_publication_enabled=%u, "
         "tlas_binding_enforcement_enabled=%u, "
         "shader_return_publication_gate=%s, "
         "shader_return_consumer_gate=%s\n",
         pI->source_file(), pI->source_line(), reason,
         getenv(rtcore_v04_functional_shader_return_authority_gate_name()) !=
                 NULL
             ? getenv(
                   rtcore_v04_functional_shader_return_authority_gate_name())
             : "<unset>",
         shadow_consumer_enabled ? 1u : 0u,
         boundary_publication_enabled ? 1u : 0u,
         live_publication_enabled ? 1u : 0u,
         tlas_binding_enforcement_enabled ? 1u : 0u,
         getenv(rtcore_v04_shadow_shader_return_publication_gate_name()) !=
                 NULL
             ? getenv(
                   rtcore_v04_shadow_shader_return_publication_gate_name())
             : "<unset>",
         getenv(rtcore_v04_shadow_shader_return_consumer_gate_name()) != NULL
             ? getenv(rtcore_v04_shadow_shader_return_consumer_gate_name())
             : "<unset>");
  fflush(stdout);
  return false;
}

static bool rtcore_validate_v04_shadow_trace_input(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    unsigned lane_slot_index,
    const rtcore_v03_compact_context_decoded &admission_context,
    unsigned owner_hw_sid, unsigned dynamic_warp_id, unsigned warp_uid,
    unsigned warp_id, unsigned resident_warp_generation,
    const unsigned char *acquired_lane_bytes,
    unsigned acquired_lane_byte_count,
    std::array<uint32_t, rtcore::abi_v04::kWordCount> *validated_words) {
  if (thread == NULL || lane_slot_index >= 32) {
    return false;
  }
  const uint64_t lane_offset =
      (uint64_t)lane_slot_index * rtcore::abi_v04::kLaneSlotBytes;
  const uint64_t lane_address = handoff_window_base + lane_offset;
  if (lane_address < handoff_window_base) {
    return false;
  }

  std::array<uint8_t, rtcore::abi_v04::kLaneSlotBytes> image = {};
  const bool retained_initial_acquire = acquired_lane_bytes != NULL;
  if (retained_initial_acquire) {
    if (acquired_lane_byte_count != image.size()) return false;
    memcpy(image.data(), acquired_lane_bytes, image.size());
  } else {
    if (acquired_lane_byte_count != 0) return false;
    thread->get_global_memory()->read_simulator_backing(
        (mem_addr_t)lane_address, image.size(), image.data());
  }
  std::array<uint32_t, rtcore::abi_v04::kWordCount> actual =
      rtcore::abi_v04::decode_words_le(image);

  const char *mutation =
      getenv("VULKAN_SIM_RTCORE_TEST_V04_SHADOW_TRACE_INPUT_MUTATION");
  bool mutation_valid = mutation == NULL || mutation[0] == '\0' ||
                        strcmp(mutation, "none") == 0;
  if (mutation != NULL && strcmp(mutation, "context") == 0) {
    actual[rtcore::abi_v04::kContextAddressLow32.word] ^= 1u;
    mutation_valid = true;
  } else if (mutation != NULL && strcmp(mutation, "ray_tmin") == 0) {
    actual[rtcore::abi_v04::kRayTminFp32.word] ^= 1u;
    mutation_valid = true;
  } else if (mutation != NULL && strcmp(mutation, "packed_policy") == 0) {
    actual[rtcore::abi_v04::kCullMask.word] ^= 1u;
    mutation_valid = true;
  } else if (mutation != NULL && strcmp(mutation, "reserved") == 0) {
    for (std::size_t word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
      if (rtcore::abi_v04::kReservedMasks[word] == 0xffffffffu) {
        actual[word] ^= 1u;
        mutation_valid = true;
        break;
      }
    }
  }

  rtcore::abi_v04::shadow::trace_input_values expected = {};
  expected.context_address = context_ptr;
  expected.traversable_reference =
      admission_context.as_handle_or_traversable_ref;
  expected.world_ray_origin_fp32[0] =
      rtcore_context_float_to_u32(admission_context.ray_origin.x);
  expected.world_ray_origin_fp32[1] =
      rtcore_context_float_to_u32(admission_context.ray_origin.y);
  expected.world_ray_origin_fp32[2] =
      rtcore_context_float_to_u32(admission_context.ray_origin.z);
  expected.ray_tmin_fp32 =
      rtcore_context_float_to_u32(admission_context.ray_tmin);
  expected.world_ray_direction_fp32[0] =
      rtcore_context_float_to_u32(admission_context.ray_direction.x);
  expected.world_ray_direction_fp32[1] =
      rtcore_context_float_to_u32(admission_context.ray_direction.y);
  expected.world_ray_direction_fp32[2] =
      rtcore_context_float_to_u32(admission_context.ray_direction.z);
  expected.launch_ray_tmax_fp32 =
      rtcore_context_float_to_u32(admission_context.ray_tmax);
  expected.ray_flags = admission_context.ray_flags;
  expected.cull_mask = admission_context.cull_mask;
  expected.sbt_record_offset = admission_context.sbt_offset;
  expected.sbt_record_stride = admission_context.sbt_stride;
  expected.miss_index = admission_context.miss_index;

  const rtcore::abi_v04::shadow::trace_input_validation validation =
      rtcore::abi_v04::shadow::validate_trace_input_words(actual, expected);
  const bool valid = mutation_valid && validation.matches();
  if (valid && validated_words != NULL) {
    *validated_words = actual;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT v04-shadow-trace-input-consumer "
         "(%s:%u), profile=%s, context_ptr=0x%llx, "
         "owner_hw_sid=%u dynamic_warp_id=%u warp_uid=%u warp_id=%u "
         "resident_generation=%u "
         "handoff_window_base=0x%llx, lane_slot_index=%u, "
         "lane_address=0x%llx, expected_encoding_valid=%u, "
         "owned_word_mask=0x%08x, mismatch_word_mask=0x%08x, "
         "mutation=%s, mutation_valid=%u, input_source=%s, "
         "observation_only=%u, traversal_authority=%u, valid=%u\n",
         pI->source_file(), pI->source_line(), rtcore::abi_v04::kProfileId,
         context_ptr, owner_hw_sid, dynamic_warp_id, warp_uid, warp_id,
         resident_warp_generation, handoff_window_base, lane_slot_index,
         (unsigned long long)lane_address,
         validation.expected_encoding_valid ? 1u : 0u,
         validation.owned_word_mask, validation.mismatch_word_mask,
         mutation != NULL && mutation[0] != '\0' ? mutation : "none",
         mutation_valid ? 1u : 0u,
         retained_initial_acquire ? "initial_l1d_response_bytes"
                                  : "simulator_backing",
         retained_initial_acquire ? 0u : 1u,
         retained_initial_acquire ? 1u : 0u,
         valid ? 1u : 0u);
  fflush(stdout);
  return valid;
}

static const char *rtcore_path_mode_raw_value() {
  const char *mode = getenv("VULKAN_SIM_RTCORE_PATH_MODE");
  return mode == NULL ? "" : mode;
}

static bool rtcore_path_mode_compat_custom_enabled() {
  return rtcore_env_flag_enabled("VULKAN_SIM_RTCORE_SYMBOLIC_SUBMIT") ||
         rtcore_env_flag_enabled("VULKAN_SIM_RTCORE_FORWARD_SIDEBAND_PATH") ||
         rtcore_env_flag_enabled(
             "VULKAN_SIM_RTCORE_COMPILER_DRIVER_PUBLICATION_SOURCE") ||
         rtcore_env_flag_enabled(
             "VULKAN_SIM_RTCORE_LAUNCH_CONTEXT_INPUT_PUBLICATION_BRIDGE");
}

static rtcore_path_mode_policy rtcore_get_path_mode_policy() {
  static const rtcore_path_mode_policy policy = []() {
    const char *mode = getenv("VULKAN_SIM_RTCORE_PATH_MODE");
    if (mode != NULL && mode[0] != '\0') {
      if (rtcore_path_mode_is(mode, "legacy") ||
          rtcore_path_mode_is(mode, "trace_ray") ||
          rtcore_path_mode_is(mode, "trace-ray") ||
          rtcore_path_mode_is(mode, "trace_ray_only") ||
          rtcore_path_mode_is(mode, "trace-ray-only")) {
        return RTCORE_PATH_MODE_POLICY_LEGACY;
      }
      if (rtcore_path_mode_is(mode, "custom") ||
          rtcore_path_mode_is(mode, "forward") ||
          rtcore_path_mode_is(mode, "forward_sideband") ||
          rtcore_path_mode_is(mode, "forward-sideband") ||
          rtcore_path_mode_is(mode, "sideband")) {
        return RTCORE_PATH_MODE_POLICY_CUSTOM;
      }
      return RTCORE_PATH_MODE_POLICY_INVALID;
    }
    if (rtcore_env_flag_enabled("VULKAN_SIM_RTCORE_LEGACY_TRACE_RAY_PATH")) {
      return RTCORE_PATH_MODE_POLICY_LEGACY;
    }
    if (rtcore_path_mode_compat_custom_enabled()) {
      return RTCORE_PATH_MODE_POLICY_CUSTOM;
    }
    return RTCORE_PATH_MODE_POLICY_CUSTOM;
  }();
  return policy;
}

static bool rtcore_path_mode_policy_legacy_path_enabled(
    rtcore_path_mode_policy policy) {
  return policy == RTCORE_PATH_MODE_POLICY_LEGACY;
}

static bool rtcore_path_mode_policy_enables_custom_path(
    rtcore_path_mode_policy policy) {
  return policy == RTCORE_PATH_MODE_POLICY_CUSTOM;
}

static bool rtcore_path_mode_policy_is_invalid(
    rtcore_path_mode_policy policy) {
  return policy == RTCORE_PATH_MODE_POLICY_INVALID;
}

static bool rtcore_legacy_trace_ray_path_enabled() {
  return rtcore_path_mode_policy_legacy_path_enabled(
      rtcore_get_path_mode_policy());
}

extern "C" bool rtcore_custom_path_mode_enabled() {
  return rtcore_path_mode_policy_enables_custom_path(
      rtcore_get_path_mode_policy());
}

static bool rtcore_forward_sideband_path_enabled() {
  return rtcore_custom_path_mode_enabled();
}

static bool rtcore_trace_invocation_publication_source_enabled() {
  const rtcore_path_mode_policy policy = rtcore_get_path_mode_policy();
  if (rtcore_path_mode_policy_legacy_path_enabled(policy) ||
      rtcore_path_mode_policy_is_invalid(policy)) {
    return false;
  }
  return rtcore_env_flag_enabled(
      "VULKAN_SIM_RTCORE_TRACE_INVOCATION_PUBLICATION_SOURCE");
}

static bool rtcore_compiler_driver_publication_source_enabled() {
  const rtcore_path_mode_policy policy = rtcore_get_path_mode_policy();
  if (rtcore_path_mode_policy_legacy_path_enabled(policy) ||
      rtcore_path_mode_policy_is_invalid(policy)) {
    return false;
  }
  return rtcore_path_mode_policy_enables_custom_path(policy);
}

static bool rtcore_fail_closed_on_invalid_path_mode(const ptx_instruction *pI) {
  if (!rtcore_path_mode_policy_is_invalid(rtcore_get_path_mode_policy())) {
    return false;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
         "invalid VULKAN_SIM_RTCORE_PATH_MODE=%s\n",
         pI->source_file(), pI->source_line(), rtcore_path_mode_raw_value());
  fflush(stdout);
  inst_not_implemented(pI);
  return true;
}

static bool
rtcore_trace_invocation_publication_source_fallback_enabled() {
  return rtcore_trace_invocation_publication_source_enabled() &&
         !rtcore_compiler_driver_publication_source_enabled();
}

static bool
rtcore_compiler_driver_publication_source_failpoint_corrupt_context_window_key() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_COMPILER_DRIVER_PUBLICATION_SOURCE_FAILPOINT");
  return value != NULL && strcmp(value, "corrupt_context_window_key") == 0;
}

static bool
rtcore_compiler_driver_publication_source_failpoint_drop_context_window_key() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_COMPILER_DRIVER_PUBLICATION_SOURCE_FAILPOINT");
  return value != NULL && strcmp(value, "drop_context_window_key") == 0;
}

static bool rtcore_trace_invocation_publication_source_owner_tuple_matches(
    ptx_thread_info *thread,
    const rtcore_trace_invocation_publication_source_shadow &shadow) {
  if (thread == NULL) {
    return false;
  }
  return shadow.owner_hw_tid == thread->get_hw_tid() &&
         shadow.owner_hw_wid == thread->get_hw_wid() &&
         shadow.owner_hw_sid == thread->get_hw_sid();
}

static bool
rtcore_trace_invocation_publication_source_failpoint_drop_publish() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_TRACE_INVOCATION_PUBLICATION_SOURCE_FAILPOINT");
  return value != NULL && strcmp(value, "drop_publish") == 0;
}

static bool
rtcore_trace_invocation_publication_source_failpoint_corrupt_owner_tuple() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_TRACE_INVOCATION_PUBLICATION_SOURCE_FAILPOINT");
  return value != NULL && strcmp(value, "corrupt_owner_tuple") == 0;
}

static void rtcore_publish_trace_invocation_publication_source_shadow(
    const ptx_instruction *pI, ptx_thread_info *thread, uint64_t top_level_as,
    uint32_t ray_flags, uint32_t cull_mask, uint32_t sbt_record_offset,
    uint32_t sbt_record_stride, uint32_t miss_index, float3 ray_origin,
    float ray_tmin, float3 ray_direction, float ray_tmax) {
  if (rtcore_trace_invocation_publication_source_enabled() &&
      rtcore_compiler_driver_publication_source_enabled()) {
    printf("GPGPU-Sim PTX: RT_SUBMIT "
           "compiler-driver-publication-source-policy-suppressed-trace-shadow "
           "(%s:%u), source=trace_ray_impl, "
           "preferred_source=compiler_driver_publication_sideband\n",
           pI->source_file(), pI->source_line());
    fflush(stdout);
    return;
  }
  if (!rtcore_trace_invocation_publication_source_fallback_enabled() ||
      thread == NULL) {
    return;
  }
  if (rtcore_trace_invocation_publication_source_failpoint_drop_publish()) {
    printf("GPGPU-Sim PTX: RT_SUBMIT "
           "trace-invocation-publication-source-drop-publish (%s:%u), "
           "source=trace_ray_impl, top_level_as=0x%llx, ray_flags=%u, "
           "cull_mask=%u, sbt_record_offset=%u, sbt_record_stride=%u, "
           "miss_index=%u\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)top_level_as, ray_flags, cull_mask,
           sbt_record_offset, sbt_record_stride, miss_index);
    fflush(stdout);
    return;
  }

  rtcore_trace_invocation_publication_source_shadow shadow;
  shadow.valid = true;
  shadow.thread = thread;
  shadow.source_publication_seq =
      ++g_rtcore_trace_invocation_publication_source_next_seq;
  shadow.owner_hw_tid = thread->get_hw_tid();
  shadow.owner_hw_wid = thread->get_hw_wid();
  shadow.owner_hw_sid = thread->get_hw_sid();
  shadow.owner_tuple_match = true;
  shadow.top_level_as = top_level_as;
  shadow.has_top_level_as = top_level_as != 0;
  shadow.ray_origin = ray_origin;
  shadow.ray_direction = ray_direction;
  shadow.ray_tmin = ray_tmin;
  shadow.ray_tmax = ray_tmax;
  shadow.ray_flags = ray_flags;
  shadow.cull_mask = cull_mask;
  shadow.sbt_record_offset = sbt_record_offset;
  shadow.sbt_record_stride = sbt_record_stride;
  shadow.miss_index = miss_index;
  if (rtcore_trace_invocation_publication_source_failpoint_corrupt_owner_tuple()) {
    unsigned expected_owner_hw_sid = shadow.owner_hw_sid;
    shadow.owner_hw_sid = shadow.owner_hw_sid + 1;
    shadow.owner_tuple_match = false;
    printf("GPGPU-Sim PTX: RT_SUBMIT "
           "trace-invocation-publication-source-owner-mismatch (%s:%u), "
           "source=trace_ray_impl, source_publication_seq=%llu, "
           "expected_owner_hw_tid=%u, expected_owner_hw_wid=%u, "
           "expected_owner_hw_sid=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
           "owner_hw_sid=%u\n",
           pI->source_file(), pI->source_line(),
           shadow.source_publication_seq, shadow.owner_hw_tid,
           shadow.owner_hw_wid, expected_owner_hw_sid,
           shadow.owner_hw_tid, shadow.owner_hw_wid, shadow.owner_hw_sid);
    fflush(stdout);
  }
  g_rtcore_trace_invocation_publication_source_shadow[thread] = shadow;

  printf("GPGPU-Sim PTX: RT_SUBMIT "
         "trace-invocation-publication-source-shadow (%s:%u), "
         "source=trace_ray_impl, top_level_as=0x%llx, "
         "has_top_level_as=%u, ray_flags=%u, cull_mask=%u, "
         "sbt_record_offset=%u, sbt_record_stride=%u, miss_index=%u, "
         "source_publication_seq=%llu, owner_hw_tid=%u, "
         "owner_hw_wid=%u, owner_hw_sid=%u\n",
         pI->source_file(), pI->source_line(),
         (unsigned long long)shadow.top_level_as,
         shadow.has_top_level_as ? 1 : 0, shadow.ray_flags,
         shadow.cull_mask, shadow.sbt_record_offset,
         shadow.sbt_record_stride, shadow.miss_index,
         shadow.source_publication_seq, shadow.owner_hw_tid,
         shadow.owner_hw_wid, shadow.owner_hw_sid);
  fflush(stdout);
}

static bool rtcore_consume_trace_invocation_publication_source_shadow(
    ptx_thread_info *thread,
    rtcore_trace_invocation_publication_source_shadow *out_shadow) {
  if (thread == NULL || out_shadow == NULL) {
    return false;
  }
  std::map<ptx_thread_info *,
           rtcore_trace_invocation_publication_source_shadow>::iterator found =
      g_rtcore_trace_invocation_publication_source_shadow.find(thread);
  if (found == g_rtcore_trace_invocation_publication_source_shadow.end()) {
    return false;
  }
  *out_shadow = found->second;
  g_rtcore_trace_invocation_publication_source_shadow.erase(found);
  out_shadow->owner_tuple_match =
      rtcore_trace_invocation_publication_source_owner_tuple_matches(
          thread, *out_shadow);
  return out_shadow->valid && out_shadow->thread == thread &&
         out_shadow->owner_tuple_match;
}

static void rtcore_publish_trace_context_publication_source_shadow(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    uint64_t top_level_as, uint32_t ray_flags, uint32_t cull_mask,
    uint32_t sbt_record_offset, uint32_t sbt_record_stride,
    uint32_t miss_index, float3 ray_origin, float ray_tmin,
    float3 ray_direction, float ray_tmax) {
  if (!rtcore_compiler_driver_publication_source_enabled() || thread == NULL) {
    return;
  }

  rtcore_trace_invocation_publication_source_shadow shadow;
  shadow.valid = true;
  shadow.thread = thread;
  shadow.source_publication_seq =
      ++g_rtcore_trace_invocation_publication_source_next_seq;
  shadow.owner_hw_tid = thread->get_hw_tid();
  shadow.owner_hw_wid = thread->get_hw_wid();
  shadow.owner_hw_sid = thread->get_hw_sid();
  shadow.owner_tuple_match = true;
  shadow.source = "compiler_driver_publication_sideband";
  shadow.has_context_window_owner_key = true;
  shadow.context_ptr = context_ptr;
  shadow.handoff_window_base = handoff_window_base;
  shadow.top_level_as = top_level_as;
  shadow.has_top_level_as = top_level_as != 0;
  shadow.ray_origin = ray_origin;
  shadow.ray_direction = ray_direction;
  shadow.ray_tmin = ray_tmin;
  shadow.ray_tmax = ray_tmax;
  shadow.ray_flags = ray_flags;
  shadow.cull_mask = cull_mask;
  shadow.sbt_record_offset = sbt_record_offset;
  shadow.sbt_record_stride = sbt_record_stride;
  shadow.miss_index = miss_index;
  if (rtcore_compiler_driver_publication_source_failpoint_corrupt_context_window_key()) {
    unsigned long long expected_context_ptr = shadow.context_ptr;
    unsigned long long expected_handoff_window_base = shadow.handoff_window_base;
    shadow.context_ptr = shadow.context_ptr + 64;
    shadow.handoff_window_base = shadow.handoff_window_base + 128;
    printf("GPGPU-Sim PTX: RT_SUBMIT "
           "compiler-driver-publication-source-context-window-mismatch "
           "(%s:%u), source=compiler_driver_publication_sideband, "
           "source_publication_seq=%llu, "
           "expected_context_ptr=0x%llx, expected_handoff_window_base=0x%llx, "
           "published_context_ptr=0x%llx, "
           "published_handoff_window_base=0x%llx\n",
           pI->source_file(), pI->source_line(),
           shadow.source_publication_seq, expected_context_ptr,
           expected_handoff_window_base, shadow.context_ptr,
           shadow.handoff_window_base);
    fflush(stdout);
  }
  if (rtcore_compiler_driver_publication_source_failpoint_drop_context_window_key()) {
    shadow.has_context_window_owner_key = false;
    printf("GPGPU-Sim PTX: RT_SUBMIT "
           "compiler-driver-publication-source-missing-context-window-key "
           "(%s:%u), source=compiler_driver_publication_sideband, "
           "source_publication_seq=%llu, published_context_ptr=0x%llx, "
           "published_handoff_window_base=0x%llx\n",
           pI->source_file(), pI->source_line(),
           shadow.source_publication_seq, shadow.context_ptr,
           shadow.handoff_window_base);
    fflush(stdout);
  }
  g_rtcore_trace_invocation_publication_source_shadow[thread] = shadow;

  printf("GPGPU-Sim PTX: RT_SUBMIT "
         "rt-publish-trace-context-publication-source (%s:%u), "
         "source=compiler_driver_publication_sideband, "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "top_level_as=0x%llx, has_top_level_as=%u, "
         "ray_flags=%u, cull_mask=%u, sbt_record_offset=%u, "
         "sbt_record_stride=%u, miss_index=%u, "
         "source_publication_seq=%llu, owner_hw_tid=%u, "
         "owner_hw_wid=%u, owner_hw_sid=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         handoff_window_base, (unsigned long long)shadow.top_level_as,
         shadow.has_top_level_as ? 1 : 0, shadow.ray_flags,
         shadow.cull_mask, shadow.sbt_record_offset,
         shadow.sbt_record_stride, shadow.miss_index,
         shadow.source_publication_seq, shadow.owner_hw_tid,
         shadow.owner_hw_wid, shadow.owner_hw_sid);
  fflush(stdout);
}

static bool rtcore_fail_closed_on_rt_publish_trace_context_operand_contract(
    const ptx_instruction *pI) {
  if (pI->get_num_operands() == 16 || pI->get_num_operands() == 17) {
    return false;
  }
  printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
         "reason=RT_PUBLISH_TRACE_CONTEXT_OPERAND_CONTRACT, "
         "observed_operands=%u, expected_operands=16_or_17\n",
         pI->source_file(), pI->source_line(), pI->get_num_operands());
  fflush(stdout);
  inst_not_implemented(pI);
  return true;
}

void rt_publish_trace_context_impl(const ptx_instruction *pI, ptx_thread_info *thread) {
  if (rtcore_fail_closed_on_rt_publish_trace_context_operand_contract(pI)) {
    return;
  }

  const operand_info &context_ptr = pI->operand_lookup(0);
  ptx_reg_t context_ptr_data =
      thread->get_operand_value(context_ptr, context_ptr, B64_TYPE, thread, 1);

  const operand_info &handoff_window_base = pI->operand_lookup(1);
  ptx_reg_t handoff_window_base_data = thread->get_operand_value(
      handoff_window_base, handoff_window_base, B64_TYPE, thread, 1);
  if ((thread->get_hw_tid() % 32) == 0 &&
      rtcore_env_flag_enabled("VULKAN_SIM_RTCORE_TEST_CONTEXT_LANE_ALIAS")) {
    context_ptr_data.u64 += sizeof(rtcore_v03_compact_context_image);
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT "
           "test-context-lane-alias (%s:%u), context_ptr=0x%llx, "
           "lane_slot_index=0\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)context_ptr_data.u64);
    fflush(stdout);
  }

  const operand_info &topLevelAS = pI->operand_lookup(2);
  ptx_reg_t topLevelAS_data =
      thread->get_operand_value(topLevelAS, topLevelAS, B64_TYPE, thread, 1);

  const operand_info &rayFlags = pI->operand_lookup(3);
  ptx_reg_t rayFlags_data =
      thread->get_operand_value(rayFlags, rayFlags, U32_TYPE, thread, 1);

  const operand_info &cullMask = pI->operand_lookup(4);
  ptx_reg_t cullMask_data =
      thread->get_operand_value(cullMask, cullMask, U32_TYPE, thread, 1);

  const operand_info &sbtRecordOffset = pI->operand_lookup(5);
  ptx_reg_t sbtRecordOffset_data = thread->get_operand_value(
      sbtRecordOffset, sbtRecordOffset, U32_TYPE, thread, 1);

  const operand_info &sbtRecordStride = pI->operand_lookup(6);
  ptx_reg_t sbtRecordStride_data = thread->get_operand_value(
      sbtRecordStride, sbtRecordStride, U32_TYPE, thread, 1);

  const operand_info &missIndex = pI->operand_lookup(7);
  ptx_reg_t missIndex_data =
      thread->get_operand_value(missIndex, missIndex, U32_TYPE, thread, 1);

  const operand_info &originX = pI->operand_lookup(8);
  ptx_reg_t originX_data =
      thread->get_operand_value(originX, originX, F32_TYPE, thread, 1);

  const operand_info &originY = pI->operand_lookup(9);
  ptx_reg_t originY_data =
      thread->get_operand_value(originY, originY, F32_TYPE, thread, 1);

  const operand_info &originZ = pI->operand_lookup(10);
  ptx_reg_t originZ_data =
      thread->get_operand_value(originZ, originZ, F32_TYPE, thread, 1);

  const operand_info &Tmin = pI->operand_lookup(11);
  ptx_reg_t Tmin_data =
      thread->get_operand_value(Tmin, Tmin, F32_TYPE, thread, 1);

  const operand_info &directionX = pI->operand_lookup(12);
  ptx_reg_t directionX_data =
      thread->get_operand_value(directionX, directionX, F32_TYPE, thread, 1);

  const operand_info &directionY = pI->operand_lookup(13);
  ptx_reg_t directionY_data =
      thread->get_operand_value(directionY, directionY, F32_TYPE, thread, 1);

  const operand_info &directionZ = pI->operand_lookup(14);
  ptx_reg_t directionZ_data =
      thread->get_operand_value(directionZ, directionZ, F32_TYPE, thread, 1);

  const operand_info &Tmax = pI->operand_lookup(15);
  ptx_reg_t Tmax_data =
      thread->get_operand_value(Tmax, Tmax, F32_TYPE, thread, 1);

  const bool prepare_v04_shadow_handoff = pI->get_num_operands() == 17;
  unsigned v04_shadow_handoff_bytes = 0;
  if (prepare_v04_shadow_handoff) {
    const operand_info &handoff_bytes = pI->operand_lookup(16);
    const ptx_reg_t handoff_bytes_data = thread->get_operand_value(
        handoff_bytes, handoff_bytes, U32_TYPE, thread, 1);
    v04_shadow_handoff_bytes = handoff_bytes_data.u32;
    if (v04_shadow_handoff_bytes != rtcore::abi_v04::kLaneSlotBytes) {
      printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
             "reason=V04_SHADOW_HANDOFF_BYTES_MISMATCH, "
             "observed_bytes=%u, expected_bytes=%zu\n",
             pI->source_file(), pI->source_line(),
             v04_shadow_handoff_bytes,
             (size_t)rtcore::abi_v04::kLaneSlotBytes);
      fflush(stdout);
      inst_not_implemented(pI);
      return;
    }
  }

  float3 ray_origin = {originX_data.f32, originY_data.f32, originZ_data.f32};
  float3 ray_direction = {directionX_data.f32, directionY_data.f32,
                          directionZ_data.f32};
  const bool context_published = rtcore_publish_v03_compact_context_image(
      pI, thread, context_ptr_data.u64, handoff_window_base_data.u64,
      (uint64_t)topLevelAS_data.u64, rayFlags_data.u32, cullMask_data.u32,
      sbtRecordOffset_data.u32, sbtRecordStride_data.u32, missIndex_data.u32,
      ray_origin, Tmin_data.f32, ray_direction, Tmax_data.f32);
  if (!context_published) {
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
           "reason=COMPACT_CONTEXT_PUBLICATION_FAILED, "
           "context_ptr=0x%llx, handoff_window_base=0x%llx\n",
           pI->source_file(), pI->source_line(), context_ptr_data.u64,
           handoff_window_base_data.u64);
    fflush(stdout);
    inst_not_implemented(pI);
    return;
  }

  if (prepare_v04_shadow_handoff) {
    const uint64_t lane_slot_index = thread->get_hw_tid() % 32;
    const uint64_t lane_offset =
        lane_slot_index * rtcore::abi_v04::kLaneSlotBytes;
    const uint64_t lane_address = handoff_window_base_data.u64 + lane_offset;
    if (lane_address < handoff_window_base_data.u64) {
      printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
             "reason=V04_SHADOW_HANDOFF_ADDRESS_OVERFLOW, "
             "handoff_window_base=0x%llx, lane_slot_index=%llu\n",
             pI->source_file(), pI->source_line(),
             handoff_window_base_data.u64,
             (unsigned long long)lane_slot_index);
      fflush(stdout);
      inst_not_implemented(pI);
      return;
    }
    if (!thread->get_global_memory()->ensure_simulator_backing(
            (mem_addr_t)lane_address, v04_shadow_handoff_bytes)) {
      printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
             "reason=V04_SHADOW_HANDOFF_ADDRESS_RANGE_INVALID, "
             "lane_address=0x%llx, lane_slot_bytes=%u\n",
             pI->source_file(), pI->source_line(),
             (unsigned long long)lane_address,
             v04_shadow_handoff_bytes);
      fflush(stdout);
      inst_not_implemented(pI);
      return;
    }
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT "
           "v04-shadow-handoff-backing-prepared (%s:%u), "
           "handoff_window_base=0x%llx, lane_slot_index=%llu, "
           "lane_address=0x%llx, lane_slot_bytes=%zu, byte_write=0\n",
           pI->source_file(), pI->source_line(),
           handoff_window_base_data.u64,
           (unsigned long long)lane_slot_index,
           (unsigned long long)lane_address,
           (size_t)v04_shadow_handoff_bytes);
    fflush(stdout);
  }
  if (!rtcore_v04_register_global384_provisional_publication(
          pI, thread, context_ptr_data.u64, handoff_window_base_data.u64,
          thread->get_hw_tid() % 32, prepare_v04_shadow_handoff,
          v04_shadow_handoff_bytes)) {
    inst_not_implemented(pI);
    return;
  }
}

void trace_ray_impl(const ptx_instruction *pI, ptx_thread_info *thread) {
  // if(thread->get_tid().x == 0 && thread->get_tid().y == 0 && thread->get_tid().z == 0)
  //   if(thread->get_ctaid().x == 0 && thread->get_ctaid().y == 0 && thread->get_ctaid().z == 0)
    VSIM_DPRINTF("gpgpusim: trace ray implementation\n");
    if(print_debug_insts)
    {
      printf("########## running line %d of file %s. thread(%d, %d, %d), cta(%d, %d, %d)\n", pI->source_line(), pI->source_file(),
                                        thread->get_tid().x, thread->get_tid().y, thread->get_tid().z,
                                        thread->get_ctaid().x, thread->get_ctaid().y, thread->get_ctaid().z);
      fflush(stdout);
    }

  // const operand_info &target = pI->func_addr();
  // const symbol *func_addr = target.get_symbol();
  // function_info *target_func = func_addr->get_pc();

  // unsigned n_return = target_func->has_return();
  // assert(n_return == 0);
  // unsigned n_args = target_func->num_args();
  // assert(n_args == 11);



  int arg = 0;
  const operand_info &op1 = pI->operand_lookup(arg);
  ptx_reg_t op1_data = thread->get_operand_value(op1, op1, B64_TYPE, thread, 1);
  VkAccelerationStructureKHR _topLevelAS = (VkAccelerationStructureKHR)(op1_data.s64);

  arg++;
  const operand_info &op2 = pI->operand_lookup(arg);
  ptx_reg_t op2_data = thread->get_operand_value(op2, op2, U32_TYPE, thread, 1);
  uint rayFlags = op2_data.u32;


  arg++;
  const operand_info &op3 = pI->operand_lookup(arg);
  ptx_reg_t op3_data = thread->get_operand_value(op3, op3, U32_TYPE, thread, 1);
  uint cullMask = op3_data.u32;

  arg++;
  const operand_info &op4 = pI->operand_lookup(arg);
  ptx_reg_t op4_data = thread->get_operand_value(op4, op4, U32_TYPE, thread, 1);
  uint sbtRecordOffset = op4_data.u32;

  arg++;
  const operand_info &op5 = pI->operand_lookup(arg);
  ptx_reg_t op5_data = thread->get_operand_value(op5, op5, U32_TYPE, thread, 1);
  uint sbtRecordStride = op5_data.u32;

  arg++;
  const operand_info &op6 = pI->operand_lookup(arg);
  ptx_reg_t op6_data = thread->get_operand_value(op6, op6, U32_TYPE, thread, 1);
  uint missIndex = op6_data.u32;

  arg++;
  const operand_info &op7 = pI->operand_lookup(arg);
  ptx_reg_t op7_data = thread->get_operand_value(op7, op7, F32_TYPE, thread, 1);
  float originX = op7_data.f32;

  arg++;
  const operand_info &op8 = pI->operand_lookup(arg);
  ptx_reg_t op8_data = thread->get_operand_value(op8, op8, F32_TYPE, thread, 1);
  float originY = op8_data.f32;

  arg++;
  const operand_info &op9 = pI->operand_lookup(arg);
  ptx_reg_t op9_data = thread->get_operand_value(op9, op9, F32_TYPE, thread, 1);
  float originZ = op9_data.f32;

  arg++;
  const operand_info &op10 = pI->operand_lookup(arg);
  ptx_reg_t op10_data = thread->get_operand_value(op10, op10, F32_TYPE, thread, 1);
  float Tmin = op10_data.f32;

  arg++;
  const operand_info &op11 = pI->operand_lookup(arg);
  ptx_reg_t op11_data = thread->get_operand_value(op11, op11, F32_TYPE, thread, 1);
  float directionX = op11_data.f32;

  arg++;
  const operand_info &op12 = pI->operand_lookup(arg);
  ptx_reg_t op12_data = thread->get_operand_value(op12, op12, F32_TYPE, thread, 1);
  float directionY = op12_data.f32;

  arg++;
  const operand_info &op13 = pI->operand_lookup(arg);
  ptx_reg_t op13_data = thread->get_operand_value(op13, op13, F32_TYPE, thread, 1);
  float directionZ = op13_data.f32;

  arg++;
  const operand_info &op14 = pI->operand_lookup(arg);
  ptx_reg_t op14_data = thread->get_operand_value(op14, op14, F32_TYPE, thread, 1);
  float Tmax = op14_data.f32;

  // arg++;
  // const operand_info &op15 = pI->operand_lookup(arg);
  // ptx_reg_t op15_data = thread->get_operand_value(op15, op15, U64_TYPE, thread, 1);
  // uint32_t payload = op15_data.u64;

  // thread->dump_regs(stdout);

  float3 ray_origin = {originX, originY, originZ};
  float3 ray_direction = {directionX, directionY, directionZ};
  rtcore_publish_trace_invocation_publication_source_shadow(
      pI, thread, (uint64_t)_topLevelAS, rayFlags, cullMask, sbtRecordOffset,
      sbtRecordStride, missIndex, ray_origin, Tmin, ray_direction, Tmax);

  VulkanRayTracing::traceRay(_topLevelAS, rayFlags, cullMask, sbtRecordOffset, sbtRecordStride, missIndex,
                   ray_origin,
                   Tmin,
                   ray_direction,
                   Tmax,
                   0,
                   0,
                   0,
                   0,
                   NULL,
                   NULL,
                   pI,
                   thread);
}

