unsigned rtcore_v02_lsu_handoff_window_lane_slot_chunk_count() {
  return (RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE +
          RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES - 1) /
         RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES;
}

unsigned rtcore_v02_lsu_handoff_memory_op_seq(unsigned window_generation,
                                              unsigned access_kind) {
  const unsigned op_slot =
      access_kind == RTCORE_V02_LSU_ACCESS_RESULT_STORE ? 1u : 0u;
  return window_generation * 2u + op_slot;
}

unsigned rtcore_v02_lsu_handoff_publication_memory_op_seq(
    unsigned window_generation) {
  return RTCORE_V02_LSU_HANDOFF_PUBLICATION_MEMORY_OP_SEQ_BASE +
         window_generation;
}

unsigned long long rtcore_v02_lsu_issue_cycle(ptx_thread_info *thread) {
  return thread != NULL && thread->get_gpu() != NULL
             ? thread->get_gpu()->gpu_tot_sim_cycle +
                   thread->get_gpu()->gpu_sim_cycle
             : 0;
}

bool rtcore_address_in_range(unsigned long long address,
                             unsigned long long base,
                             unsigned long long bytes) {
  return address >= base && address < (base + bytes);
}

rtcore_handoff_window_class rtcore_classify_handoff_window(
    unsigned long long handoff_window_base) {
  if (rtcore_address_in_range(handoff_window_base,
                              RTCORE_SHARED_HANDOFF_WINDOW_BASE,
                              RTCORE_SHARED_HANDOFF_WINDOW_BYTES)) {
    return RTCORE_HANDOFF_WINDOW_CLASS_SHARED_WORKGROUP;
  }
  if (rtcore_address_in_range(handoff_window_base,
                              RTCORE_LOCAL_PRIVATE_HANDOFF_WINDOW_BASE,
                              RTCORE_LOCAL_PRIVATE_HANDOFF_WINDOW_BYTES)) {
    return RTCORE_HANDOFF_WINDOW_CLASS_LOCAL_PRIVATE;
  }
  return RTCORE_HANDOFF_WINDOW_CLASS_UNSUPPORTED;
}

const char *rtcore_handoff_window_class_name(
    rtcore_handoff_window_class window_class) {
  switch (window_class) {
    case RTCORE_HANDOFF_WINDOW_CLASS_SHARED_WORKGROUP:
      return "shared_workgroup";
    case RTCORE_HANDOFF_WINDOW_CLASS_LOCAL_PRIVATE:
      return "local_private";
    default:
      return "unsupported";
  }
}

bool rtcore_submit_handoff_window_class_is_valid(
    const ptx_instruction *pI, unsigned long long context_ptr,
    unsigned long long handoff_window_base, unsigned lane_slot_index) {
  const rtcore_handoff_window_class window_class =
      rtcore_classify_handoff_window(handoff_window_base);
  const bool shared_workgroup =
      window_class == RTCORE_HANDOFF_WINDOW_CLASS_SHARED_WORKGROUP;
  const bool accepted = shared_workgroup;

  printf("GPGPU-Sim PTX: RT_SUBMIT handoff-window-class (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, window_class=%s, shared_workgroup=%u, "
         "accepted=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         handoff_window_base, lane_slot_index,
         rtcore_handoff_window_class_name(window_class),
         shared_workgroup ? 1 : 0, accepted ? 1 : 0);
  fflush(stdout);

  if (!accepted) {
    const char *reason =
        window_class == RTCORE_HANDOFF_WINDOW_CLASS_LOCAL_PRIVATE
            ? "LOCAL_PRIVATE_HOT_WINDOW"
            : "UNSUPPORTED_WINDOW_CLASS";
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=%s, context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u, window_class=%s, consumed=0\n",
           pI->source_file(), pI->source_line(), reason, context_ptr,
           handoff_window_base, lane_slot_index,
           rtcore_handoff_window_class_name(window_class));
    fflush(stdout);
  }

  return accepted;
}

rtcore_symbolic_resource_profile rtcore_get_symbolic_resource_profile() {
  rtcore_symbolic_resource_profile profile;
  profile.shared_memory_bytes_available_per_execution_partition =
      rtcore_resource_env_u32(
          "VULKAN_SIM_RTCORE_SHARED_MEMORY_BYTES",
          RTCORE_SHARED_MEMORY_BYTES_PER_EXECUTION_PARTITION);
  profile.max_resident_warps_per_execution_partition =
      rtcore_resource_env_u32(
          "VULKAN_SIM_RTCORE_MAX_RESIDENT_WARPS",
          RTCORE_MAX_RESIDENT_WARPS_PER_EXECUTION_PARTITION);
  profile.max_active_lanes_per_rt_warp = RTCORE_MAX_LANES_PER_WARP;
  profile.handoff_window_bytes_per_active_rt_lane =
      RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE;
  profile.rt_tokens_per_execution_partition = rtcore_resource_env_u32(
      "VULKAN_SIM_RTCORE_RT_TOKENS",
      RTCORE_RT_TOKENS_PER_EXECUTION_PARTITION);
  profile.traversal_stack_entries_per_active_lane = rtcore_resource_env_u32(
      "VULKAN_SIM_RTCORE_TRAVERSAL_STACK_ENTRIES",
      RTCORE_TRAVERSAL_STACK_ENTRIES_PER_ACTIVE_LANE);
  profile.traversal_stack_entries_per_execution_partition =
      rtcore_resource_env_u32(
          "VULKAN_SIM_RTCORE_TRAVERSAL_STACK_ENTRIES_TOTAL",
          RTCORE_TRAVERSAL_STACK_ENTRIES_PER_EXECUTION_PARTITION);
  profile.full_warp_handoff_window_bytes =
      RTCORE_MAX_LANES_PER_WARP * RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE;
  profile.traversal_stack_entries_per_full_warp =
      rtcore_u64_to_u32_saturating(
          (unsigned long long)profile.max_active_lanes_per_rt_warp *
          profile.traversal_stack_entries_per_active_lane);
  profile.handoff_window_limited_warps =
      profile.full_warp_handoff_window_bytes == 0
          ? 0
          : profile.shared_memory_bytes_available_per_execution_partition /
                profile.full_warp_handoff_window_bytes;
  profile.token_limited_warps =
      profile.max_active_lanes_per_rt_warp == 0
          ? 0
          : profile.rt_tokens_per_execution_partition /
                profile.max_active_lanes_per_rt_warp;
  profile.traversal_stack_limited_warps =
      profile.traversal_stack_entries_per_full_warp == 0
          ? 0
          : profile.traversal_stack_entries_per_execution_partition /
                profile.traversal_stack_entries_per_full_warp;
  profile.resident_rt_warps = rtcore_min_u32(
      profile.max_resident_warps_per_execution_partition,
      rtcore_min_u32(profile.handoff_window_limited_warps,
                     rtcore_min_u32(profile.token_limited_warps,
                                    profile.traversal_stack_limited_warps)));
  return profile;
}

const char *rtcore_symbolic_resource_limit_name(
    const rtcore_symbolic_resource_profile &profile) {
  if (profile.handoff_window_limited_warps == 0) {
    return "HANDOFF_WINDOW_EXHAUSTED";
  }
  if (profile.token_limited_warps == 0) {
    return "RT_TOKEN_EXHAUSTED";
  }
  if (profile.traversal_stack_limited_warps == 0) {
    return "TRAVERSAL_STACK_EXHAUSTED";
  }
  if (profile.max_resident_warps_per_execution_partition == 0) {
    return "MAX_RESIDENT_WARPS_ZERO";
  }
  return "RESOURCE_EXHAUSTED";
}

void rtcore_log_symbolic_resource_profile_once(
    const rtcore_symbolic_resource_profile &profile) {
  if (g_rtcore_symbolic_resource_profile_logged) {
    return;
  }
  g_rtcore_symbolic_resource_profile_logged = true;

  printf("GPGPU-Sim PTX: RT resource-profile "
         "lanes_per_warp=%u, handoff_words_per_lane=%u, "
         "handoff_bytes_per_lane=%u, handoff_bytes_full_warp=%u, "
         "context_bytes_per_lane=%u, "
         "shared_memory_bytes_per_execution_partition=%u, "
         "max_resident_warps_per_execution_partition=%u, "
         "max_active_lanes_per_rt_warp=%u, "
         "handoff_window_bytes_per_active_rt_lane=%u, "
         "rt_tokens_per_execution_partition=%u, "
         "traversal_stack_entries_per_active_lane=%u, "
         "traversal_stack_entries_per_execution_partition=%u, "
         "traversal_stack_entries_per_full_warp=%u, "
         "handoff_window_limited_warps=%u, token_limited_warps=%u, "
         "traversal_stack_limited_warps=%u, "
         "resident_rt_warps=%u\n",
         RTCORE_MAX_LANES_PER_WARP, RTCORE_HANDOFF_WINDOW_WORDS_PER_LANE,
         RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE,
         RTCORE_HANDOFF_WINDOW_BYTES_PER_FULL_WARP,
         RTCORE_CONTEXT_BYTES_PER_LANE,
         profile.shared_memory_bytes_available_per_execution_partition,
         profile.max_resident_warps_per_execution_partition,
         profile.max_active_lanes_per_rt_warp,
         profile.handoff_window_bytes_per_active_rt_lane,
         profile.rt_tokens_per_execution_partition,
         profile.traversal_stack_entries_per_active_lane,
         profile.traversal_stack_entries_per_execution_partition,
         profile.traversal_stack_entries_per_full_warp,
         profile.handoff_window_limited_warps, profile.token_limited_warps,
         profile.traversal_stack_limited_warps,
         profile.resident_rt_warps);
  fflush(stdout);
}

bool rtcore_symbolic_submit_has_capacity(
    const ptx_instruction *pI, const rtcore_symbolic_resource_profile &profile,
    unsigned lane_slot_index, unsigned long long context_ptr,
    unsigned long long handoff_window_base) {
  const unsigned active_lane_mask = rtcore_active_thread_mask(pI);
  const unsigned active_lanes = rtcore_count_active_lanes(active_lane_mask);
  const bool resident_capacity_available = profile.resident_rt_warps != 0;

  printf("GPGPU-Sim PTX: RT_SUBMIT resource-check (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, active_lane_mask=0x%08x, active_lanes=%u, "
         "worst_case_divergent_lanes=%u, "
         "full_warp_handoff_window_bytes=%u, "
         "rt_tokens_per_execution_partition=%u, "
         "traversal_stack_entries_per_active_lane=%u, "
         "traversal_stack_entries_per_execution_partition=%u, "
         "traversal_stack_entries_per_full_warp=%u, "
         "traversal_stack_limited_warps=%u, "
         "resident_rt_warps=%u, capacity_available=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         handoff_window_base, lane_slot_index, active_lane_mask, active_lanes,
         RTCORE_MAX_LANES_PER_WARP, profile.full_warp_handoff_window_bytes,
         profile.rt_tokens_per_execution_partition,
         profile.traversal_stack_entries_per_active_lane,
         profile.traversal_stack_entries_per_execution_partition,
         profile.traversal_stack_entries_per_full_warp,
         profile.traversal_stack_limited_warps,
         profile.resident_rt_warps, resident_capacity_available ? 1 : 0);
  fflush(stdout);

  if (profile.resident_rt_warps == 0) {
    const char *resource_limit_name =
        rtcore_symbolic_resource_limit_name(profile);
    printf("GPGPU-Sim PTX: RT_SUBMIT resource-wait-or-reject (%s:%u), "
           "reason=%s, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "traversal_stack_entries_per_execution_partition=%u, "
           "traversal_stack_entries_per_full_warp=%u, "
           "traversal_stack_limited_warps=%u, resident_rt_warps=%u, "
           "consumed=0\n",
           pI->source_file(), pI->source_line(),
           resource_limit_name, context_ptr, handoff_window_base, lane_slot_index,
           profile.traversal_stack_entries_per_execution_partition,
           profile.traversal_stack_entries_per_full_warp,
           profile.traversal_stack_limited_warps, profile.resident_rt_warps);
    fflush(stdout);
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=%s, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "traversal_stack_entries_per_execution_partition=%u, "
           "traversal_stack_entries_per_full_warp=%u, "
           "traversal_stack_limited_warps=%u, resident_rt_warps=%u, "
           "capacity_available=0, consumed=0\n",
           pI->source_file(), pI->source_line(), resource_limit_name,
           context_ptr, handoff_window_base, lane_slot_index,
           profile.traversal_stack_entries_per_execution_partition,
           profile.traversal_stack_entries_per_full_warp,
           profile.traversal_stack_limited_warps, profile.resident_rt_warps);
    fflush(stdout);
  }

  return resident_capacity_available;
}

void rtcore_reject_symbolic_submit(const ptx_instruction *pI) {
  inst_not_implemented(pI);
}

bool rtcore_symbolic_submit_lane_is_active(
    const ptx_instruction *pI, unsigned lane_slot_index,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    unsigned active_lane_mask) {
  const unsigned lane_thread_mask =
      rtcore_lane_thread_mask(lane_slot_index);
  const bool test_active_mask_override =
      rtcore_test_inactive_lane_submit_enabled();
  if (test_active_mask_override) {
    active_lane_mask &= ~lane_thread_mask;
  }
  const bool lane_active =
      rtcore_lane_is_active_in_mask(active_lane_mask, lane_slot_index);

  printf("GPGPU-Sim PTX: RT_SUBMIT active-mask-check (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, test_active_mask_override=%u, "
         "active_lane_mask=0x%08x, lane_thread_mask=0x%08x, active=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         handoff_window_base, lane_slot_index,
         test_active_mask_override ? 1 : 0, active_lane_mask, lane_thread_mask,
         lane_active ? 1 : 0);
  fflush(stdout);

  if (!lane_active) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=INACTIVE_LANE_SUBMIT, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "active_lane_mask=0x%08x, lane_thread_mask=0x%08x, consumed=0\n",
           pI->source_file(), pI->source_line(), context_ptr,
           handoff_window_base, lane_slot_index, active_lane_mask,
           lane_thread_mask);
    fflush(stdout);
  }

  return lane_active;
}

bool rtcore_synthetic_handoff_window_is_live(
    const rtcore_synthetic_handoff_key &key) {
  return g_rtcore_synthetic_handoff_windows.find(key) !=
         g_rtcore_synthetic_handoff_windows.end();
}

bool rtcore_symbolic_submit_lane_slot_available(
    const ptx_instruction *pI, const rtcore_synthetic_handoff_key &key,
    unsigned long long context_ptr) {
  const bool live_slot = rtcore_synthetic_handoff_window_is_live(key);
  const bool slot_available = !live_slot;

  printf("GPGPU-Sim PTX: RT_SUBMIT lane-slot-check (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_sid=%u, owner_hw_wid=%u, "
         "live_slot=%u, slot_available=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         key.handoff_window_base, key.lane_slot_index, key.owner_hw_sid,
         key.owner_hw_wid, live_slot ? 1 : 0, slot_available ? 1 : 0);
  fflush(stdout);

  if (live_slot) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=LIVE_SLOT_OVERWRITE, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "owner_hw_sid=%u, owner_hw_wid=%u, consumed=0\n",
           pI->source_file(), pI->source_line(), context_ptr,
           key.handoff_window_base, key.lane_slot_index, key.owner_hw_sid,
           key.owner_hw_wid);
    fflush(stdout);
  }

  return slot_available;
}

rtcore_synthetic_handoff_key rtcore_make_synthetic_handoff_key(
    unsigned long long handoff_window_base, unsigned lane_slot_index,
    ptx_thread_info *thread) {
  rtcore_synthetic_handoff_key key;
  key.handoff_window_base = handoff_window_base;
  key.owner_hw_sid = thread->get_hw_sid();
  key.owner_hw_wid = thread->get_hw_wid();
  key.lane_slot_index = lane_slot_index;
  return key;
}

rtcore_symbolic_rt_token_key rtcore_make_symbolic_rt_token_key(
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    unsigned lane_slot_index, ptx_thread_info *thread) {
  rtcore_symbolic_rt_token_key key;
  key.context_ptr = context_ptr;
  key.handoff_window_base = handoff_window_base;
  key.owner_hw_sid = thread->get_hw_sid();
  key.owner_hw_wid = thread->get_hw_wid();
  key.owner_hw_tid = thread->get_hw_tid();
  key.lane_slot_index = lane_slot_index;
  return key;
}

rtcore_symbolic_rt_token_reservation_key
rtcore_make_symbolic_rt_token_reservation_key(
    const ptx_thread_info::rtcore_current_warp_metadata &metadata,
    unsigned long long context_ptr, unsigned long long handoff_window_base) {
  rtcore_symbolic_rt_token_reservation_key key;
  key.warp_uid = metadata.warp_uid;
  key.warp_id = metadata.warp_id;
  key.owner_hw_sid = metadata.owner_hw_sid;
  key.static_inst_uid = metadata.static_inst_uid;
  key.active_mask = metadata.active_mask;
  key.context_ptr = context_ptr;
  key.handoff_window_base = handoff_window_base;
  return key;
}

bool rtcore_symbolic_rt_token_is_live(
    const rtcore_symbolic_rt_token_key &key) {
  return g_rtcore_symbolic_rt_tokens.find(key) !=
         g_rtcore_symbolic_rt_tokens.end();
}

bool rtcore_symbolic_submit_token_available(
    const ptx_instruction *pI, const rtcore_symbolic_rt_token_key &key) {
  const bool live_token = rtcore_symbolic_rt_token_is_live(key);
  const bool token_available = !live_token;

  printf("GPGPU-Sim PTX: RT_SUBMIT token-check (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, live_token=%u, token_available=%u\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
         key.owner_hw_wid, key.owner_hw_sid, live_token ? 1 : 0,
         token_available ? 1 : 0);
  fflush(stdout);

  if (live_token) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=LIVE_TOKEN_REUSE, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "owner_hw_tid=%u, owner_hw_wid=%u, owner_hw_sid=%u, consumed=0\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
           key.owner_hw_wid, key.owner_hw_sid);
    fflush(stdout);
  }

  return token_available;
}

size_t rtcore_symbolic_rt_token_allocator_live_count() {
  return g_rtcore_symbolic_rt_token_allocator.live_allocations;
}

size_t rtcore_symbolic_rt_token_allocator_free_count() {
  return g_rtcore_symbolic_rt_token_allocator.free_slot_ids.size();
}

size_t rtcore_symbolic_rt_token_allocator_slot_count() {
  return g_rtcore_symbolic_rt_token_allocator.slots.size();
}

size_t rtcore_symbolic_rt_token_allocator_live_plus_reserved_count(
    unsigned reserved_tokens) {
  return rtcore_symbolic_rt_token_allocator_live_count() + reserved_tokens;
}

bool rtcore_symbolic_rt_token_allocator_has_capacity(
    const rtcore_symbolic_resource_profile &profile,
    unsigned reserved_tokens) {
  return rtcore_symbolic_rt_token_allocator_live_plus_reserved_count(
             reserved_tokens) <= profile.rt_tokens_per_execution_partition;
}

bool rtcore_symbolic_rt_token_allocator_record_matches(
    const rtcore_symbolic_rt_token_record &record) {
  if (record.allocator_slot_id == 0 || record.allocator_generation == 0) {
    return false;
  }
  std::map<unsigned, rtcore_symbolic_rt_token_allocator_slot>::const_iterator
      slot = g_rtcore_symbolic_rt_token_allocator.slots.find(
          record.allocator_slot_id);
  return slot != g_rtcore_symbolic_rt_token_allocator.slots.end() &&
         slot->second.live &&
         slot->second.generation == record.allocator_generation;
}

rtcore_symbolic_rt_token_allocation
rtcore_allocate_symbolic_rt_token_slot(
    const ptx_instruction *pI, const rtcore_symbolic_rt_token_key &key,
    const rtcore_symbolic_resource_profile &profile) {
  rtcore_symbolic_rt_token_allocation allocation;
  allocation.slot_id = 0;
  allocation.generation = 0;
  allocation.allocated = false;
  bool reused_slot = false;
  bool nominal_capacity_exhausted =
      g_rtcore_symbolic_rt_token_allocator.slots.size() >=
      profile.rt_tokens_per_execution_partition;
  bool capacity_oversubscribed = false;
  rtcore_symbolic_rt_token_allocator_slot *slot = NULL;

  if (!g_rtcore_symbolic_rt_token_allocator.free_slot_ids.empty()) {
    allocation.slot_id =
        g_rtcore_symbolic_rt_token_allocator.free_slot_ids.back();
    g_rtcore_symbolic_rt_token_allocator.free_slot_ids.pop_back();
    std::map<unsigned, rtcore_symbolic_rt_token_allocator_slot>::iterator
        free_slot =
            g_rtcore_symbolic_rt_token_allocator.slots.find(
                allocation.slot_id);
    if (free_slot != g_rtcore_symbolic_rt_token_allocator.slots.end() &&
        !free_slot->second.live) {
      slot = &free_slot->second;
      reused_slot = true;
    }
  } else {
    capacity_oversubscribed = nominal_capacity_exhausted;
    rtcore_symbolic_rt_token_allocator_slot new_slot;
    allocation.slot_id =
        g_rtcore_symbolic_rt_token_allocator.next_slot_id++;
    allocation.generation =
        g_rtcore_symbolic_rt_token_allocator.next_generation++;
    new_slot.slot_id = allocation.slot_id;
    new_slot.generation = allocation.generation;
    new_slot.live = false;
    std::pair<std::map<unsigned, rtcore_symbolic_rt_token_allocator_slot>::
                  iterator,
              bool>
        inserted = g_rtcore_symbolic_rt_token_allocator.slots.insert(
            std::make_pair(new_slot.slot_id, new_slot));
    if (inserted.second) {
      slot = &inserted.first->second;
    }
  }

  if (slot != NULL) {
    slot->live = true;
    allocation.slot_id = slot->slot_id;
    allocation.generation = slot->generation;
    allocation.allocated = true;
    g_rtcore_symbolic_rt_token_allocator.live_allocations++;
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT allocator-allocate (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, allocator_slot_id=%u, "
         "allocator_generation=%u, allocator_live=%zu, "
         "allocator_released=%zu, allocator_free=%zu, "
         "allocator_slots=%zu, allocator_slot_reused=%u, "
         "rt_tokens_per_execution_partition=%u, "
         "nominal_capacity_exhausted=%u, "
         "capacity_oversubscribed=%u, allocated=%u\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
         key.owner_hw_wid, key.owner_hw_sid, allocation.slot_id,
         allocation.generation,
         g_rtcore_symbolic_rt_token_allocator.live_allocations,
         g_rtcore_symbolic_rt_token_allocator.released_allocations,
         rtcore_symbolic_rt_token_allocator_free_count(),
         rtcore_symbolic_rt_token_allocator_slot_count(),
         reused_slot ? 1 : 0, profile.rt_tokens_per_execution_partition,
         nominal_capacity_exhausted ? 1 : 0,
         capacity_oversubscribed ? 1 : 0,
         allocation.allocated ? 1 : 0);
  fflush(stdout);

  return allocation;
}

bool rtcore_release_symbolic_rt_token_allocation(
    const rtcore_symbolic_rt_token_record &record) {
  const bool valid_metadata =
      record.allocator_slot_id != 0 && record.allocator_generation != 0;
  const bool valid_allocation =
      valid_metadata &&
      rtcore_symbolic_rt_token_allocator_record_matches(record);
  if (!valid_allocation ||
      g_rtcore_symbolic_rt_token_allocator.live_allocations == 0) {
    return false;
  }
  std::map<unsigned, rtcore_symbolic_rt_token_allocator_slot>::iterator slot =
      g_rtcore_symbolic_rt_token_allocator.slots.find(
          record.allocator_slot_id);
  slot->second.live = false;
  slot->second.generation =
      g_rtcore_symbolic_rt_token_allocator.next_generation++;
  g_rtcore_symbolic_rt_token_allocator.free_slot_ids.push_back(
      record.allocator_slot_id);
  g_rtcore_symbolic_rt_token_allocator.live_allocations--;
  g_rtcore_symbolic_rt_token_allocator.released_allocations++;
  return true;
}

bool rtcore_acquire_symbolic_rt_token(
    const ptx_instruction *pI, const rtcore_symbolic_rt_token_key &key,
    unsigned submit_transaction_id, unsigned result_word) {
  const rtcore_symbolic_resource_profile profile =
      rtcore_get_symbolic_resource_profile();
  const rtcore_symbolic_rt_token_allocation allocation =
      rtcore_allocate_symbolic_rt_token_slot(pI, key, profile);
  if (!allocation.allocated) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=RT_TOKEN_ALLOCATOR_EXHAUSTED_AT_ACQUIRE, "
           "context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u, rt_tokens_per_execution_partition=%u, "
           "allocator_live=%zu, allocator_free=%zu, allocator_slots=%zu, "
           "consumed=0\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, key.lane_slot_index,
           profile.rt_tokens_per_execution_partition,
           rtcore_symbolic_rt_token_allocator_live_count(),
           rtcore_symbolic_rt_token_allocator_free_count(),
           rtcore_symbolic_rt_token_allocator_slot_count());
    fflush(stdout);
    return false;
  }
  rtcore_symbolic_rt_token_record record;
  record.token_id = g_rtcore_next_symbolic_rt_token_id++;
  record.allocator_slot_id = allocation.slot_id;
  record.allocator_generation = allocation.generation;
  record.submit_transaction_id = submit_transaction_id;
  record.result_word = result_word;
  record.completed = false;

  const bool inserted =
      g_rtcore_symbolic_rt_tokens.insert(std::make_pair(key, record)).second;
  if (!inserted) {
    rtcore_release_symbolic_rt_token_allocation(record);
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT token-acquire (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, token_id=%u, allocator_slot_id=%u, "
         "allocator_generation=%u, submit_transaction_id=%u, "
         "result=0x%08x, "
         "acquired=%u, live_tokens=%zu, allocator_live=%zu, "
         "allocator_free=%zu, allocator_slots=%zu\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
         key.owner_hw_wid, key.owner_hw_sid, record.token_id,
         record.allocator_slot_id, record.allocator_generation,
         record.submit_transaction_id, record.result_word, inserted ? 1 : 0,
         g_rtcore_symbolic_rt_tokens.size(),
         rtcore_symbolic_rt_token_allocator_live_count(),
         rtcore_symbolic_rt_token_allocator_free_count(),
         rtcore_symbolic_rt_token_allocator_slot_count());
  fflush(stdout);

  if (!inserted) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=LIVE_TOKEN_REUSE_AT_ACQUIRE, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, consumed=0\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, key.lane_slot_index);
    fflush(stdout);
  }

  return inserted;
}

bool rtcore_complete_symbolic_rt_token(
    const ptx_instruction *pI, const rtcore_symbolic_rt_token_key &key,
    unsigned result_word) {
  std::map<rtcore_symbolic_rt_token_key,
           rtcore_symbolic_rt_token_record>::iterator token =
      g_rtcore_symbolic_rt_tokens.find(key);
  const bool live_token = token != g_rtcore_symbolic_rt_tokens.end();
  const unsigned allocator_slot_id =
      live_token ? token->second.allocator_slot_id : 0;
  const unsigned allocator_generation =
      live_token ? token->second.allocator_generation : 0;
  const bool allocator_record_matches =
      live_token &&
      rtcore_symbolic_rt_token_allocator_record_matches(token->second);
  const bool allocator_metadata_valid =
      allocator_record_matches;
  const bool result_matches = live_token && token->second.result_word == result_word;
  const bool completion_validated =
      live_token && allocator_metadata_valid && result_matches;
  const bool test_retire_before_completion =
      completion_validated && rtcore_test_retire_before_completion_enabled();

  if (completion_validated && !test_retire_before_completion) {
    token->second.completed = true;
  }
  const bool completed = live_token && token->second.completed;

  printf("GPGPU-Sim PTX: RT_SUBMIT token-complete (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, allocator_slot_id=%u, "
         "allocator_generation=%u, live_token=%u, "
         "allocator_metadata_valid=%u, result_match=%u, "
         "test_retire_before_completion=%u, "
         "completed=%u\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
         key.owner_hw_wid, key.owner_hw_sid, allocator_slot_id,
         allocator_generation, live_token ? 1 : 0,
         allocator_metadata_valid ? 1 : 0, result_matches ? 1 : 0,
         test_retire_before_completion ? 1 : 0,
         completed ? 1 : 0);
  fflush(stdout);

  return completion_validated;
}

size_t rtcore_synthetic_handoff_window_count();
size_t rtcore_symbolic_rt_token_count();
size_t rtcore_symbolic_rt_token_reservation_count();

bool rtcore_symbolic_rt_token_can_retire(
    const ptx_instruction *pI, const rtcore_symbolic_rt_token_key &key) {
  std::map<rtcore_symbolic_rt_token_key,
           rtcore_symbolic_rt_token_record>::const_iterator token =
      g_rtcore_symbolic_rt_tokens.find(key);
  const bool live_token = token != g_rtcore_symbolic_rt_tokens.end();
  const bool completed = live_token && token->second.completed;
  const bool allocator_record_matches =
      live_token &&
      rtcore_symbolic_rt_token_allocator_record_matches(token->second);
  const bool test_stale_allocator_generation =
      live_token && completed &&
      rtcore_test_stale_allocator_generation_enabled();
  const bool allocator_generation_matches =
      allocator_record_matches && !test_stale_allocator_generation;
  const bool accepted = live_token && completed && allocator_generation_matches;

  printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT token-check (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, live_token=%u, completed=%u, "
         "allocator_generation_matches=%u, "
         "test_stale_allocator_generation=%u, accepted=%u\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
         key.owner_hw_wid, key.owner_hw_sid, live_token ? 1 : 0,
         completed ? 1 : 0, allocator_generation_matches ? 1 : 0,
         test_stale_allocator_generation ? 1 : 0,
         accepted ? 1 : 0);
  fflush(stdout);

  if (!live_token) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "reason=TOKEN_NOT_LIVE, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "owner_hw_tid=%u, owner_hw_wid=%u, owner_hw_sid=%u\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
           key.owner_hw_wid, key.owner_hw_sid);
    fflush(stdout);
  } else if (!completed) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "reason=RETIRE_BEFORE_COMPLETION, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, "
           "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
           "owner_hw_sid=%u\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
           key.owner_hw_wid, key.owner_hw_sid);
    fflush(stdout);
  } else if (!allocator_generation_matches) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "reason=RT_TOKEN_ALLOCATOR_STALE_GENERATION, "
           "context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
           "owner_hw_sid=%u, remaining_windows=%zu, remaining_tokens=%zu, "
           "remaining_reservations=%zu, remaining_allocator_live=%zu\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, key.lane_slot_index, key.owner_hw_tid,
           key.owner_hw_wid, key.owner_hw_sid,
           rtcore_synthetic_handoff_window_count(),
           rtcore_symbolic_rt_token_count(),
           rtcore_symbolic_rt_token_reservation_count(),
           rtcore_symbolic_rt_token_allocator_live_count());
    fflush(stdout);
  }

  return accepted;
}

bool rtcore_release_symbolic_rt_token(
    const rtcore_symbolic_rt_token_key &key) {
  std::map<rtcore_symbolic_rt_token_key,
           rtcore_symbolic_rt_token_record>::iterator token =
      g_rtcore_symbolic_rt_tokens.find(key);
  if (token == g_rtcore_symbolic_rt_tokens.end()) {
    return false;
  }
  const bool released_allocation =
      rtcore_release_symbolic_rt_token_allocation(token->second);
  if (!released_allocation) {
    return false;
  }
  g_rtcore_symbolic_rt_tokens.erase(token);
  return released_allocation;
}

size_t rtcore_symbolic_rt_token_count() {
  return g_rtcore_symbolic_rt_tokens.size();
}

bool rtcore_cancel_symbolic_rt_token_reservation(
    const rtcore_symbolic_rt_token_reservation_key &key) {
  return g_rtcore_symbolic_rt_token_reservations.erase(key) == 1;
}

size_t rtcore_symbolic_rt_token_reservation_count() {
  return g_rtcore_symbolic_rt_token_reservations.size();
}

size_t rtcore_synthetic_handoff_window_count();

bool rtcore_symbolic_submit_token_reservation_available(
    const ptx_instruction *pI, const rtcore_symbolic_resource_profile &profile,
    const rtcore_symbolic_rt_token_reservation_key &key,
    const rtcore_symbolic_rt_token_key &token_key, unsigned lane_slot_index) {
  const size_t token_map_live_tokens = rtcore_symbolic_rt_token_count();
  const unsigned active_lanes = rtcore_count_active_lanes(key.active_mask);
  const unsigned reserved_tokens = active_lanes;
  const size_t allocator_live_tokens =
      rtcore_symbolic_rt_token_allocator_live_count();
  const size_t allocator_live_plus_reserved_tokens =
      rtcore_symbolic_rt_token_allocator_live_plus_reserved_count(
          reserved_tokens);
  const bool allocator_capacity_available =
      rtcore_symbolic_rt_token_allocator_has_capacity(
          profile, reserved_tokens);
  const size_t live_tokens = allocator_live_tokens;
  std::map<rtcore_symbolic_rt_token_reservation_key,
           rtcore_symbolic_rt_token_reservation_record>::iterator reservation =
      g_rtcore_symbolic_rt_token_reservations.find(key);
  const bool reservation_live =
      reservation != g_rtcore_symbolic_rt_token_reservations.end();
  bool reservation_inserted = false;
  bool capacity_oversubscribed = false;
  bool token_capacity_available = reservation_live;

  if (!reservation_live) {
    capacity_oversubscribed = !allocator_capacity_available;
    rtcore_symbolic_rt_token_reservation_record record;
    record.active_mask = key.active_mask;
    record.active_lanes = active_lanes;
    record.acquired_lane_mask = 0;
    reservation_inserted =
        g_rtcore_symbolic_rt_token_reservations.insert(
            std::make_pair(key, record))
            .second;
    token_capacity_available = reservation_inserted;
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT token-reservation-check (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, warp_uid=%u, static_inst_uid=%u, "
         "active_lane_mask=0x%08x, active_lanes=%u, "
         "reservation_live=%u, reservation_inserted=%u, "
         "reserved_tokens=%u, rt_tokens_per_execution_partition=%u, "
         "live_tokens=%zu, token_map_live_tokens=%zu, "
         "allocator_live_tokens=%zu, allocator_reserved_tokens=%u, "
         "allocator_live_plus_reserved_tokens=%zu, "
         "allocator_capacity_available=%u, capacity_oversubscribed=%u, "
         "token_capacity_available=%u\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, lane_slot_index, token_key.owner_hw_tid,
         key.warp_id, key.owner_hw_sid, key.warp_uid, key.static_inst_uid,
         key.active_mask, active_lanes, reservation_live ? 1 : 0,
         reservation_inserted ? 1 : 0, reserved_tokens,
         profile.rt_tokens_per_execution_partition, live_tokens,
         token_map_live_tokens, allocator_live_tokens, reserved_tokens,
         allocator_live_plus_reserved_tokens,
         allocator_capacity_available ? 1 : 0,
         capacity_oversubscribed ? 1 : 0,
         token_capacity_available ? 1 : 0);
  fflush(stdout);

  if (capacity_oversubscribed) {
    printf("GPGPU-Sim PTX: RT_SUBMIT token-resource-backpressure (%s:%u), "
           "diagnostic=RT_SUBMIT token-reservation-capacity, "
           "context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "owner_hw_tid=%u, owner_hw_wid=%u, owner_hw_sid=%u, "
           "warp_uid=%u, static_inst_uid=%u, active_lane_mask=0x%08x, "
           "active_lanes=%u, reservation_live=%u, reserved_tokens=%u, "
           "rt_tokens_per_execution_partition=%u, live_tokens=%zu, "
           "token_map_live_tokens=%zu, allocator_live_tokens=%zu, "
           "allocator_reserved_tokens=%u, "
           "allocator_live_plus_reserved_tokens=%zu, "
           "allocator_capacity_available=%u, capacity_oversubscribed=%u, "
           "token_capacity_available=%u, remaining_windows=%zu, "
           "remaining_tokens=%zu, remaining_reservations=%zu, "
           "remaining_allocator_live=%zu, action=oversubscribe, "
           "functional_progress=1, consumed=0\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, lane_slot_index, token_key.owner_hw_tid,
           key.warp_id, key.owner_hw_sid, key.warp_uid, key.static_inst_uid,
           key.active_mask, active_lanes, reservation_live ? 1 : 0,
           reserved_tokens, profile.rt_tokens_per_execution_partition,
           live_tokens, token_map_live_tokens, allocator_live_tokens,
           reserved_tokens, allocator_live_plus_reserved_tokens,
           allocator_capacity_available ? 1 : 0,
           capacity_oversubscribed ? 1 : 0,
           token_capacity_available ? 1 : 0,
           rtcore_synthetic_handoff_window_count(),
           rtcore_symbolic_rt_token_count(),
           rtcore_symbolic_rt_token_reservation_count(),
           rtcore_symbolic_rt_token_allocator_live_count());
    fflush(stdout);
  }

  return token_capacity_available;
}

bool rtcore_symbolic_submit_issue_token_backpressure_enabled() {
  const char *value = getenv("VULKAN_SIM_RTCORE_TOKEN_BACKPRESSURE");
  return value != NULL && *value != '\0' && strcmp(value, "0") != 0;
}

bool rtcore_symbolic_submit_issue_resource_backpressure_enabled() {
  const char *value = getenv("VULKAN_SIM_RTCORE_ISSUE_RESOURCE_BACKPRESSURE");
  if (value != NULL && *value != '\0' && strcmp(value, "0") != 0) {
    return true;
  }
  return rtcore_symbolic_submit_issue_token_backpressure_enabled();
}

extern "C" bool
rtcore_symbolic_submit_issue_resource_backpressure_is_enabled() {
  return rtcore_symbolic_submit_issue_resource_backpressure_enabled();
}

struct rtcore_symbolic_submit_issue_resource_snapshot {
  unsigned warp_id;
  unsigned owner_hw_sid;
  unsigned active_lane_mask;
  unsigned long long static_inst_pc;
  unsigned active_lanes;
  unsigned rt_tokens_per_execution_partition;
  size_t allocator_live_tokens;
  size_t allocator_live_plus_demand_tokens;
  bool demand_exceeds_capacity;
  size_t handoff_live_slots;
  size_t handoff_slot_capacity;
  size_t handoff_live_plus_demand_slots;
  bool handoff_demand_exceeds_capacity;
  bool handoff_capacity_available;
  unsigned handoff_window_limited_warps;
  unsigned traversal_stack_limited_warps;
  unsigned resident_rt_warps;
  bool token_capacity_available;
  bool capacity_available;
};

rtcore_symbolic_submit_issue_resource_snapshot
rtcore_make_submit_issue_resource_snapshot(
    unsigned warp_id, unsigned owner_hw_sid, unsigned active_mask,
    unsigned long long static_inst_pc) {
  const rtcore_symbolic_resource_profile profile =
      rtcore_get_symbolic_resource_profile();
  const unsigned active_lanes = rtcore_count_active_lanes(active_mask);
  const size_t allocator_live_tokens =
      rtcore_symbolic_rt_token_allocator_live_count();
  const bool demand_exceeds_capacity =
      active_lanes > profile.rt_tokens_per_execution_partition;
  const size_t allocator_live_plus_demand_tokens =
      allocator_live_tokens + active_lanes;
  const bool token_capacity_available =
      active_lanes == 0 || demand_exceeds_capacity ||
      allocator_live_plus_demand_tokens <=
          profile.rt_tokens_per_execution_partition;
  const size_t handoff_live_slots =
      rtcore_synthetic_handoff_window_count();
  const size_t handoff_slot_capacity =
      (size_t)profile.handoff_window_limited_warps *
      profile.max_active_lanes_per_rt_warp;
  const size_t handoff_live_plus_demand_slots =
      handoff_live_slots + active_lanes;
  const bool handoff_demand_exceeds_capacity =
      active_lanes > handoff_slot_capacity;
  const bool handoff_capacity_available =
      active_lanes == 0 || handoff_demand_exceeds_capacity ||
      handoff_live_plus_demand_slots <= handoff_slot_capacity;

  rtcore_symbolic_submit_issue_resource_snapshot snapshot;
  snapshot.warp_id = warp_id;
  snapshot.owner_hw_sid = owner_hw_sid;
  snapshot.active_lane_mask = active_mask;
  snapshot.static_inst_pc = static_inst_pc;
  snapshot.active_lanes = active_lanes;
  snapshot.rt_tokens_per_execution_partition =
      profile.rt_tokens_per_execution_partition;
  snapshot.allocator_live_tokens = allocator_live_tokens;
  snapshot.allocator_live_plus_demand_tokens =
      allocator_live_plus_demand_tokens;
  snapshot.demand_exceeds_capacity = demand_exceeds_capacity;
  snapshot.handoff_live_slots = handoff_live_slots;
  snapshot.handoff_slot_capacity = handoff_slot_capacity;
  snapshot.handoff_live_plus_demand_slots = handoff_live_plus_demand_slots;
  snapshot.handoff_demand_exceeds_capacity =
      handoff_demand_exceeds_capacity;
  snapshot.handoff_capacity_available = handoff_capacity_available;
  snapshot.handoff_window_limited_warps = profile.handoff_window_limited_warps;
  snapshot.traversal_stack_limited_warps =
      profile.traversal_stack_limited_warps;
  snapshot.resident_rt_warps = profile.resident_rt_warps;
  snapshot.token_capacity_available = token_capacity_available;
  snapshot.capacity_available =
      token_capacity_available && handoff_capacity_available;
  return snapshot;
}

extern "C" bool rtcore_symbolic_submit_issue_resources_available(
    unsigned warp_id, unsigned owner_hw_sid, unsigned active_mask,
    unsigned long long static_inst_pc) {
  if (!rtcore_symbolic_submit_issue_resource_backpressure_enabled()) {
    return true;
  }

  const rtcore_symbolic_submit_issue_resource_snapshot snapshot =
      rtcore_make_submit_issue_resource_snapshot(
          warp_id, owner_hw_sid, active_mask, static_inst_pc);

  if (!snapshot.capacity_available) {
    const char *backpressure_kind =
        !snapshot.token_capacity_available
            ? "token-resource-backpressure"
            : "handoff-slot-backpressure";
    printf("GPGPU-Sim PTX: RT_SUBMIT %s, "
           "diagnostic=RT_SUBMIT issue-resource-snapshot, "
           "warp_id=%u, owner_hw_sid=%u, static_inst_pc=0x%llx, "
           "active_lane_mask=0x%08x, active_lanes=%u, "
           "rt_tokens_per_execution_partition=%u, "
           "allocator_live_tokens=%zu, "
           "allocator_live_plus_demand_tokens=%zu, "
           "demand_exceeds_capacity=%u, "
           "handoff_live_slots=%zu, handoff_slot_capacity=%zu, "
           "handoff_live_plus_demand_slots=%zu, "
           "handoff_demand_exceeds_capacity=%u, "
           "handoff_window_limited_warps=%u, "
           "traversal_stack_limited_warps=%u, resident_rt_warps=%u, "
           "token_capacity_available=%u, handoff_capacity_available=%u, "
           "capacity_available=0, "
           "action=stall\n",
           backpressure_kind, snapshot.warp_id, snapshot.owner_hw_sid,
           snapshot.static_inst_pc,
           snapshot.active_lane_mask, snapshot.active_lanes,
           snapshot.rt_tokens_per_execution_partition,
           snapshot.allocator_live_tokens,
           snapshot.allocator_live_plus_demand_tokens,
           snapshot.demand_exceeds_capacity ? 1 : 0,
           snapshot.handoff_live_slots, snapshot.handoff_slot_capacity,
           snapshot.handoff_live_plus_demand_slots,
           snapshot.handoff_demand_exceeds_capacity ? 1 : 0,
           snapshot.handoff_window_limited_warps,
           snapshot.traversal_stack_limited_warps,
           snapshot.resident_rt_warps,
           snapshot.token_capacity_available ? 1 : 0,
           snapshot.handoff_capacity_available ? 1 : 0);
    fflush(stdout);
  }

  return snapshot.capacity_available;
}

extern "C" bool rtcore_symbolic_submit_issue_has_token_capacity(
    unsigned warp_id, unsigned owner_hw_sid, unsigned active_mask,
    unsigned long long static_inst_pc) {
  return rtcore_symbolic_submit_issue_resources_available(
      warp_id, owner_hw_sid, active_mask, static_inst_pc);
}

bool rtcore_note_symbolic_rt_token_reservation_lane_acquired(
    const ptx_instruction *pI,
    const rtcore_symbolic_rt_token_reservation_key &key,
    unsigned lane_slot_index) {
  std::map<rtcore_symbolic_rt_token_reservation_key,
           rtcore_symbolic_rt_token_reservation_record>::iterator reservation =
      g_rtcore_symbolic_rt_token_reservations.find(key);
  const bool reservation_live =
      reservation != g_rtcore_symbolic_rt_token_reservations.end();
  const unsigned lane_thread_mask = rtcore_lane_thread_mask(lane_slot_index);
  unsigned acquired_lane_mask = 0;
  unsigned active_lanes = 0;
  bool reservation_complete = false;

  if (reservation_live) {
    reservation->second.acquired_lane_mask |= lane_thread_mask;
    acquired_lane_mask = reservation->second.acquired_lane_mask;
    active_lanes = reservation->second.active_lanes;
    reservation_complete =
        (acquired_lane_mask & reservation->second.active_mask) ==
        reservation->second.active_mask;
    if (reservation_complete) {
      g_rtcore_symbolic_rt_token_reservations.erase(reservation);
    }
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT token-reservation-acquire (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, warp_uid=%u, static_inst_uid=%u, "
         "active_lane_mask=0x%08x, active_lanes=%u, "
         "lane_thread_mask=0x%08x, acquired_lane_mask=0x%08x, "
         "reservation_live=%u, reservation_complete=%u\n",
         pI->source_file(), pI->source_line(), key.context_ptr,
         key.handoff_window_base, lane_slot_index, key.warp_uid,
         key.static_inst_uid, key.active_mask, active_lanes,
         lane_thread_mask, acquired_lane_mask, reservation_live ? 1 : 0,
         reservation_complete ? 1 : 0);
  fflush(stdout);

  if (!reservation_live) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=RT_TOKEN_RESERVATION_MISSING, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "warp_uid=%u, static_inst_uid=%u, consumed=0\n",
           pI->source_file(), pI->source_line(), key.context_ptr,
           key.handoff_window_base, lane_slot_index, key.warp_uid,
           key.static_inst_uid);
    fflush(stdout);
  }

  return reservation_live;
}

void rtcore_populate_synthetic_owner_tuple(
    rtcore_v03_handoff_lane_slot *slot,
    const rtcore_synthetic_handoff_key &key, ptx_thread_info *thread,
    unsigned thread_mask) {
  slot->handoff_window_base = key.handoff_window_base;
  slot->lane_slot_index = key.lane_slot_index;
  slot->lane_slot_base = rtcore_handoff_lane_slot_base(
      key.handoff_window_base, key.lane_slot_index);
  slot->owner_hw_tid = thread->get_hw_tid();
  slot->owner_hw_wid = thread->get_hw_wid();
  slot->owner_hw_sid = thread->get_hw_sid();
  slot->thread_mask = thread_mask;
  slot->window_state = RTCORE_WINDOW_STATE_COMPLETE;
}

bool rtcore_synthetic_owner_tuple_matches(
    const rtcore_v03_handoff_lane_slot &window,
    const rtcore_synthetic_handoff_key &key, unsigned long long context_ptr,
    const ptx_instruction *pI, ptx_thread_info *thread) {
  const unsigned lane_thread_mask =
      rtcore_lane_thread_mask(key.lane_slot_index);
  return window.context_ptr == context_ptr &&
         window.handoff_window_base == key.handoff_window_base &&
         window.lane_slot_index == key.lane_slot_index &&
         window.owner_hw_sid == key.owner_hw_sid &&
         window.owner_hw_wid == key.owner_hw_wid &&
         window.lane_slot_base == rtcore_handoff_lane_slot_base(
                                      key.handoff_window_base,
                                      key.lane_slot_index) &&
         window.owner_hw_tid == thread->get_hw_tid() &&
         window.owner_hw_wid == thread->get_hw_wid() &&
         window.owner_hw_sid == thread->get_hw_sid() &&
         (window.thread_mask & lane_thread_mask) != 0 &&
         window.window_state == RTCORE_WINDOW_STATE_COMPLETE;
}

static bool rtcore_shader_return_application_required() {
  return rtcore_oracle_shader_boundary_continuation_enabled();
}

static bool rtcore_v04_functional_only_commit_resubmit_stage(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned static_inst_uid, unsigned active_mask,
    unsigned previous_warp_uid) {
  std::map<unsigned,
           rtcore_v04_functional_only_resubmit_stage>::iterator stage =
      g_rtcore_v04_functional_only_resubmit_stages.find(warp_uid);
  const rtcore_v04_functional_only_warp_key key =
      std::make_pair(owner_hw_sid, warp_id);
  std::map<rtcore_v04_functional_only_warp_key,
           rtcore_v04_functional_only_warp_record>::iterator live =
      g_rtcore_v04_functional_only_live_warps.find(key);
  if (stage == g_rtcore_v04_functional_only_resubmit_stages.end() ||
      !stage->second.valid ||
      stage->second.previous_warp_uid != previous_warp_uid ||
      !stage->second.next_record.valid ||
      stage->second.next_record.owner_hw_sid != owner_hw_sid ||
      stage->second.next_record.warp_uid != warp_uid ||
      stage->second.next_record.warp_id != warp_id ||
      stage->second.next_record.static_inst_uid != static_inst_uid ||
      stage->second.next_record.active_mask != active_mask ||
      live == g_rtcore_v04_functional_only_live_warps.end() ||
      live->second.warp_uid != previous_warp_uid) {
    return false;
  }
  request_owner::allocator_state_v0 &allocator =
      rtcore_v04_functional_only_allocator(owner_hw_sid);
  if (request_owner::commit_mask_shrink(
          &allocator, stage->second.owner_plan) !=
      request_owner::kStatusOk) {
    return false;
  }
  const rtcore_v04_functional_only_warp_record previous = live->second;
  live->second = stage->second.next_record;
  g_rtcore_v04_functional_only_resubmit_stages.erase(stage);
  rtcore_v04_functional_only_record_warp_or_abort(
      rtcore::v04::conservation::kEventResubmit, previous,
      previous_warp_uid, active_mask);
  return true;
}

extern "C" bool rtcore_v04_functional_only_retire_lane_quiescent(
    unsigned owner_hw_sid, unsigned warp_id, unsigned lane_id,
    unsigned thread_uid, unsigned long long context_ptr,
    unsigned long long handoff_window_base, const char **failure_reason) {
  const char *reason = "accepted";
  const rtcore_v04_functional_only_warp_key key =
      std::make_pair(owner_hw_sid, warp_id);
  std::map<rtcore_v04_functional_only_warp_key,
           rtcore_v04_functional_only_warp_record>::const_iterator warp =
      g_rtcore_v04_functional_only_live_warps.find(key);
  if (!rtcore_v04_functional_only_engine_gate_active()) {
    reason = "FUNCTIONAL_ONLY_ENGINE_DISABLED";
  } else if (warp == g_rtcore_v04_functional_only_live_warps.end() ||
             !warp->second.valid) {
    reason = "FUNCTIONAL_ONLY_RESIDENT_WARP_MISSING";
  }

  const unsigned lane_mask =
      lane_id < kRtcoreV04FunctionalOnlyLaneCapacity ? 1u << lane_id : 0;
  const rtcore_v04_functional_only_lane_record *lane = NULL;
  bool lane_released_by_mask_shrink = false;
  if (strcmp(reason, "accepted") == 0 &&
      (lane_mask == 0 ||
       (warp->second.bound_lane_mask & lane_mask) == 0)) {
    reason = "FUNCTIONAL_ONLY_RETIRE_LANE_NOT_BOUND";
  } else if (strcmp(reason, "accepted") == 0) {
    lane = &warp->second.lane[lane_id];
    lane_released_by_mask_shrink =
        (warp->second.active_mask & lane_mask) == 0;
  }
  if (lane != NULL && lane_released_by_mask_shrink && lane->valid) {
    reason = "FUNCTIONAL_ONLY_MASK_SHRINK_LANE_STILL_LIVE";
  } else if (lane != NULL && !lane_released_by_mask_shrink &&
      (!lane->valid || lane->thread_uid != thread_uid ||
       lane->context_ptr != context_ptr ||
       lane->handoff_window_base != handoff_window_base)) {
    reason = "FUNCTIONAL_ONLY_RETIRE_LANE_IDENTITY_MISMATCH";
  }
  if (lane != NULL && !lane_released_by_mask_shrink &&
      strcmp(reason, "accepted") == 0 &&
      (!lane->initial_output_consumed || !lane->engine_state.valid ||
       lane->engine_state.waiting_shader || !lane->engine_state.terminal ||
       !lane->engine_output.valid || lane->engine_output.waiting_shader ||
       !lane->engine_output.terminal)) {
    reason = "FUNCTIONAL_ONLY_RETIRE_LANE_NOT_QUIESCENT";
  }
  if (strcmp(reason, "accepted") == 0) {
    printf("GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_RETIRE_PREFLIGHT "
           "owner_hw_sid=%u submit_warp_uid=%u warp_id=%u lane_id=%u "
           "active_mask=0x%08x bound_lane_mask=0x%08x "
           "terminal=%u waiting_shader=0 mask_shrink_released=%u "
           "timing_state_read=0 result=accepted\n",
           owner_hw_sid, warp->second.warp_uid, warp_id, lane_id,
           warp->second.active_mask, warp->second.bound_lane_mask,
           lane_released_by_mask_shrink ? 0u : 1u,
           lane_released_by_mask_shrink ? 1u : 0u);
    fflush(stdout);
  }
  if (failure_reason != NULL) {
    *failure_reason = reason;
  }
  return strcmp(reason, "accepted") == 0;
}

static void rtcore_v04_functional_only_discard_resubmit_stage(
    unsigned warp_uid) {
  g_rtcore_v04_functional_only_resubmit_stages.erase(warp_uid);
}

static bool rtcore_v04_functional_only_publish_resubmit(
    const ptx_instruction *pI,
    const ptx_thread_info::rtcore_current_warp_metadata &metadata,
    ptx_thread_info *const *lane_threads);

static float rtcore_shader_return_word_to_float(unsigned word) {
  float value = 0.0f;
  memcpy(&value, &word, sizeof(value));
  return value;
}

static bool rtcore_observe_v04_shadow_shader_return(
    ptx_thread_info *thread, unsigned lane_id,
    unsigned long long handoff_window_base, uint32_t boundary_reason,
    const rtcore::abi_v04::shadow::boundary_return_update &expected_update,
    unsigned long long observation_cycle, const char **failure_reason) {
  const char *failure = "accepted";
  if (thread == NULL || thread->get_global_memory() == NULL ||
      lane_id >= RTCORE_MAX_LANES_PER_WARP || handoff_window_base == 0) {
    failure = "V04_SHADOW_SHADER_RETURN_CONTEXT_MISSING";
  }

  const uint64_t lane_offset =
      (uint64_t)lane_id * rtcore::abi_v04::kLaneSlotBytes;
  const uint64_t lane_address = handoff_window_base + lane_offset;
  if (strcmp(failure, "accepted") == 0 &&
      lane_address < handoff_window_base) {
    failure = "V04_SHADOW_SHADER_RETURN_ADDRESS_OVERFLOW";
  }

  std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
  if (strcmp(failure, "accepted") == 0) {
    std::array<uint8_t, rtcore::abi_v04::kLaneSlotBytes> image = {};
    thread->get_global_memory()->read_simulator_backing(
        (mem_addr_t)lane_address, image.size(), image.data());
    words = rtcore::abi_v04::decode_words_le(image);
  }

  const char *mutation =
      getenv("VULKAN_SIM_RTCORE_TEST_V04_SHADOW_SHADER_RETURN_MUTATION");
  bool mutation_valid = mutation == NULL || mutation[0] == '\0' ||
                        strcmp(mutation, "none") == 0;
  if (strcmp(failure, "accepted") == 0 && mutation != NULL &&
      strcmp(mutation, "effect") == 0) {
    words[rtcore::abi_v04::kCommitRetainedCandidate.word] ^= 1u;
    mutation_valid = true;
  } else if (strcmp(failure, "accepted") == 0 && mutation != NULL &&
             strcmp(mutation, "reported_t") == 0) {
    words[rtcore::abi_v04::kReportedTFp32.word] ^= 1u;
    mutation_valid = true;
  } else if (strcmp(failure, "accepted") == 0 && mutation != NULL &&
             strcmp(mutation, "reserved") == 0) {
    words[rtcore::abi_v04::kCommitRetainedCandidate.word] |= 1u << 3;
    mutation_valid = true;
  } else if (strcmp(failure, "accepted") == 0 && mutation != NULL &&
             strcmp(mutation, "terminate") == 0) {
    words[rtcore::abi_v04::kTerminateSearch.word] |=
        rtcore::abi_v04::kTerminateSearch.mask;
    mutation_valid = true;
  } else if (strcmp(failure, "accepted") == 0 && mutation != NULL &&
             strcmp(mutation, "attributes") == 0) {
    rtcore::abi_v04::insert_field(
        words, rtcore::abi_v04::kReportedAttributeWordCount, 1u);
    rtcore::abi_v04::insert_field(
        words, rtcore::abi_v04::kReportedAttributeFormat, 2u);
    mutation_valid = true;
  }
  if (strcmp(failure, "accepted") == 0 && !mutation_valid) {
    failure = "V04_SHADOW_SHADER_RETURN_MUTATION_INVALID";
  }

  rtcore::abi_v04::shadow::shader_return_observation observation;
  if (strcmp(failure, "accepted") == 0) {
    observation = rtcore::abi_v04::shadow::compare_shader_return_words(
        words, boundary_reason, expected_update);
    if (!observation.valid()) {
      failure = rtcore::abi_v04::shadow::shader_return_error_name(
          observation.error);
    }
  }
  const bool valid = strcmp(failure, "accepted") == 0;
  if (failure_reason != NULL) {
    *failure_reason = failure;
  }
  printf("GPGPU-Sim RTCORE_V04_SHADOW_SHADER_RETURN_OBSERVATION "
         "profile=%s lane_id=%u handoff_window_base=0x%llx "
         "lane_address=0x%llx boundary_reason=%u traversal_effect=%u "
         "decoded_action=%u expected_action=%u mutation=%s "
         "mutation_valid=%u observation_only=1 functional_authority=0 "
         "resubmit_authority=0 terminal_write=0 observation_cycle=%llu "
         "result=%s\n",
         rtcore::abi_v04::kProfileId, lane_id, handoff_window_base,
         (unsigned long long)lane_address, boundary_reason,
         observation.traversal_effect,
         static_cast<unsigned>(observation.update.action),
         static_cast<unsigned>(expected_update.action),
         mutation != NULL && mutation[0] != '\0' ? mutation : "none",
         mutation_valid ? 1u : 0u, observation_cycle,
         valid ? "matched" : failure);
  fflush(stdout);
  return valid;
}

static bool rtcore_apply_shader_visible_resubmit_lane_return(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned owner_hw_sid, unsigned previous_warp_uid, unsigned warp_uid,
    unsigned warp_id, unsigned lane_id,
    unsigned long long handoff_window_base, unsigned long long apply_cycle,
    rtcore::abi_v04::shadow::boundary_return_update *v04_return_update,
    uint32_t *v04_boundary_reason,
    const char **failure_reason) {
  const char *failure = "accepted";
  const char *action = "unsupported";
  unsigned reason = 0;
  unsigned shader_return_words[3] = {};
  unsigned boundary_geometry_index = 0;
  int32_t shader_counter = -1;
  int32_t shader_type = -1;
  bool v04_commit_current_candidate = false;
  uint32_t v04_reported_t_fp32 = 0;
  uint32_t v04_reported_hit_kind = 0;
  uint32_t v04_reported_attribute_word_count = 0;
  uint32_t v04_reported_attribute_format = 0;

  if (v04_return_update != NULL) {
    *v04_return_update =
        rtcore::abi_v04::shadow::boundary_return_update();
  }
  if (v04_boundary_reason != NULL) {
    *v04_boundary_reason = rtcore::abi_v04::kReasonNoneOrInvalid;
  }

  if (thread == NULL || thread->RT_thread_data == NULL ||
      thread->RT_thread_data->traversal_data.empty() ||
      handoff_window_base == 0 || lane_id >= RTCORE_MAX_LANES_PER_WARP) {
    failure = "SHADER_RETURN_APPLY_CONTEXT_MISSING";
  }

  Traversal_data *traversal_data = NULL;
  memory_space *mem = NULL;
  if (strcmp(failure, "accepted") == 0) {
    traversal_data = thread->RT_thread_data->traversal_data.back();
    mem = thread->get_global_memory();
    if (traversal_data == NULL || mem == NULL) {
      failure = "SHADER_RETURN_APPLY_TRAVERSAL_STATE_MISSING";
    }
  }

  if (strcmp(failure, "accepted") == 0) {
    const unsigned long long shader_return_base =
        handoff_window_base +
        lane_id * RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE +
        RTCORE_HANDOFF_W_SHADER_RETURN_BEGIN * sizeof(unsigned);
    const unsigned long long boundary_geometry_index_addr =
        handoff_window_base +
        lane_id * RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE +
        RTCORE_HANDOFF_W_GEOMETRY_INDEX * sizeof(unsigned);
    mem->read_simulator_backing(shader_return_base,
                                sizeof(shader_return_words),
                                shader_return_words);
    mem->read_simulator_backing(boundary_geometry_index_addr,
                                sizeof(boundary_geometry_index),
                                &boundary_geometry_index);
    mem->read(&(traversal_data->current_shader_counter),
              sizeof(traversal_data->current_shader_counter),
              &shader_counter);
    mem->read(&(traversal_data->current_shader_type),
              sizeof(traversal_data->current_shader_type), &shader_type);
    if ((shader_return_words[0] & 0xffffff00u) != 0) {
      failure = "SHADER_RETURN_HIT_RESULT_RESERVED_BITS";
    }
  }

  const unsigned hit_result = shader_return_words[0] & 0xffu;
  if (strcmp(failure, "accepted") == 0 && shader_type == 2) {
    reason = RTCORE_RETURN_FOR_ANY_HIT;
    if (hit_result != RTCORE_HIT_RESULT_ACCEPT_HIT &&
        hit_result != RTCORE_HIT_RESULT_IGNORE_HIT) {
      failure = "SHADER_RETURN_ANYHIT_RESULT_INVALID";
    } else if (shader_counter < 0 ||
               static_cast<size_t>(shader_counter) >=
                   thread->RT_thread_data->all_hit_data.size()) {
      failure = "SHADER_RETURN_ANYHIT_CANDIDATE_MISSING";
    }

    Hit_data *candidate_address = NULL;
    Hit_data candidate = {};
    if (strcmp(failure, "accepted") == 0) {
      candidate_address =
          thread->RT_thread_data->all_hit_data[shader_counter];
      if (candidate_address == NULL) {
        failure = "SHADER_RETURN_ANYHIT_CANDIDATE_MISSING";
      } else {
        mem->read(candidate_address, sizeof(candidate), &candidate);
      }
    }

    if (strcmp(failure, "accepted") == 0 &&
        hit_result == RTCORE_HIT_RESULT_IGNORE_HIT) {
      const float invalid_hit = -1.0f;
      mem->write(&(candidate_address->world_min_thit), sizeof(invalid_hit),
                 &invalid_hit, thread, pI);
      action = "anyhit_ignore_invalidated";
    } else if (strcmp(failure, "accepted") == 0) {
      if (!(candidate.world_min_thit > 0.0f) ||
          candidate.geometryType != VK_GEOMETRY_TYPE_TRIANGLES_KHR) {
        failure = "SHADER_RETURN_ANYHIT_ACCEPT_CANDIDATE_INVALID";
      } else {
        v04_commit_current_candidate = true;
        bool hit_geometry = false;
        Hit_data closest_hit = {};
        mem->read(&(traversal_data->hit_geometry),
                  sizeof(traversal_data->hit_geometry), &hit_geometry);
        if (hit_geometry) {
          mem->read(&(traversal_data->closest_hit),
                    sizeof(traversal_data->closest_hit), &closest_hit);
        }
        const bool commit_candidate =
            !hit_geometry ||
            candidate.world_min_thit < closest_hit.world_min_thit;
        if (commit_candidate) {
          hit_geometry = true;
          thread->RT_thread_data->set_hitAttribute(
              candidate.barycentric_coordinates, pI, thread);
          mem->write(&(traversal_data->hit_geometry),
                     sizeof(traversal_data->hit_geometry), &hit_geometry,
                     thread, pI);
          mem->write(&(traversal_data->closest_hit),
                     sizeof(traversal_data->closest_hit), &candidate, thread,
                     pI);
          action = "anyhit_accept_committed";
        } else {
          action = "anyhit_accept_kept_closer";
        }
      }
    }
  } else if (strcmp(failure, "accepted") == 0 && shader_type == 1) {
    reason = RTCORE_RETURN_FOR_INTERSECTION;
    if (hit_result != RTCORE_HIT_RESULT_CONTINUE_OR_NONE &&
        hit_result != RTCORE_HIT_RESULT_REPORTED_INTERSECTION) {
      failure = "SHADER_RETURN_INTERSECTION_RESULT_INVALID";
    } else if (shader_counter < 0) {
      failure = "SHADER_RETURN_INTERSECTION_CANDIDATE_MISSING";
    } else if (hit_result == RTCORE_HIT_RESULT_CONTINUE_OR_NONE) {
      action = "intersection_no_hit";
    } else {
      const unsigned metadata = shader_return_words[2];
      const unsigned hit_kind = metadata & 0xffu;
      const unsigned attribute_word_count = (metadata >> 8) & 0xffu;
      const unsigned attribute_base_word = (metadata >> 16) & 0xffu;
      const unsigned attribute_format = (metadata >> 24) & 0xffu;
      const bool attribute_metadata_valid =
          (attribute_word_count == 0 && attribute_base_word == 0 &&
           attribute_format == 0) ||
          (attribute_word_count > 0 &&
           attribute_word_count <= RTCORE_HANDOFF_MAX_INLINE_ATTRIBUTE_WORDS &&
           attribute_base_word == RTCORE_HANDOFF_W_INLINE_ATTRIBUTE_BEGIN &&
           attribute_format == 0x02u);
      const float reported_t =
          rtcore_shader_return_word_to_float(shader_return_words[1]);
      float tmin = 0.0f;
      float tmax = 0.0f;
      bool hit_geometry = false;
      Hit_data closest_hit = {};
      mem->read(&(traversal_data->Tmin), sizeof(traversal_data->Tmin),
                &tmin);
      mem->read(&(traversal_data->Tmax), sizeof(traversal_data->Tmax),
                &tmax);
      mem->read(&(traversal_data->hit_geometry),
                sizeof(traversal_data->hit_geometry), &hit_geometry);
      if (hit_geometry) {
        mem->read(&(traversal_data->closest_hit),
                  sizeof(traversal_data->closest_hit), &closest_hit);
      }
      const rtcore::procedural_report_ordering ordering =
          rtcore::classify_procedural_report(
              reported_t, tmin, tmax, hit_geometry,
              closest_hit.world_min_thit);
      if (!attribute_metadata_valid || hit_kind > 0x7fu ||
          ordering == rtcore::RTCORE_PROCEDURAL_REPORT_INVALID) {
        failure = "SHADER_RETURN_INTERSECTION_REPORT_INVALID";
      } else {
        warp_intersection_table *table =
            VulkanRayTracing::intersection_table[thread->get_ctaid().x]
                                                   [thread->get_ctaid().y];
        if (table == NULL ||
            !table->shader_exists(thread->get_tid().x, shader_counter, pI,
                                  thread)) {
          failure = "SHADER_RETURN_INTERSECTION_TABLE_IDENTITY_MISSING";
        } else {
          const int32_t hit_group_index = table->get_hitGroupIndex(
              shader_counter, thread->get_tid().x, pI, thread);
          const uint32_t primitive_index = table->get_primitiveID(
              shader_counter, thread->get_tid().x, pI, thread);
          const uint32_t instance_index = table->get_instanceID(
              shader_counter, thread->get_tid().x, pI, thread);
          const uint32_t instance_id = table->get_instanceIndex(
              shader_counter, thread->get_tid().x, pI, thread);
          const bool already_committed =
              hit_geometry && closest_hit.world_min_thit == reported_t &&
              closest_hit.geometryType == VK_GEOMETRY_TYPE_AABBS_KHR &&
              closest_hit.hit_kind == hit_kind &&
              closest_hit.hitGroupIndex == hit_group_index &&
              closest_hit.geometry_index == boundary_geometry_index &&
              closest_hit.primitive_index == primitive_index &&
              closest_hit.instance_index == instance_index &&
              closest_hit.instance_id == instance_id;
          if (ordering == rtcore::RTCORE_PROCEDURAL_REPORT_KEEP_EXISTING) {
            action = already_committed
                         ? "intersection_reported_already_committed"
                         : "intersection_reported_kept_closer";
          } else {
            hit_geometry = true;
            mem->write(&(traversal_data->hit_geometry),
                       sizeof(traversal_data->hit_geometry), &hit_geometry,
                       thread, pI);
            const VkGeometryTypeKHR geometry_type =
                VK_GEOMETRY_TYPE_AABBS_KHR;
            mem->write(&(traversal_data->closest_hit.geometryType),
                       sizeof(traversal_data->closest_hit.geometryType),
                       &geometry_type, thread, pI);
            mem->write(&(traversal_data->closest_hit.hit_kind),
                       sizeof(traversal_data->closest_hit.hit_kind),
                       &hit_kind, thread, pI);
            mem->write(&(traversal_data->closest_hit.hitGroupIndex),
                       sizeof(traversal_data->closest_hit.hitGroupIndex),
                       &hit_group_index, thread, pI);
            mem->write(&(traversal_data->closest_hit.geometry_index),
                       sizeof(traversal_data->closest_hit.geometry_index),
                       &boundary_geometry_index, thread, pI);
            mem->write(&(traversal_data->closest_hit.world_min_thit),
                       sizeof(traversal_data->closest_hit.world_min_thit),
                       &reported_t, thread, pI);
            mem->write(&(traversal_data->closest_hit.primitive_index),
                       sizeof(traversal_data->closest_hit.primitive_index),
                       &primitive_index, thread, pI);
            mem->write(&(traversal_data->closest_hit.instance_index),
                       sizeof(traversal_data->closest_hit.instance_index),
                       &instance_index, thread, pI);
            mem->write(&(traversal_data->closest_hit.instance_id),
                       sizeof(traversal_data->closest_hit.instance_id),
                       &instance_id, thread, pI);
            action = "intersection_reported_committed";
          }
          v04_commit_current_candidate = true;
          memcpy(&v04_reported_t_fp32, &reported_t,
                 sizeof(v04_reported_t_fp32));
          v04_reported_hit_kind = hit_kind;
          v04_reported_attribute_word_count = attribute_word_count;
          v04_reported_attribute_format = attribute_format;
        }
      }
    }
  } else if (strcmp(failure, "accepted") == 0) {
    failure = "SHADER_RETURN_BOUNDARY_TYPE_INVALID";
  }

  if (failure_reason != NULL) {
    *failure_reason = failure;
  }
  if (strcmp(failure, "accepted") != 0) {
    return false;
  }

  if (v04_return_update != NULL && v04_commit_current_candidate) {
    v04_return_update->action =
        reason == RTCORE_RETURN_FOR_ANY_HIT
            ? rtcore::abi_v04::shadow::kBoundaryReturnCommitAnyHit
            : rtcore::abi_v04::shadow::kBoundaryReturnCommitIntersection;
    v04_return_update->reported_t_fp32 = v04_reported_t_fp32;
    v04_return_update->reported_hit_kind = v04_reported_hit_kind;
    v04_return_update->reported_attribute_word_count =
        v04_reported_attribute_word_count;
    v04_return_update->reported_attribute_format =
        v04_reported_attribute_format;
    if (reason == RTCORE_RETURN_FOR_INTERSECTION &&
        v04_reported_attribute_word_count > 0) {
      const unsigned long long attribute_base =
          handoff_window_base +
          lane_id * RTCORE_HANDOFF_WINDOW_BYTES_PER_LANE +
          RTCORE_HANDOFF_W_INLINE_ATTRIBUTE_BEGIN * sizeof(unsigned);
      mem->read_simulator_backing(
          attribute_base,
          v04_reported_attribute_word_count * sizeof(unsigned),
          v04_return_update->reported_attribute_words.data());
    }
  }
  if (v04_boundary_reason != NULL) {
    *v04_boundary_reason = reason;
  }

  printf("GPGPU-Sim RTCORE_SHADER_RETURN_DECISION_APPLY "
         "owner_hw_sid=%u previous_warp_uid=%u warp_uid=%u warp_id=%u "
         "lane_id=%u handoff_window_base=0x%llx reason=%u hit_result=%u "
         "shader_counter=%d boundary_geometry_index=%u "
         "action=%s handoff_return_consumed=1 functional_state_applied=1 "
         "functional_oracle_replayed=0 apply_cycle=%llu "
         "apply_result=applied\n",
         owner_hw_sid, previous_warp_uid, warp_uid, warp_id, lane_id,
         handoff_window_base, reason, hit_result, shader_counter,
         boundary_geometry_index, action, apply_cycle);
  fflush(stdout);
  return true;
}

enum rtcore_symbolic_resubmit_action {
  RTCORE_SYMBOLIC_RESUBMIT_NOT_APPLICABLE = 0,
  RTCORE_SYMBOLIC_RESUBMIT_PENDING_WHOLE_MASK,
  RTCORE_SYMBOLIC_RESUBMIT_COMMITTED,
  RTCORE_SYMBOLIC_RESUBMIT_REJECTED,
};

static rtcore_symbolic_resubmit_action rtcore_reject_symbolic_resubmit(
    const ptx_instruction *pI, unsigned long long context_ptr,
    unsigned long long handoff_window_base, unsigned lane_slot_index,
    const ptx_thread_info::rtcore_current_warp_metadata &metadata,
    const char *reason) {
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
         "reason=%s, context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_hw_sid=%u, warp_uid=%u, warp_id=%u, "
         "next_active_mask=0x%08x, whole_mask_committed=0, consumed=0\n",
         pI->source_file(), pI->source_line(),
         reason != NULL ? reason : "RESUBMIT_ADMISSION_REJECTED", context_ptr,
         handoff_window_base, lane_slot_index, metadata.owner_hw_sid,
         metadata.warp_uid, metadata.warp_id, metadata.active_mask);
  fflush(stdout);
  return RTCORE_SYMBOLIC_RESUBMIT_REJECTED;
}

static rtcore_symbolic_resubmit_action rtcore_try_commit_symbolic_resubmit(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    unsigned lane_slot_index,
    const ptx_thread_info::rtcore_current_warp_metadata &metadata,
    const rtcore_synthetic_handoff_key &handoff_key,
    const rtcore_symbolic_rt_token_key &token_key) {
  unsigned resident_warp_uid = 0;
  unsigned previous_active_mask = 0;
  unsigned resident_generation = 0;
  unsigned resident_occupancy = 0;
  const bool resident_live = rtcore_query_resident_rt_warp_record(
      metadata.owner_hw_sid, metadata.warp_id, &resident_warp_uid,
      &previous_active_mask, &resident_generation, &resident_occupancy);
  const bool live_slot = rtcore_synthetic_handoff_window_is_live(handoff_key);
  const bool live_token = rtcore_symbolic_rt_token_is_live(token_key);
  const bool same_initial_submit =
      resident_live && resident_warp_uid == metadata.warp_uid &&
      previous_active_mask == metadata.active_mask;

  if (!resident_live) {
    return RTCORE_SYMBOLIC_RESUBMIT_NOT_APPLICABLE;
  }
  if (!live_slot && !live_token && same_initial_submit) {
    return RTCORE_SYMBOLIC_RESUBMIT_NOT_APPLICABLE;
  }
  if (same_initial_submit) {
    return RTCORE_SYMBOLIC_RESUBMIT_NOT_APPLICABLE;
  }
  if (!live_slot && !live_token) {
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        "RESIDENT_CONTEXT_WINDOW_MISMATCH");
  }
  if (live_slot != live_token) {
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        "RESUBMIT_SLOT_TOKEN_LIVENESS_MISMATCH");
  }

  std::map<rtcore_synthetic_handoff_key,
           rtcore_v03_handoff_lane_slot>::const_iterator window =
      g_rtcore_synthetic_handoff_windows.find(handoff_key);
  std::map<rtcore_symbolic_rt_token_key,
           rtcore_symbolic_rt_token_record>::const_iterator token =
      g_rtcore_symbolic_rt_tokens.find(token_key);
  const bool window_matches =
      window != g_rtcore_synthetic_handoff_windows.end() &&
      rtcore_synthetic_owner_tuple_matches(window->second, handoff_key,
                                           context_ptr, pI, thread);
  const bool token_matches =
      token != g_rtcore_symbolic_rt_tokens.end() && token->second.completed &&
      rtcore_symbolic_rt_token_allocator_record_matches(token->second);
  if (!window_matches || !token_matches) {
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        !window_matches ? "RESUBMIT_WINDOW_OWNER_MISMATCH"
                        : "RESUBMIT_TOKEN_STALE_OR_INCOMPLETE");
  }

  const bool v04_native_continuation_lifecycle =
      rtcore_v04_continuation_lifecycle_gate_active();
  const bool v04_functional_only_engine =
      rtcore_v04_functional_only_engine_gate_active();
  const char *validation_failure = "accepted";
  const bool lane_valid =
      v04_native_continuation_lifecycle ||
      (v04_functional_only_engine
           ? rtcore_validate_v04_functional_only_compatibility_resubmit_lane(
                 metadata.owner_hw_sid, metadata.warp_uid, metadata.warp_id,
                 metadata.active_mask, lane_slot_index, thread->get_uid(),
                 context_ptr, handoff_window_base, token->second.token_id,
                 token->second.allocator_generation,
                 window->second.submit_transaction_id, &validation_failure)
           : rtcore_validate_shader_visible_resubmit_lane(
                 metadata.owner_hw_sid, metadata.warp_uid, metadata.warp_id,
                 metadata.active_mask, lane_slot_index, thread->get_uid(),
                 context_ptr, handoff_window_base, token->second.token_id,
                 token->second.allocator_generation,
                 window->second.submit_transaction_id,
                 &validation_failure));
  if (!lane_valid) {
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        validation_failure);
  }

  rtcore_symbolic_resubmit_lane_transaction &transaction =
      g_rtcore_symbolic_resubmit_lane_transactions[metadata.warp_uid];
  if (!transaction.valid) {
    transaction.valid = true;
    transaction.owner_hw_sid = metadata.owner_hw_sid;
    transaction.warp_uid = metadata.warp_uid;
    transaction.warp_id = metadata.warp_id;
    transaction.static_inst_uid = metadata.static_inst_uid;
    transaction.previous_warp_uid = resident_warp_uid;
    transaction.resident_generation = resident_generation;
    transaction.next_active_mask = metadata.active_mask;
    transaction.handoff_window_base = handoff_window_base;
    transaction.resident_occupancy_before = resident_occupancy;
    transaction.token_occupancy_before = rtcore_symbolic_rt_token_count();
    transaction.handoff_slot_occupancy_before =
        rtcore_synthetic_handoff_window_count();
  }
  const bool transaction_metadata_matches =
      transaction.owner_hw_sid == metadata.owner_hw_sid &&
      transaction.warp_uid == metadata.warp_uid &&
      transaction.warp_id == metadata.warp_id &&
      transaction.static_inst_uid == metadata.static_inst_uid &&
      transaction.previous_warp_uid == resident_warp_uid &&
      transaction.resident_generation == resident_generation &&
      transaction.next_active_mask == metadata.active_mask &&
      transaction.handoff_window_base == handoff_window_base;
  if (!transaction_metadata_matches) {
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        "RESUBMIT_LANE_TRANSACTION_METADATA_MISMATCH");
  }

  const unsigned lane_mask = rtcore_lane_thread_mask(lane_slot_index);
  if (transaction.lane_thread[lane_slot_index] != NULL &&
      transaction.lane_thread[lane_slot_index] != thread) {
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        "RESUBMIT_LANE_THREAD_IDENTITY_MISMATCH");
  }
  transaction.lane_thread[lane_slot_index] = thread;
  transaction.seen_lane_mask |= lane_mask;
  transaction.validated_lane_mask |= lane_mask;
  const bool whole_mask_ready =
      (transaction.seen_lane_mask & transaction.next_active_mask) ==
          transaction.next_active_mask &&
      (transaction.validated_lane_mask & transaction.next_active_mask) ==
          transaction.next_active_mask;
  if (!whole_mask_ready) {
    printf("GPGPU-Sim RTCORE_SHADER_VISIBLE_RESUBMIT_LANE_PRECHECK "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
           "previous_active_mask=0x%08x next_active_mask=0x%08x "
           "seen_lane_mask=0x%08x validated_lane_mask=0x%08x "
           "precheck_result=pending_whole_mask\n",
           metadata.owner_hw_sid, metadata.warp_uid, metadata.warp_id,
           lane_slot_index, previous_active_mask, metadata.active_mask,
           transaction.seen_lane_mask, transaction.validated_lane_mask);
    fflush(stdout);
    return RTCORE_SYMBOLIC_RESUBMIT_PENDING_WHOLE_MASK;
  }

  bool shader_return_decisions_applied = true;
  const char *shader_return_apply_failure = "accepted";
  bool terminal_facts_refreshed = true;
  const char *terminal_facts_refresh_failure = "accepted";
  unsigned committed_previous_active_mask = 0;
  unsigned released_lane_mask = 0;
  unsigned reactivated_lane_mask = 0;
  unsigned resident_occupancy_before = 0;
  unsigned resident_occupancy_after = 0;
  const char *commit_failure = "accepted";
  bool committed = false;
  const bool v04_functional_shader_return_authority_enabled =
      rtcore_v04_shadow_gate(
          rtcore_v04_functional_shader_return_authority_gate_name()) ==
      RTCORE_V04_SHADOW_GATE_ENABLED;
  if (v04_functional_only_engine) {
    shader_return_decisions_applied =
        g_rtcore_v04_functional_only_resubmit_stages.find(
            metadata.warp_uid) !=
        g_rtcore_v04_functional_only_resubmit_stages.end();
    if (!shader_return_decisions_applied) {
      shader_return_apply_failure =
          "V04_FUNCTIONAL_ONLY_RESUBMIT_STAGE_MISSING";
    }
  } else if (v04_native_continuation_lifecycle) {
    committed = rtcore_stage_v04_native_continuation_resubmit(
        metadata.owner_hw_sid, metadata.dynamic_warp_id,
        metadata.warp_uid, metadata.warp_id, metadata.static_inst_uid,
        metadata.active_mask,
        transaction.previous_warp_uid, transaction.resident_generation,
        transaction.handoff_window_base, rtcore_v02_lsu_issue_cycle(thread),
        &committed_previous_active_mask, &released_lane_mask,
        &reactivated_lane_mask, &resident_occupancy_before,
        &resident_occupancy_after, &commit_failure);
  } else if (rtcore_shader_return_application_required()) {
    const bool v04_shadow_boundary_return_enabled =
        rtcore_v04_shadow_gate(
            rtcore_v04_shadow_boundary_publication_gate_name()) ==
        RTCORE_V04_SHADOW_GATE_ENABLED;
    const bool v04_shadow_shader_return_consumer_enabled =
        rtcore_v04_shadow_gate(
            rtcore_v04_shadow_shader_return_consumer_gate_name()) ==
        RTCORE_V04_SHADOW_GATE_ENABLED;
    if (v04_functional_shader_return_authority_enabled) {
      committed =
          rtcore_commit_v04_functional_shader_visible_resubmit_admission(
              pI, metadata.owner_hw_sid, metadata.warp_uid,
              metadata.warp_id, metadata.static_inst_uid,
              metadata.active_mask, transaction.previous_warp_uid,
              transaction.resident_generation, previous_active_mask,
              transaction.handoff_window_base, transaction.lane_thread,
              rtcore_v02_lsu_issue_cycle(thread),
              &committed_previous_active_mask, &released_lane_mask,
              &reactivated_lane_mask, &resident_occupancy_before,
              &resident_occupancy_after, &shader_return_apply_failure);
      shader_return_decisions_applied = committed;
    } else {
      for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
        if ((metadata.active_mask & rtcore_lane_thread_mask(lane)) == 0) {
          continue;
        }
        rtcore::abi_v04::shadow::boundary_return_update v04_return_update;
        uint32_t v04_boundary_reason =
            rtcore::abi_v04::kReasonNoneOrInvalid;
        if (transaction.lane_thread[lane] == NULL ||
            !rtcore_apply_shader_visible_resubmit_lane_return(
                pI, transaction.lane_thread[lane], metadata.owner_hw_sid,
                transaction.previous_warp_uid, metadata.warp_uid,
                metadata.warp_id, lane, transaction.handoff_window_base,
                rtcore_v02_lsu_issue_cycle(thread),
                v04_shadow_boundary_return_enabled ? &v04_return_update : NULL,
                v04_shadow_shader_return_consumer_enabled
                    ? &v04_boundary_reason
                    : NULL,
                &shader_return_apply_failure)) {
          shader_return_decisions_applied = false;
          break;
        }
        if (v04_shadow_shader_return_consumer_enabled &&
            !rtcore_observe_v04_shadow_shader_return(
                transaction.lane_thread[lane], lane,
                transaction.handoff_window_base, v04_boundary_reason,
                v04_return_update, rtcore_v02_lsu_issue_cycle(thread),
                &shader_return_apply_failure)) {
          shader_return_decisions_applied = false;
          break;
        }
        if (!rtcore_refresh_shader_visible_resubmit_lane_terminal_facts(
                metadata.owner_hw_sid, transaction.previous_warp_uid,
                metadata.warp_id, previous_active_mask, lane,
                transaction.lane_thread[lane],
                v04_shadow_boundary_return_enabled ? &v04_return_update : NULL,
                rtcore_v02_lsu_issue_cycle(thread),
                &terminal_facts_refresh_failure)) {
          terminal_facts_refreshed = false;
          break;
        }
      }
    }
  } else if (v04_functional_shader_return_authority_enabled) {
    shader_return_apply_failure =
        "V04_FUNCTIONAL_SHADER_RETURN_APPLICATION_REQUIRED";
    shader_return_decisions_applied = false;
  }
  if (!shader_return_decisions_applied || !terminal_facts_refreshed) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_RETURN_DECISION_APPLY_FAULT "
            "owner_hw_sid=%u previous_warp_uid=%u warp_uid=%u warp_id=%u "
            "next_active_mask=0x%08x apply_result=%u refresh_result=%u "
            "fault=%s\n",
            metadata.owner_hw_sid, transaction.previous_warp_uid,
            metadata.warp_uid, metadata.warp_id, metadata.active_mask,
            shader_return_decisions_applied ? 1u : 0u,
            terminal_facts_refreshed ? 1u : 0u,
            !shader_return_decisions_applied
                ? shader_return_apply_failure
                : terminal_facts_refresh_failure);
    fflush(stderr);
    abort();
  }

  if (!committed && !v04_native_continuation_lifecycle) {
    if (v04_functional_only_engine) {
      committed =
          rtcore_commit_v04_functional_only_compatibility_resubmit(
              metadata.owner_hw_sid, metadata.warp_uid,
              metadata.warp_id, metadata.static_inst_uid,
              metadata.active_mask, transaction.previous_warp_uid,
              transaction.resident_generation,
              rtcore_v02_lsu_issue_cycle(thread),
              &committed_previous_active_mask, &released_lane_mask,
              &reactivated_lane_mask, &resident_occupancy_before,
              &resident_occupancy_after, &commit_failure);
    } else {
      committed = rtcore_commit_shader_visible_resubmit_admission(
          metadata.owner_hw_sid, metadata.warp_uid, metadata.warp_id,
          metadata.static_inst_uid, metadata.active_mask,
          transaction.previous_warp_uid, transaction.resident_generation,
          rtcore_v02_lsu_issue_cycle(thread),
          &committed_previous_active_mask, &released_lane_mask,
          &reactivated_lane_mask, &resident_occupancy_before,
          &resident_occupancy_after, &commit_failure);
    }
  }
  if (!committed) {
    if (rtcore_v04_functional_only_engine_gate_active()) {
      rtcore_v04_functional_only_discard_resubmit_stage(
          metadata.warp_uid);
    }
    g_rtcore_symbolic_resubmit_lane_transactions.erase(metadata.warp_uid);
    return rtcore_reject_symbolic_resubmit(
        pI, context_ptr, handoff_window_base, lane_slot_index, metadata,
        commit_failure);
  }

  bool adapter_completion_rebound = true;
  if (rtcore_v04_functional_only_engine_gate_active()) {
    const bool functional_stage_committed =
        rtcore_v04_functional_only_commit_resubmit_stage(
            metadata.owner_hw_sid, metadata.warp_uid,
            metadata.warp_id, metadata.static_inst_uid,
            metadata.active_mask, transaction.previous_warp_uid);
    adapter_completion_rebound =
        functional_stage_committed &&
        rtcore_v04_functional_only_publish_resubmit(
            pI, metadata, transaction.lane_thread);
  } else {
    for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
      if ((metadata.active_mask & rtcore_lane_thread_mask(lane)) == 0) {
        continue;
      }
      adapter_completion_rebound =
          rtcore_publish_adapter_completion(
              metadata.warp_uid, metadata.warp_id,
              metadata.owner_hw_sid, metadata.active_mask,
              metadata.static_inst_uid, lane, 0, 0) &&
          adapter_completion_rebound;
    }
  }
  if (!adapter_completion_rebound) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_RESUBMIT_ADAPTER_REBIND_INVARIANT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x\n",
            metadata.owner_hw_sid, metadata.warp_uid, metadata.warp_id,
            metadata.active_mask);
    fflush(stderr);
    abort();
  }

  const size_t token_occupancy_after = rtcore_symbolic_rt_token_count();
  const size_t handoff_slot_occupancy_after =
      rtcore_synthetic_handoff_window_count();
  const bool resource_occupancy_stable =
      resident_occupancy_before == transaction.resident_occupancy_before &&
      resident_occupancy_after == transaction.resident_occupancy_before &&
      token_occupancy_after == transaction.token_occupancy_before &&
      handoff_slot_occupancy_after == transaction.handoff_slot_occupancy_before;

  printf("GPGPU-Sim RTCORE_SHADER_VISIBLE_RESUBMIT_ADMISSION "
         "owner_hw_sid=%u previous_warp_uid=%u warp_uid=%u warp_id=%u "
         "handoff_window_base=0x%llx resident_generation=%u "
         "previous_active_mask=0x%08x next_active_mask=0x%08x "
         "released_lane_mask=0x%08x reactivated_lane_mask=0x%08x "
         "resident_record_reused=1 token_reused=1 handoff_slot_reused=1 "
         "resident_occupancy_delta=%d token_occupancy_delta=%lld "
         "handoff_slot_occupancy_delta=%lld functional_oracle_replayed=0 "
         "resource_identity_validated_mask=0x%08x "
         "per_lane_owner_tuple_revalidated=1 service_cycle=%llu "
         "adapter_completion_rebound=%u whole_mask_committed=1 "
         "admission_result=%s\n",
         metadata.owner_hw_sid, transaction.previous_warp_uid,
         metadata.warp_uid, metadata.warp_id,
         transaction.handoff_window_base,
         transaction.resident_generation,
         committed_previous_active_mask, metadata.active_mask,
         released_lane_mask, reactivated_lane_mask,
         static_cast<int>(resident_occupancy_after) -
             static_cast<int>(transaction.resident_occupancy_before),
         static_cast<long long>(token_occupancy_after) -
             static_cast<long long>(transaction.token_occupancy_before),
         static_cast<long long>(handoff_slot_occupancy_after) -
             static_cast<long long>(transaction.handoff_slot_occupancy_before),
         transaction.validated_lane_mask,
         rtcore_v02_lsu_issue_cycle(thread),
         adapter_completion_rebound ? 1u : 0u,
         resource_occupancy_stable ? "accepted"
                                   : "RESOURCE_OCCUPANCY_CHANGED");
  fflush(stdout);
  g_rtcore_symbolic_resubmit_lane_transactions.erase(metadata.warp_uid);
  if (!resource_occupancy_stable) {
    abort();
  }
  return RTCORE_SYMBOLIC_RESUBMIT_COMMITTED;
}

void rtcore_publish_synthetic_handoff_window(
    const ptx_instruction *pI, const rtcore_synthetic_handoff_key &key,
    const rtcore_v03_handoff_lane_slot &slot, ptx_thread_info *thread) {
  assert(thread != NULL);
  const dim3 owner_tid = thread->get_tid();
  const dim3 owner_ctaid = thread->get_ctaid();
  const unsigned launch_x = owner_tid.x + owner_ctaid.x * 32;
  const unsigned launch_y = owner_ctaid.y;
  const unsigned launch_width =
      thread->get_kernel().vulkan_metadata.launch_width;
  const unsigned long long pixel_index =
      launch_x + static_cast<unsigned long long>(launch_y) * launch_width;
  const bool inserted =
      g_rtcore_synthetic_handoff_windows.insert(std::make_pair(key, slot))
          .second;
  if (!inserted) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=LIVE_SLOT_OVERWRITE_AT_PUBLISH, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u\n",
           pI->source_file(), pI->source_line(), slot.context_ptr,
           key.handoff_window_base, key.lane_slot_index);
    fflush(stdout);
  }
  assert(inserted);
  rtcore_commit_synthetic_window_generation(key,
                                             slot.submit_transaction_id);
  const unsigned lane_slot_byte_offset =
      rtcore_handoff_lane_slot_byte_offset(key.lane_slot_index);
  const unsigned long long lane_slot_base =
      rtcore_handoff_lane_slot_base(key.handoff_window_base,
                                    key.lane_slot_index);
  const bool v04_live_publication_enabled =
      rtcore_v04_shadow_gate(
          rtcore_v04_live_handoff_publication_gate_name()) ==
      RTCORE_V04_SHADOW_GATE_ENABLED;
  if (!v04_live_publication_enabled) {
    thread->get_global_memory()->write_simulator_backing(
        lane_slot_base, sizeof(slot.words), slot.words);
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT handoff-window-published (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, lane_slot_byte_offset=%u, "
         "lane_slot_base=0x%llx, launch=(%u,%u), pixel_index=%llu, "
         "owner_hw_tid=%u, owner_hw_wid=%u, "
         "owner_hw_sid=%u, thread_mask=0x%08x, "
         "submit_transaction_id=%u, handoff_profile=v03_compressed_sync, "
         "backing_byte_write=%u, compatibility_map_only=%u, "
         "ray_flags=0x%08x, selector={w1=0x%08x,w2=0x%08x,w3=0x%08x,"
         "w4=0x%08x}, candidate_metadata={w9=0x%08x,w10=0x%08x,"
         "w11=0x%08x,w12=0x%08x}\n",
         pI->source_file(), pI->source_line(), slot.context_ptr,
         key.handoff_window_base, key.lane_slot_index, lane_slot_byte_offset,
         lane_slot_base, launch_x, launch_y, pixel_index,
         slot.owner_hw_tid, slot.owner_hw_wid,
         slot.owner_hw_sid, slot.thread_mask, slot.submit_transaction_id,
         v04_live_publication_enabled ? 0u : 1u,
         v04_live_publication_enabled ? 1u : 0u,
         slot.words[RTCORE_HANDOFF_W_RAY_FLAGS], slot.words[1],
         slot.words[2], slot.words[3], slot.words[4], slot.words[9],
         slot.words[10], slot.words[11], slot.words[12]);
  fflush(stdout);
  VulkanRayTracing::publishLegacyDistanceProducerEvidenceForTransaction(
      thread, slot.context_ptr, key.lane_slot_index,
      slot.submit_transaction_id);
}

bool rtcore_synthetic_lane_binding_matches(
    const ptx_instruction *pI, const rtcore_synthetic_handoff_key &key,
    const rtcore_v03_handoff_lane_slot &slot,
    unsigned long long context_ptr) {
  const bool context_matches = slot.context_ptr == context_ptr;
  const bool window_base_matches =
      slot.handoff_window_base == key.handoff_window_base;
  const bool lane_slot_matches =
      slot.lane_slot_index == key.lane_slot_index;
  const bool lane_slot_base_matches =
      slot.lane_slot_base == rtcore_handoff_lane_slot_base(
                                   key.handoff_window_base,
                                   key.lane_slot_index);
  const unsigned lane_thread_mask =
      rtcore_lane_thread_mask(key.lane_slot_index);
  const bool active_lane = (slot.thread_mask & lane_thread_mask) != 0;
  const bool accepted =
      context_matches && window_base_matches && lane_slot_matches &&
      lane_slot_base_matches && active_lane;

  printf("GPGPU-Sim PTX: RT_SUBMIT result-lane-binding (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, lane_slot_base=0x%llx, "
         "context_match=%u, window_base_match=%u, lane_slot_match=%u, "
         "lane_slot_base_match=%u, active_lane=%u, "
         "accepted=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         key.handoff_window_base, key.lane_slot_index,
         rtcore_handoff_lane_slot_base(key.handoff_window_base,
                                       key.lane_slot_index),
         context_matches ? 1 : 0,
         window_base_matches ? 1 : 0, lane_slot_matches ? 1 : 0,
         lane_slot_base_matches ? 1 : 0, active_lane ? 1 : 0,
         accepted ? 1 : 0);
  fflush(stdout);

  return accepted;
}

const rtcore_v03_handoff_lane_slot *rtcore_acquire_synthetic_handoff_window(
    const std::map<rtcore_synthetic_handoff_key, rtcore_v03_handoff_lane_slot>
        &windows,
    const rtcore_synthetic_handoff_key &key) {
  std::map<rtcore_synthetic_handoff_key,
           rtcore_v03_handoff_lane_slot>::const_iterator window =
      windows.find(key);
  if (window == windows.end()) {
    return NULL;
  }
  return &window->second;
}

bool rtcore_release_synthetic_handoff_window(
    const rtcore_synthetic_handoff_key &key) {
  return g_rtcore_synthetic_handoff_windows.erase(key) == 1;
}

size_t rtcore_synthetic_handoff_window_count() {
  return g_rtcore_synthetic_handoff_windows.size();
}

void rtcore_rollback_symbolic_submit_after_token_acquire(
    const ptx_instruction *pI,
    const rtcore_symbolic_rt_token_key &token_key,
    const rtcore_symbolic_rt_token_reservation_key &reservation_key,
    const rtcore_synthetic_handoff_key &handoff_key) {
  const bool released_token =
      rtcore_release_symbolic_rt_token(token_key);
  const bool cancelled_reservation =
      rtcore_cancel_symbolic_rt_token_reservation(reservation_key);

  printf("GPGPU-Sim PTX: RT_SUBMIT rollback-cleanup (%s:%u), "
         "reason=FAIL_AFTER_TOKEN_ACQUIRE, context_ptr=0x%llx, "
         "handoff_window_base=0x%llx, lane_slot_index=%u, "
         "owner_hw_tid=%u, owner_hw_wid=%u, owner_hw_sid=%u, "
         "warp_uid=%u, static_inst_uid=%u, released_token=%u, "
         "cancelled_reservation=%u, remaining_windows=%zu, "
         "remaining_tokens=%zu, remaining_reservations=%zu, "
         "remaining_allocator_live=%zu\n",
         pI->source_file(), pI->source_line(), token_key.context_ptr,
         handoff_key.handoff_window_base, handoff_key.lane_slot_index,
         token_key.owner_hw_tid, token_key.owner_hw_wid,
         token_key.owner_hw_sid, reservation_key.warp_uid,
         reservation_key.static_inst_uid, released_token ? 1 : 0,
         cancelled_reservation ? 1 : 0,
         rtcore_synthetic_handoff_window_count(),
         rtcore_symbolic_rt_token_count(),
         rtcore_symbolic_rt_token_reservation_count(),
         rtcore_symbolic_rt_token_allocator_live_count());
  fflush(stdout);

  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
         "reason=FAIL_AFTER_TOKEN_ACQUIRE, context_ptr=0x%llx, "
         "handoff_window_base=0x%llx, lane_slot_index=%u, consumed=0\n",
         pI->source_file(), pI->source_line(), token_key.context_ptr,
         handoff_key.handoff_window_base, handoff_key.lane_slot_index);
  fflush(stdout);
}

void rtcore_rollback_symbolic_submit_after_handoff_publish(
    const ptx_instruction *pI,
    const rtcore_symbolic_rt_token_key &token_key,
    const rtcore_symbolic_rt_token_reservation_key &reservation_key,
    const rtcore_synthetic_handoff_key &handoff_key) {
  const bool released_window =
      rtcore_release_synthetic_handoff_window(handoff_key);
  const bool released_token =
      rtcore_release_symbolic_rt_token(token_key);
  const bool cancelled_reservation =
      rtcore_cancel_symbolic_rt_token_reservation(reservation_key);

  printf("GPGPU-Sim PTX: RT_SUBMIT rollback-cleanup (%s:%u), "
         "reason=FAIL_AFTER_HANDOFF_PUBLISH, context_ptr=0x%llx, "
         "handoff_window_base=0x%llx, lane_slot_index=%u, "
         "owner_hw_tid=%u, owner_hw_wid=%u, owner_hw_sid=%u, "
         "warp_uid=%u, static_inst_uid=%u, released_window=%u, "
         "released_token=%u, cancelled_reservation=%u, "
         "remaining_windows=%zu, remaining_tokens=%zu, "
         "remaining_reservations=%zu, remaining_allocator_live=%zu\n",
         pI->source_file(), pI->source_line(), token_key.context_ptr,
         handoff_key.handoff_window_base, handoff_key.lane_slot_index,
         token_key.owner_hw_tid, token_key.owner_hw_wid,
         token_key.owner_hw_sid, reservation_key.warp_uid,
         reservation_key.static_inst_uid, released_window ? 1 : 0,
         released_token ? 1 : 0, cancelled_reservation ? 1 : 0,
         rtcore_synthetic_handoff_window_count(),
         rtcore_symbolic_rt_token_count(),
         rtcore_symbolic_rt_token_reservation_count(),
         rtcore_symbolic_rt_token_allocator_live_count());
  fflush(stdout);

  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
         "reason=FAIL_AFTER_HANDOFF_PUBLISH, context_ptr=0x%llx, "
         "handoff_window_base=0x%llx, lane_slot_index=%u, consumed=0\n",
         pI->source_file(), pI->source_line(), token_key.context_ptr,
         handoff_key.handoff_window_base, handoff_key.lane_slot_index);
  fflush(stdout);
}

