bool rtcore_v03_return_reason_is_valid(unsigned reason) {
  switch (reason) {
    case RTCORE_RETURN_FOR_MISS:
    case RTCORE_RETURN_FOR_CLOSEST_HIT:
    case RTCORE_RETURN_FOR_ANY_HIT:
    case RTCORE_RETURN_FOR_INTERSECTION:
    case RTCORE_RETURN_FOR_TRACE_DONE:
    case RTCORE_RETURN_FOR_MEMORY_FAULT:
    case RTCORE_RETURN_FOR_UNSUPPORTED:
      return true;
    default:
      return false;
  }
}

unsigned rtcore_compact_result(unsigned reason) {
  return RTCORE_COMPLETION_VALID | (reason & 0xff);
}

unsigned rtcore_apply_test_compact_result_corruption(
    const ptx_instruction *pI, unsigned result_word) {
  const char *mode = getenv("VULKAN_SIM_RTCORE_TEST_V_RESULT_CORRUPTION");
  if (mode == NULL || *mode == '\0' || strcmp(mode, "0") == 0) {
    return result_word;
  }

  unsigned corrupted = result_word;
  if (strcmp(mode, "reserved") == 0) {
    corrupted |= 1u << 8;
  } else if (strcmp(mode, "invalid") == 0) {
    corrupted &= ~RTCORE_COMPLETION_VALID;
  } else if (strcmp(mode, "unknown_reason") == 0) {
    corrupted = (corrupted & ~0xffu) | 0x80u;
  } else {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=INVALID_V_RESULT_CORRUPTION_MODE, mode=%s\n",
           pI->source_file(), pI->source_line(), mode);
    fflush(stdout);
    inst_not_implemented(pI);
    return result_word;
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT v-result-corruption (%s:%u), "
         "v_result_profile=v03_compact, mode=%s, before=0x%08x, "
         "after=0x%08x\n",
         pI->source_file(), pI->source_line(), mode, result_word, corrupted);
  fflush(stdout);
  return corrupted;
}

void rtcore_log_v02_lsu_retire_side_observation(
    const ptx_instruction *pI, unsigned long long context_ptr,
    unsigned long long handoff_window_base, unsigned lane_slot_index,
    const rtcore_v03_handoff_lane_slot *window, bool tracked_window,
    bool matching_context, bool owner_tuple_matches,
    const rtcore_symbolic_rt_token_key &token_key, bool token_can_retire) {
  if (!rtcore_v02_lsu_retire_side_observation_enabled()) {
    return;
  }

  std::map<rtcore_symbolic_rt_token_key,
           rtcore_symbolic_rt_token_record>::const_iterator token =
      g_rtcore_symbolic_rt_tokens.find(token_key);
  const bool token_live = token != g_rtcore_symbolic_rt_tokens.end();
  const bool token_completed = token_live && token->second.completed;
  const bool lane_slot_profile_present =
      tracked_window && window != NULL &&
      window->submit_transaction_id != 0;
  const bool result_store_sideband_enabled =
      rtcore_v02_lsu_handoff_window_sideband_enabled();
  const bool accepted =
      tracked_window && matching_context && owner_tuple_matches &&
      token_can_retire && token_live && token_completed &&
      lane_slot_profile_present && result_store_sideband_enabled;

  printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT "
         "v02-lsu-retire-side-observation (%s:%u), "
         "observation_enabled=1, observation_path=retire_owned_read, "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, tracked_window=%u, matching_context=%u, "
         "owner_tuple_match=%u, token_live=%u, token_completed=%u, "
         "handoff_profile=v03_compressed_sync, "
         "lane_slot_profile_present=%u, result_store_sideband_enabled=%u, "
         "observation_before_release=1, accepted=%u\n",
         pI->source_file(), pI->source_line(), context_ptr,
         handoff_window_base, lane_slot_index, tracked_window ? 1 : 0,
         matching_context ? 1 : 0, owner_tuple_matches ? 1 : 0,
         token_live ? 1 : 0, token_completed ? 1 : 0,
         lane_slot_profile_present ? 1 : 0,
         result_store_sideband_enabled ? 1 : 0, accepted ? 1 : 0);
  fflush(stdout);
}

unsigned rtcore_float_to_u32(float value) {
  unsigned word = 0;
  memcpy(&word, &value, sizeof(word));
  return word;
}

const char *rtcore_return_reason_name(unsigned reason);

enum rtcore_test_handoff_boundary_mode {
  RTCORE_TEST_HANDOFF_BOUNDARY_NONE,
  RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_ACCEPT,
  RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_IGNORE,
  RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_REPORTED,
  RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_NO_HIT,
  RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INLINE_OVERFLOW,
  RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INVALID_HIT_KIND
};

rtcore_test_handoff_boundary_mode rtcore_test_handoff_boundary_mode_config(
    const ptx_instruction *pI) {
  const char *mode = getenv("VULKAN_SIM_RTCORE_TEST_HANDOFF_BOUNDARY");
  if (mode == NULL || *mode == '\0' || strcmp(mode, "0") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_NONE;
  }
  if (strcmp(mode, "any_hit_accept") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_ACCEPT;
  }
  if (strcmp(mode, "any_hit_ignore") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_IGNORE;
  }
  if (strcmp(mode, "intersection_reported") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_REPORTED;
  }
  if (strcmp(mode, "intersection_no_hit") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_NO_HIT;
  }
  if (strcmp(mode, "intersection_inline_overflow") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INLINE_OVERFLOW;
  }
  if (strcmp(mode, "intersection_invalid_hit_kind") == 0) {
    return RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INVALID_HIT_KIND;
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
         "reason=INVALID_HANDOFF_BOUNDARY_TEST_MODE, mode=%s\n",
         pI->source_file(), pI->source_line(), mode);
  fflush(stdout);
  inst_not_implemented(pI);
  return RTCORE_TEST_HANDOFF_BOUNDARY_NONE;
}

unsigned rtcore_test_handoff_boundary_reason(
    rtcore_test_handoff_boundary_mode mode, unsigned default_reason) {
  if (mode == RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_ACCEPT ||
      mode == RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_IGNORE) {
    return RTCORE_RETURN_FOR_ANY_HIT;
  }
  if (mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_REPORTED ||
      mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_NO_HIT ||
      mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INLINE_OVERFLOW ||
      mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INVALID_HIT_KIND) {
    return RTCORE_RETURN_FOR_INTERSECTION;
  }
  return default_reason;
}

unsigned rtcore_v03_handoff_geometry_type(VkGeometryTypeKHR geometry_type) {
  if (geometry_type == VK_GEOMETRY_TYPE_TRIANGLES_KHR) {
    return 0x01;
  }
  if (geometry_type == VK_GEOMETRY_TYPE_AABBS_KHR) {
    return 0x02;
  }
  return 0;
}

bool rtcore_publish_v03_handoff_lane_slot(
    const ptx_instruction *pI, const Traversal_data &traversal_data,
    unsigned reason, rtcore_v03_handoff_lane_slot *slot) {
  memset(slot->words, 0, sizeof(slot->words));
  slot->words[RTCORE_HANDOFF_W_RAY_FLAGS] = traversal_data.rayFlags;

  const bool selector_required =
      reason == RTCORE_RETURN_FOR_MISS ||
      reason == RTCORE_RETURN_FOR_CLOSEST_HIT ||
      reason == RTCORE_RETURN_FOR_ANY_HIT ||
      reason == RTCORE_RETURN_FOR_INTERSECTION;
  const bool candidate_required =
      reason == RTCORE_RETURN_FOR_CLOSEST_HIT ||
      reason == RTCORE_RETURN_FOR_ANY_HIT ||
      reason == RTCORE_RETURN_FOR_INTERSECTION;

  if (reason == RTCORE_RETURN_FOR_MISS) {
    slot->words[1] = traversal_data.missIndex;
  } else if (candidate_required) {
    if (!traversal_data.hit_geometry) {
      printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
             "reason=V03_HANDOFF_CANDIDATE_MISSING, return_reason=%s\n",
             pI->source_file(), pI->source_line(),
             rtcore_return_reason_name(reason));
      fflush(stdout);
      return false;
    }

    const Hit_data &hit = traversal_data.closest_hit;
    const unsigned geometry_type =
        rtcore_v03_handoff_geometry_type(hit.geometryType);
    if (geometry_type == 0 || hit.primitive_index > 0x00ffffffu) {
      printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
             "reason=V03_HANDOFF_CANDIDATE_UNREPRESENTABLE, "
             "geometry_type=%u, primitive_index=%u\n",
             pI->source_file(), pI->source_line(), geometry_type,
             hit.primitive_index);
      fflush(stdout);
      return false;
    }

    slot->words[1] = traversal_data.sbtRecordOffset;
    slot->words[2] = traversal_data.sbtRecordStride;
    slot->words[3] = hit.hitGroupIndex >= 0
                         ? (unsigned)hit.hitGroupIndex
                         : 0;
    slot->words[4] = hit.geometry_index;
    slot->words[5] = rtcore_float_to_u32(hit.world_min_thit);
    slot->words[6] = hit.primitive_index;
    slot->words[7] = hit.instance_index;
    slot->words[8] = 0;

    const unsigned hit_kind = hit.hit_kind;
    slot->words[9] = hit_kind | (geometry_type << 8);
    slot->words[10] = 0;
    const unsigned candidate_ref_kind =
        reason == RTCORE_RETURN_FOR_CLOSEST_HIT
            ? 0x03u
            : (geometry_type == 0x01 ? 0x01u : 0x02u);
    slot->words[11] = (hit.primitive_index & 0x00ffffffu) |
                      (candidate_ref_kind << 24) | (0x02u << 28);

    if (geometry_type == 0x01) {
      slot->words[12] = 2u | (0x01u << 8) | (0x01u << 16);
      slot->words[16] =
          rtcore_float_to_u32(hit.barycentric_coordinates.x);
      slot->words[17] =
          rtcore_float_to_u32(hit.barycentric_coordinates.y);
    }
  }

  const char *corruption =
      getenv("VULKAN_SIM_RTCORE_TEST_HANDOFF_CORRUPTION");
  if (corruption != NULL && *corruption != '\0' &&
      strcmp(corruption, "0") != 0) {
    if (strcmp(corruption, "candidate_reserved") == 0) {
      if (candidate_required) {
        slot->words[9] |= 1u << 16;
      }
    } else if (strcmp(corruption, "attribute_spill") == 0) {
      if (candidate_required) {
        slot->words[12] = 1u | (0x03u << 8) | (0x01u << 16);
      }
    } else if (strcmp(corruption, "shader_return_dirty") == 0) {
      slot->words[13] = 1;
    } else {
      printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
             "reason=INVALID_HANDOFF_CORRUPTION_MODE, mode=%s\n",
             pI->source_file(), pI->source_line(), corruption);
      fflush(stdout);
      return false;
    }
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT handoff-lane-slot-publication (%s:%u), "
         "handoff_profile=v03_compressed_sync, reason=%s, "
         "reason_directed_read_set=1, selector_required=%u, "
         "candidate_required=%u, ray_flags=0x%08x, "
         "selector={w1=0x%08x,w2=0x%08x,w3=0x%08x,w4=0x%08x}, "
         "candidate={w5=0x%08x,w6=0x%08x,w7=0x%08x,w8=0x%08x,"
         "w9=0x%08x,w10=0x%08x,w11=0x%08x,w12=0x%08x}, "
         "shader_return={w13=0x%08x,w14=0x%08x,w15=0x%08x}, "
         "inline_attribute={w16=0x%08x,w17=0x%08x}\n",
         pI->source_file(), pI->source_line(),
         rtcore_return_reason_name(reason), selector_required ? 1 : 0,
         candidate_required ? 1 : 0, slot->words[0], slot->words[1],
         slot->words[2], slot->words[3], slot->words[4], slot->words[5],
         slot->words[6], slot->words[7], slot->words[8], slot->words[9],
         slot->words[10], slot->words[11], slot->words[12], slot->words[13],
         slot->words[14], slot->words[15], slot->words[16], slot->words[17]);
  fflush(stdout);

  return true;
}

bool rtcore_submit_operands_are_valid(unsigned long long context_ptr,
                                      unsigned long long handoff_window_base) {
  return context_ptr != 0 && handoff_window_base != 0 &&
         (context_ptr % RTCORE_CONTEXT_ALIGNMENT) == 0 &&
         (handoff_window_base % RTCORE_HANDOFF_WINDOW_ALIGNMENT) == 0;
}

const char *rtcore_return_reason_name(unsigned reason) {
  switch (reason) {
    case RTCORE_RETURN_FOR_MISS:
      return "miss";
    case RTCORE_RETURN_FOR_CLOSEST_HIT:
      return "closest_hit";
    case RTCORE_RETURN_FOR_ANY_HIT:
      return "any_hit_required";
    case RTCORE_RETURN_FOR_INTERSECTION:
      return "intersection_required";
    case RTCORE_RETURN_FOR_TRACE_DONE:
      return "trace_done_no_shader";
    case RTCORE_RETURN_FOR_MEMORY_FAULT:
      return "fault";
    case RTCORE_RETURN_FOR_UNSUPPORTED:
      return "unsupported";
    default:
      return "unknown";
  }
}

bool rtcore_software_lazy_load_v03_handoff_words(
    const ptx_instruction *pI, const rtcore_v03_handoff_lane_slot &window,
    unsigned reason, unsigned lane_slot_index) {
  const bool known_reason = rtcore_v03_return_reason_is_valid(reason);
  const bool selector_required =
      reason == RTCORE_RETURN_FOR_MISS ||
      reason == RTCORE_RETURN_FOR_CLOSEST_HIT ||
      reason == RTCORE_RETURN_FOR_ANY_HIT ||
      reason == RTCORE_RETURN_FOR_INTERSECTION;
  const bool candidate_required =
      reason == RTCORE_RETURN_FOR_CLOSEST_HIT ||
      reason == RTCORE_RETURN_FOR_ANY_HIT ||
      reason == RTCORE_RETURN_FOR_INTERSECTION;

  bool candidate_type_reserved_zero = true;
  bool hit_kind_geometry_consistent = true;
  bool geometry_type_valid = true;
  bool intersection_geometry_valid = true;
  bool candidate_policy_reserved_zero = true;
  bool candidate_reference_valid = true;
  bool attribute_metadata_valid = true;
  if (candidate_required) {
    const unsigned hit_kind = window.words[9] & 0xffu;
    const unsigned geometry_type = (window.words[9] >> 8) & 0xffu;
    candidate_type_reserved_zero =
        (window.words[9] & 0xffff0000u) == 0;
    geometry_type_valid = geometry_type == 0x01u || geometry_type == 0x02u;
    intersection_geometry_valid =
        reason != RTCORE_RETURN_FOR_INTERSECTION || geometry_type == 0x02u;
    hit_kind_geometry_consistent =
        (geometry_type == 0x01u &&
         (hit_kind == 0xfeu || hit_kind == 0xffu)) ||
        (geometry_type == 0x02u && hit_kind <= 0x7fu);
    candidate_policy_reserved_zero =
        (window.words[10] & 0xffe0f0fcu) == 0;

    const unsigned candidate_ref_kind =
        (window.words[11] >> 24) & 0x0fu;
    const unsigned candidate_ref_format =
        (window.words[11] >> 28) & 0x0fu;
    const bool candidate_ref_kind_valid =
        (candidate_ref_kind >= 0x01u && candidate_ref_kind <= 0x06u) ||
        candidate_ref_kind == 0x0fu;
    const bool candidate_ref_format_valid =
        (candidate_ref_format >= 0x01u && candidate_ref_format <= 0x05u) ||
        candidate_ref_format == 0x0fu;
    candidate_reference_valid =
        candidate_ref_kind_valid && candidate_ref_format_valid;

    const unsigned attribute_word_count = window.words[12] & 0xffu;
    const unsigned attribute_location = (window.words[12] >> 8) & 0xffu;
    const unsigned attribute_format = (window.words[12] >> 16) & 0xffu;
    const unsigned attribute_flags = (window.words[12] >> 24) & 0xffu;
    const bool attribute_flags_valid =
        (attribute_flags & 0xfeu) == 0;
    const bool no_attribute_metadata_valid =
        attribute_word_count != 0 ||
        (attribute_location == 0 && attribute_format == 0 &&
         attribute_flags == 0);
    const bool inline_attribute_metadata_valid =
        attribute_word_count == 0 ||
        (attribute_location == 0x01u &&
         attribute_word_count <= RTCORE_HANDOFF_MAX_INLINE_ATTRIBUTE_WORDS &&
         attribute_format >= 0x01u && attribute_format <= 0x7fu &&
         attribute_flags == 0);
    // R0c adds context hit_state_region authority. Until then, fallback
    // metadata cannot be authenticated and is rejected rather than inferred.
    const bool no_unresolved_fallback = attribute_location != 0x02u;
    attribute_metadata_valid =
        attribute_flags_valid && no_attribute_metadata_valid &&
        inline_attribute_metadata_valid && no_unresolved_fallback;
  }
  const bool reason_directed_read_set =
      known_reason && candidate_type_reserved_zero &&
      hit_kind_geometry_consistent && geometry_type_valid &&
      intersection_geometry_valid && candidate_policy_reserved_zero &&
      candidate_reference_valid && attribute_metadata_valid;
  const bool accepted = reason_directed_read_set;

  printf("GPGPU-Sim PTX: RT_SUBMIT software-lazy-load (%s:%u), "
         "handoff_profile=v03_compressed_sync, lane_slot_index=%u, "
         "reason=%s, reason_directed_read_set=%u, selector_required=%u, "
         "candidate_required=%u, candidate_type_reserved_zero=%u, "
         "hit_kind_geometry_consistent=%u, geometry_type_valid=%u, "
         "intersection_geometry_valid=%u, "
         "candidate_policy_reserved_zero=%u, "
         "candidate_reference_valid=%u, attribute_metadata_valid=%u, "
         "accepted=%u\n",
         pI->source_file(), pI->source_line(), lane_slot_index,
         rtcore_return_reason_name(reason),
         reason_directed_read_set ? 1 : 0, selector_required ? 1 : 0,
         candidate_required ? 1 : 0,
         candidate_type_reserved_zero ? 1 : 0,
         hit_kind_geometry_consistent ? 1 : 0,
         geometry_type_valid ? 1 : 0,
         intersection_geometry_valid ? 1 : 0,
         candidate_policy_reserved_zero ? 1 : 0,
         candidate_reference_valid ? 1 : 0,
         attribute_metadata_valid ? 1 : 0, accepted ? 1 : 0);
  fflush(stdout);
  return accepted;
}

bool rtcore_v03_compact_result_is_valid(
    const ptx_instruction *pI, unsigned result_word) {
  const bool completion_valid =
      (result_word & RTCORE_COMPLETION_VALID) != 0;
  const bool reserved_zero = (result_word & 0x7fffff00u) == 0;
  const unsigned reason = result_word & 0xffu;
  const bool reason_valid = rtcore_v03_return_reason_is_valid(reason);
  const bool accepted = completion_valid && reserved_zero && reason_valid;

  printf("GPGPU-Sim PTX: RT_SUBMIT v-result-validation (%s:%u), "
         "v_result_profile=v03_compact, result=0x%08x, "
         "completion_valid=%u, reserved_zero=%u, reason_valid=%u, "
         "reason=%s, accepted=%u\n",
         pI->source_file(), pI->source_line(), result_word,
         completion_valid ? 1 : 0, reserved_zero ? 1 : 0,
         reason_valid ? 1 : 0, rtcore_return_reason_name(reason),
         accepted ? 1 : 0);
  fflush(stdout);
  return accepted;
}

bool rtcore_validate_v03_software_return_channel(
    const ptx_instruction *pI, const rtcore_v03_handoff_lane_slot &slot,
    unsigned reason) {
  const unsigned hit_result = slot.words[13] & 0xffu;
  const bool hit_result_reserved_zero = (slot.words[13] & 0xffffff00u) == 0;
  const bool any_hit_result_valid =
      reason != RTCORE_RETURN_FOR_ANY_HIT ||
      hit_result == RTCORE_HIT_RESULT_ACCEPT_HIT ||
      hit_result == RTCORE_HIT_RESULT_IGNORE_HIT;
  const bool intersection_result_valid =
      reason != RTCORE_RETURN_FOR_INTERSECTION ||
      hit_result == RTCORE_HIT_RESULT_CONTINUE_OR_NONE ||
      hit_result == RTCORE_HIT_RESULT_REPORTED_INTERSECTION;
  const bool boundary_reason =
      reason == RTCORE_RETURN_FOR_ANY_HIT ||
      reason == RTCORE_RETURN_FOR_INTERSECTION;

  const unsigned reported_attribute_word_count =
      (slot.words[15] >> 8) & 0xffu;
  const unsigned reported_hit_kind = slot.words[15] & 0xffu;
  const unsigned reported_attribute_base_word =
      (slot.words[15] >> 16) & 0xffu;
  const unsigned reported_attribute_format =
      (slot.words[15] >> 24) & 0xffu;
  const bool reported_intersection =
      hit_result == RTCORE_HIT_RESULT_REPORTED_INTERSECTION;
  const bool reported_hit_kind_valid =
      !reported_intersection || reported_hit_kind <= 0x7fu;
  const bool reported_no_attribute_metadata =
      reported_attribute_word_count != 0 ||
      (reported_attribute_base_word == 0 &&
       reported_attribute_format == 0);
  const bool reported_inline_attribute_metadata =
      reported_attribute_word_count == 0 ||
      (reported_attribute_word_count <=
           RTCORE_HANDOFF_MAX_INLINE_ATTRIBUTE_WORDS &&
       reported_attribute_base_word ==
           RTCORE_HANDOFF_W_INLINE_ATTRIBUTE_BEGIN &&
       reported_attribute_format == 0x02u);
  const bool reported_metadata_valid =
      !reported_intersection ||
      (reported_no_attribute_metadata && reported_inline_attribute_metadata);
  const bool nonreported_payload_clear =
      reported_intersection || (slot.words[14] == 0 && slot.words[15] == 0);
  const bool accepted =
      boundary_reason && hit_result_reserved_zero &&
      any_hit_result_valid && intersection_result_valid &&
      reported_hit_kind_valid && reported_metadata_valid &&
      nonreported_payload_clear;

  printf("GPGPU-Sim PTX: RT_SUBMIT software-return-channel-validation "
         "(%s:%u), handoff_profile=v03_compressed_sync, reason=%s, "
         "hit_result=%u, hit_result_reserved_zero=%u, "
         "any_hit_result_valid=%u, intersection_result_valid=%u, "
         "reported_intersection=%u, reported_hit_kind=%u, "
         "reported_hit_kind_valid=%u, reported_attribute_word_count=%u, "
         "reported_attribute_base_word=%u, "
         "reported_attribute_format=%u, reported_metadata_valid=%u, "
         "nonreported_payload_clear=%u, accepted=%u\n",
         pI->source_file(), pI->source_line(),
         rtcore_return_reason_name(reason), hit_result,
         hit_result_reserved_zero ? 1 : 0,
         any_hit_result_valid ? 1 : 0,
         intersection_result_valid ? 1 : 0,
         reported_intersection ? 1 : 0,
         reported_hit_kind, reported_hit_kind_valid ? 1 : 0,
         reported_attribute_word_count, reported_attribute_base_word,
         reported_attribute_format, reported_metadata_valid ? 1 : 0,
         nonreported_payload_clear ? 1 : 0, accepted ? 1 : 0);
  fflush(stdout);
  return accepted;
}

static bool rtcore_prepare_v03_software_return_channel_slot(
    const ptx_instruction *pI, unsigned reason,
    rtcore_v03_handoff_lane_slot *slot, bool emit_log) {
  if (slot == NULL) return false;
  const rtcore_test_handoff_boundary_mode mode =
      rtcore_test_handoff_boundary_mode_config(pI);
  if (mode == RTCORE_TEST_HANDOFF_BOUNDARY_NONE ||
      (reason != RTCORE_RETURN_FOR_ANY_HIT &&
       reason != RTCORE_RETURN_FOR_INTERSECTION)) {
    return true;
  }

  slot->words[13] = 0;
  slot->words[14] = 0;
  slot->words[15] = 0;

  if (mode == RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_ACCEPT) {
    slot->words[13] = RTCORE_HIT_RESULT_ACCEPT_HIT;
  } else if (mode == RTCORE_TEST_HANDOFF_BOUNDARY_ANY_HIT_IGNORE) {
    slot->words[13] = RTCORE_HIT_RESULT_IGNORE_HIT;
  } else if (mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_NO_HIT) {
    slot->words[13] = RTCORE_HIT_RESULT_CONTINUE_OR_NONE;
  } else {
    const unsigned reported_attribute_word_count =
        mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INLINE_OVERFLOW
            ? RTCORE_HANDOFF_MAX_INLINE_ATTRIBUTE_WORDS + 1
            : 1;
    const unsigned reported_hit_kind =
        mode == RTCORE_TEST_HANDOFF_BOUNDARY_INTERSECTION_INVALID_HIT_KIND
            ? 0x80u
            : 0x42u;
    slot->words[13] = RTCORE_HIT_RESULT_REPORTED_INTERSECTION;
    slot->words[14] = slot->words[5];
    slot->words[15] = reported_hit_kind |
                      (reported_attribute_word_count << 8) |
                      (RTCORE_HANDOFF_W_INLINE_ATTRIBUTE_BEGIN << 16) |
                      (0x02u << 24);
    slot->words[16] = 0x3f000000u;
  }

  if (emit_log) {
    printf("GPGPU-Sim PTX: RT_SUBMIT test-software-return-publication "
           "(%s:%u), publication_source=test_only_boundary_fixture, "
           "handoff_profile=v03_compressed_sync, reason=%s, w13=0x%08x, "
           "w14=0x%08x, w15=0x%08x, w16=0x%08x\n",
           pI->source_file(), pI->source_line(),
           rtcore_return_reason_name(reason), slot->words[13],
           slot->words[14], slot->words[15], slot->words[16]);
    fflush(stdout);
  }
  return rtcore_validate_v03_software_return_channel(pI, *slot, reason);
}

bool rtcore_test_publish_v03_software_return_channel(
    const ptx_instruction *pI, const rtcore_synthetic_handoff_key &key,
    unsigned reason) {
  std::map<rtcore_synthetic_handoff_key,
           rtcore_v03_handoff_lane_slot>::iterator window =
      g_rtcore_synthetic_handoff_windows.find(key);
  return window != g_rtcore_synthetic_handoff_windows.end() &&
         rtcore_prepare_v03_software_return_channel_slot(
             pI, reason, &window->second, true);
}

bool rtcore_software_acquire_synthetic_completion(
    const ptx_instruction *pI, unsigned long long context_ptr,
    unsigned long long handoff_window_base, unsigned lane_slot_index,
    unsigned result_word, ptx_thread_info *thread) {
  const rtcore_synthetic_handoff_key key =
      rtcore_make_synthetic_handoff_key(handoff_window_base, lane_slot_index,
                                        thread);
  const rtcore_v03_handoff_lane_slot *window =
      rtcore_acquire_synthetic_handoff_window(
          g_rtcore_synthetic_handoff_windows, key);
  const bool tracked_window = window != NULL;
  const bool matching_context =
      tracked_window && window->context_ptr == context_ptr;
  const bool owner_tuple_matches =
      tracked_window &&
      rtcore_synthetic_owner_tuple_matches(*window, key, context_ptr, pI,
                                           thread);
  const bool compact_result_valid =
      rtcore_v03_compact_result_is_valid(pI, result_word);
  const unsigned result_reason = result_word & 0xffu;
  const bool dependent_groups_match =
      compact_result_valid && tracked_window &&
      rtcore_software_lazy_load_v03_handoff_words(
          pI, *window, result_reason, lane_slot_index);

  const bool accepted =
      tracked_window && matching_context && owner_tuple_matches &&
      compact_result_valid && dependent_groups_match;

  printf("GPGPU-Sim PTX: RT_SUBMIT software-acquire (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, result=0x%08x, tracked=%u, matching_context=%u, "
         "owner_tuple_match=%u, v_result_profile=v03_compact, "
         "compact_result_valid=%u, dependent_groups_match=%u, accepted=%u, "
         "reason=%s\n",
         pI->source_file(), pI->source_line(), context_ptr,
         handoff_window_base, lane_slot_index, result_word,
         tracked_window ? 1 : 0,
         matching_context ? 1 : 0, owner_tuple_matches ? 1 : 0,
         compact_result_valid ? 1 : 0, dependent_groups_match ? 1 : 0,
         accepted ? 1 : 0, rtcore_return_reason_name(result_reason));
  fflush(stdout);
  return accepted;
}

bool rtcore_current_warp_metadata_is_valid(
    const char *op_name, const ptx_instruction *pI, ptx_thread_info *thread,
    const ptx_thread_info::rtcore_current_warp_metadata *metadata,
    unsigned lane_slot_index) {
  const char *metadata_op_name = op_name != NULL ? op_name : "RT_OP";
  const bool has_metadata = metadata != NULL && metadata->valid;
  const bool owner_hw_sid_matches =
      has_metadata && metadata->owner_hw_sid == thread->get_hw_sid();
  const bool warp_id_matches =
      has_metadata && metadata->warp_id == thread->get_hw_wid();
  const bool static_inst_uid_matches =
      has_metadata && metadata->static_inst_uid == pI->uid();
  const bool lane_active =
      has_metadata &&
      rtcore_lane_is_active_in_mask(metadata->active_mask, lane_slot_index);
  const bool accepted =
      has_metadata && owner_hw_sid_matches && warp_id_matches &&
      static_inst_uid_matches && lane_active;

  printf("GPGPU-Sim PTX: %s current-warp-metadata (%s:%u), "
         "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
         "active_mask=0x%08x, static_inst_uid=%u, lane_slot_index=%u, "
         "valid=%u, owner_hw_sid_match=%u, warp_id_match=%u, "
         "static_inst_uid_match=%u, lane_active=%u, accepted=%u\n",
         metadata_op_name, pI->source_file(), pI->source_line(),
         has_metadata ? metadata->warp_uid : 0,
         has_metadata ? metadata->warp_id : 0,
         has_metadata ? metadata->owner_hw_sid : 0,
         has_metadata ? metadata->active_mask : 0,
         has_metadata ? metadata->static_inst_uid : 0, lane_slot_index,
         has_metadata ? 1 : 0, owner_hw_sid_matches ? 1 : 0,
         warp_id_matches ? 1 : 0, static_inst_uid_matches ? 1 : 0,
         lane_active ? 1 : 0, accepted ? 1 : 0);
  fflush(stdout);
  return accepted;
}

static bool rtcore_v04_checked_allocation_base(
    unsigned long long pool_base, unsigned long long allocation_index,
    unsigned allocation_bytes, unsigned long long *allocation_base) {
  if (allocation_base == NULL || allocation_bytes == 0 ||
      allocation_index >
          (std::numeric_limits<unsigned long long>::max() - pool_base) /
              allocation_bytes) {
    return false;
  }
  *allocation_base = pool_base + allocation_index * allocation_bytes;
  return true;
}

bool rtcore_v04_register_global384_provisional_publication(
    const ptx_instruction *pI, ptx_thread_info *thread,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    unsigned lane_slot_index, bool v04_publication_contract,
    unsigned handoff_lane_bytes) {
  rtcore::v04::private_storage::profile_kind profile =
      rtcore::v04::private_storage::kProfileLegacyShared832;
  const rtcore::v04::private_storage::status_kind profile_status =
      rtcore::v04::private_storage::process_profile(&profile);
  if (profile_status != rtcore::v04::private_storage::kStatusOk) {
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
           "reason=GLOBAL384_INVALID_PRIVATE_STORAGE_PROFILE, "
           "profile_status=%s\n",
           pI->source_file(), pI->source_line(),
           rtcore::v04::private_storage::status_name(profile_status));
    fflush(stdout);
    return false;
  }
  if (profile != rtcore::v04::private_storage::kProfileGlobal384) {
    return true;
  }
  if (!v04_publication_contract ||
      handoff_lane_bytes != rtcore::abi_v04::kLaneSlotBytes) {
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
           "reason=GLOBAL384_REQUIRES_V04_PUBLICATION_CONTRACT, "
           "observed_lane_bytes=%u, expected_lane_bytes=%zu\n",
           pI->source_file(), pI->source_line(), handoff_lane_bytes,
           static_cast<size_t>(rtcore::abi_v04::kLaneSlotBytes));
    fflush(stdout);
    return false;
  }

  ptx_thread_info::rtcore_current_warp_metadata metadata;
  thread->get_rtcore_current_warp_metadata(&metadata);
  if (!rtcore_current_warp_metadata_is_valid(
          "RT_PUBLISH_TRACE_CONTEXT", pI, thread, &metadata,
          lane_slot_index)) {
    return false;
  }

  const rtcore_runtime_context_window_allocation_record allocation =
      rtcore_make_runtime_context_window_allocation_record(
          context_ptr, handoff_window_base, lane_slot_index);
  if (!allocation.enabled || !allocation.valid ||
      allocation.context_window_index >
          std::numeric_limits<uint32_t>::max()) {
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
           "reason=GLOBAL384_RUNTIME_ALLOCATION_INVALID, "
           "allocation_enabled=%u, allocation_valid=%u, "
           "context_window_index=%llu\n",
           pI->source_file(), pI->source_line(),
           allocation.enabled ? 1u : 0u, allocation.valid ? 1u : 0u,
           allocation.context_window_index);
    fflush(stdout);
    return false;
  }

  unsigned long long context_allocation_base = 0;
  if (!rtcore_v04_checked_allocation_base(
          allocation.context_base, allocation.context_window_index,
          allocation.context_allocation_bytes, &context_allocation_base)) {
    printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT fail-closed (%s:%u), "
           "reason=GLOBAL384_CONTEXT_ALLOCATION_BASE_OVERFLOW\n",
           pI->source_file(), pI->source_line());
    fflush(stdout);
    return false;
  }

  static const uint64_t kRuntimeAllocationDomainId = UINT64_C(1);
  std::array<uint32_t,
             rtcore::abi_v04::kLaneSlotBytes /
                 rtcore::v04::address_range_registry::kAddressChunkBytes>
      handoff_masks = {};
  const uint32_t owned_words =
      rtcore::abi_v04::shadow::trace_input_owned_word_mask();
  for (size_t word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
    if ((owned_words & (uint32_t{1} << word)) == 0) continue;
    const size_t byte_offset = word * sizeof(uint32_t);
    const size_t chunk =
        byte_offset /
        rtcore::v04::address_range_registry::kAddressChunkBytes;
    const size_t byte_in_chunk =
        byte_offset %
        rtcore::v04::address_range_registry::kAddressChunkBytes;
    handoff_masks[chunk] |= uint32_t{0xf} << byte_in_chunk;
  }

  rtcore::v04::pre_submit_publication::lane_publication_request_v0 request = {};
  request.slot.allocation_domain_id = kRuntimeAllocationDomainId;
  request.slot.allocation_slot_id =
      static_cast<uint32_t>(allocation.context_window_index);
  request.owner.owner_hw_sid = metadata.owner_hw_sid;
  request.owner.dynamic_warp_id = metadata.dynamic_warp_id;
  request.owner.warp_id = metadata.warp_id;
  request.allocation_ranges.context_base = context_allocation_base;
  request.allocation_ranges.context_byte_count =
      allocation.context_allocation_bytes;
  request.allocation_ranges.handoff_base = allocation.handoff_window_base;
  request.allocation_ranges.handoff_byte_count =
      allocation.handoff_allocation_bytes;
  request.publication_warp_uid = metadata.warp_uid;
  request.active_mask = metadata.active_mask;
  request.capacity_lane_slots = allocation.capacity_lane_slots;
  request.context_lane_stride_bytes =
      allocation.context_lane_stride_bytes;
  request.handoff_lane_stride_bytes =
      allocation.handoff_lane_slot_stride_bytes;
  request.handoff_allowed_publication_masks = handoff_masks.data();
  request.handoff_allowed_publication_mask_count = handoff_masks.size();
  request.lane_id = static_cast<uint8_t>(lane_slot_index);

  rtcore::v04::pre_submit_publication::lane_publication_result_v0 result = {};
  const rtcore::v04::pre_submit_publication::status_kind bridge_status =
      rtcore::v04::pre_submit_publication::shared_bridge()
          .observe_initial_publication(request, &result);
  printf("GPGPU-Sim PTX: RT_PUBLISH_TRACE_CONTEXT "
         "global384-provisional-publication (%s:%u), "
         "bridge_status=%s, authority_status=%s, registry_status=%s, "
         "allocation_domain_id=%llu, allocation_slot_id=%u, "
         "launch_allocation_generation=%u, window_generation=%u, "
         "dynamic_warp_id=%u, publication_warp_uid=%u, warp_id=%u, "
         "active_mask=0x%08x, published_lane_mask=0x%08x, "
         "lane_slot_index=%u, publication_complete=%u, "
         "provisional_group_registered=%u, memory_transaction=0\n",
         pI->source_file(), pI->source_line(),
         rtcore::v04::pre_submit_publication::status_name(bridge_status),
         rtcore::v04::allocation_identity::status_name(
             result.authority_status),
         rtcore::v04::address_range_registry::status_name(
             result.registry_status),
         static_cast<unsigned long long>(request.slot.allocation_domain_id),
         request.slot.allocation_slot_id,
         result.identity.launch_allocation_generation,
         result.identity.window_generation, metadata.dynamic_warp_id,
         metadata.warp_uid, metadata.warp_id, metadata.active_mask,
         result.published_lane_mask, lane_slot_index,
         result.publication_complete, result.provisional_group_registered);
  fflush(stdout);
  if (bridge_status ==
          rtcore::v04::pre_submit_publication::kStatusOk &&
      result.lane_was_new == 1) {
    rtcore_record_v04_global384_context_functional_setup(
        metadata.owner_hw_sid, lane_slot_index,
        allocation.context_lane_stride_bytes);
  }
  return bridge_status ==
         rtcore::v04::pre_submit_publication::kStatusOk;
}

struct rtcore_v04_global384_bind_material {
  rtcore::v04::pre_submit_publication::first_submit_bind_request_v0 request;
  std::array<uint32_t,
             rtcore::abi_v04::kLaneSlotBytes /
                 rtcore::v04::address_range_registry::kAddressChunkBytes>
      handoff_masks;
  unsigned dynamic_warp_id;

  rtcore_v04_global384_bind_material()
      : request(), handoff_masks(), dynamic_warp_id(0) {}
};

struct rtcore_v04_global384_pending_bind_owner {
  unsigned dynamic_warp_id;
  unsigned reserved_warp_uid;
  unsigned warp_id;
  unsigned active_mask;
  bool owner_plan_valid;
  bool owner_plan_committed;
  bool timing_driver_owned;
  bool private_init_plan_valid;
  rtcore::v04::request_owner::new_warp_plan_v0 owner_plan;
  rtcore::v04::private_global_region::whole_mask_launch_plan_v0
      private_init_plan;

  rtcore_v04_global384_pending_bind_owner()
      : dynamic_warp_id(0), reserved_warp_uid(0), warp_id(0),
        active_mask(0), owner_plan_valid(false), owner_plan_committed(false),
        timing_driver_owned(false), private_init_plan_valid(false),
        owner_plan(), private_init_plan() {}
};

static std::map<unsigned, rtcore_v04_global384_pending_bind_owner>
    g_rtcore_v04_global384_pending_bind_by_sm;

static bool rtcore_v04_global384_rollback_pending_timing_owner(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask,
    const request_owner::new_warp_plan_v0 &owner_plan,
    bool timing_driver_owned) {
  if (!timing_driver_owned) return true;
  if (!rtcore_rollback_v04_global384_timing_preissue(
          owner_hw_sid, warp_uid, warp_id, active_mask, &owner_plan)) {
    return false;
  }
  g_rtcore_v04_global384_pending_bind_by_sm.erase(owner_hw_sid);
  return true;
}

static bool rtcore_v04_make_global384_bind_material(
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned expected_dynamic_warp_id, unsigned warp_id,
    unsigned active_mask, rtcore_v04_global384_bind_material *material) {
  if (instruction == NULL || lane_threads == NULL || material == NULL ||
      active_mask == 0 || instruction->op != RT_CORE_OP ||
      instruction->rt_subop != RT_CORE_SUBOP_SUBMIT ||
      instruction->get_num_operands() != 3) {
    return false;
  }
  *material = rtcore_v04_global384_bind_material();
  const operand_info &context_operand = instruction->operand_lookup(1);
  const operand_info &handoff_operand = instruction->operand_lookup(2);
  bool have_common = false;
  unsigned long long common_context_allocation_base = 0;
  rtcore_runtime_context_window_allocation_record common;
  for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
    if ((active_mask & (1u << lane)) == 0) continue;
    ptx_thread_info *thread = lane_threads[lane];
    if (thread == NULL) return false;
    const ptx_reg_t context_value = thread->get_operand_value(
        context_operand, context_operand, B64_TYPE, thread, 1);
    const ptx_reg_t handoff_value = thread->get_operand_value(
        handoff_operand, handoff_operand, B64_TYPE, thread, 1);
    const rtcore_runtime_context_window_allocation_record allocation =
        rtcore_make_runtime_context_window_allocation_record(
            context_value.u64, handoff_value.u64, lane);
    unsigned long long context_allocation_base = 0;
    if (!allocation.enabled || !allocation.valid ||
        allocation.context_window_index >
            std::numeric_limits<uint32_t>::max() ||
        !rtcore_v04_checked_allocation_base(
            allocation.context_base, allocation.context_window_index,
            allocation.context_allocation_bytes,
            &context_allocation_base)) {
      return false;
    }
    if (!have_common) {
      common = allocation;
      common_context_allocation_base = context_allocation_base;
      have_common = true;
    } else if (context_allocation_base != common_context_allocation_base ||
               allocation.context_window_index !=
                   common.context_window_index ||
               allocation.handoff_window_base !=
                   common.handoff_window_base ||
               allocation.context_allocation_bytes !=
                   common.context_allocation_bytes ||
               allocation.handoff_allocation_bytes !=
                   common.handoff_allocation_bytes ||
               allocation.context_lane_stride_bytes !=
                   common.context_lane_stride_bytes ||
               allocation.handoff_lane_slot_stride_bytes !=
                   common.handoff_lane_slot_stride_bytes ||
               allocation.capacity_lane_slots !=
                   common.capacity_lane_slots ||
               allocation.owner_generation != common.owner_generation) {
      return false;
    }
  }
  if (!have_common) return false;

  const uint32_t owned_words =
      rtcore::abi_v04::shadow::trace_input_owned_word_mask();
  for (size_t word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
    if ((owned_words & (uint32_t{1} << word)) == 0) continue;
    const size_t byte_offset = word * sizeof(uint32_t);
    const size_t chunk =
        byte_offset /
        rtcore::v04::address_range_registry::kAddressChunkBytes;
    const size_t byte_in_chunk =
        byte_offset %
        rtcore::v04::address_range_registry::kAddressChunkBytes;
    material->handoff_masks[chunk] |= uint32_t{0xf} << byte_in_chunk;
  }
  static const uint64_t kRuntimeAllocationDomainId = UINT64_C(1);
  material->request.slot.allocation_domain_id =
      kRuntimeAllocationDomainId;
  material->request.slot.allocation_slot_id =
      static_cast<uint32_t>(common.context_window_index);
  material->request.owner.owner_hw_sid = owner_hw_sid;
  material->request.owner.dynamic_warp_id = expected_dynamic_warp_id;
  material->request.owner.warp_id = warp_id;
  material->request.allocation_ranges.context_base =
      common_context_allocation_base;
  material->request.allocation_ranges.context_byte_count =
      common.context_allocation_bytes;
  material->request.allocation_ranges.handoff_base =
      common.handoff_window_base;
  material->request.allocation_ranges.handoff_byte_count =
      common.handoff_allocation_bytes;
  material->request.active_mask = active_mask;
  material->request.capacity_lane_slots = common.capacity_lane_slots;
  material->request.context_lane_stride_bytes =
      common.context_lane_stride_bytes;
  material->request.handoff_lane_stride_bytes =
      common.handoff_lane_slot_stride_bytes;
  material->request.handoff_allowed_publication_masks =
      material->handoff_masks.data();
  material->request.handoff_allowed_publication_mask_count =
      material->handoff_masks.size();
  material->dynamic_warp_id = expected_dynamic_warp_id;
  return true;
}

static bool rtcore_v04_make_global384_retire_release_material(
    const rtcore_symbolic_retire_transaction &transaction,
    rtcore_v04_global384_bind_material *material,
    const char **failure_reason) {
  if (failure_reason != NULL) *failure_reason = "accepted";
  const auto reject = [failure_reason](const char *reason) {
    if (failure_reason != NULL) *failure_reason = reason;
    return false;
  };
  if (material == NULL) return reject("material_missing");
  if (!transaction.valid) return reject("transaction_invalid");
  if (!transaction.claimed) return reject("transaction_not_claimed");
  if (transaction.active_mask == 0) return reject("active_mask_empty");
  if (transaction.seen_lane_mask != transaction.active_mask)
    return reject("seen_lane_mask_mismatch");
  if (transaction.validated_lane_mask != transaction.active_mask)
    return reject("validated_lane_mask_mismatch");
  *material = rtcore_v04_global384_bind_material();
  bool have_common = false;
  unsigned long long common_context_allocation_base = 0;
  rtcore_runtime_context_window_allocation_record common;
  for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
    if ((transaction.active_mask & (1u << lane)) == 0) continue;
    const rtcore_symbolic_retire_lane_intent &intent = transaction.lane[lane];
    const rtcore_runtime_context_window_allocation_record &allocation =
        intent.allocation_record;
    unsigned long long context_allocation_base = 0;
    if (!intent.valid) return reject("lane_intent_invalid");
    if (!allocation.enabled) return reject("allocation_disabled");
    if (!allocation.valid) return reject("allocation_invalid");
    if (allocation.lane_slot_index != lane)
      return reject("allocation_lane_slot_mismatch");
    if (allocation.context_ptr != intent.context_ptr)
      return reject("allocation_context_ptr_mismatch");
    if (allocation.handoff_window_base != intent.handoff_window_base)
      return reject("allocation_handoff_base_mismatch");
    if (allocation.context_window_index >
        std::numeric_limits<uint32_t>::max())
      return reject("allocation_window_index_overflow");
    if (!rtcore_v04_checked_allocation_base(
            allocation.context_base, allocation.context_window_index,
            allocation.context_allocation_bytes, &context_allocation_base))
      return reject("allocation_context_base_invalid");
    if (!have_common) {
      common = allocation;
      common_context_allocation_base = context_allocation_base;
      have_common = true;
    } else if (context_allocation_base != common_context_allocation_base ||
               allocation.context_window_index !=
                   common.context_window_index ||
               allocation.handoff_window_base !=
                   common.handoff_window_base ||
               allocation.context_allocation_bytes !=
                   common.context_allocation_bytes ||
               allocation.handoff_allocation_bytes !=
                   common.handoff_allocation_bytes ||
               allocation.context_lane_stride_bytes !=
                   common.context_lane_stride_bytes ||
               allocation.handoff_lane_slot_stride_bytes !=
                   common.handoff_lane_slot_stride_bytes ||
               allocation.capacity_lane_slots !=
                   common.capacity_lane_slots ||
               allocation.owner_generation != common.owner_generation) {
      return reject("allocation_geometry_mismatch");
    }
  }
  if (!have_common) return reject("common_allocation_missing");

  const uint32_t owned_words =
      rtcore::abi_v04::shadow::trace_input_owned_word_mask();
  for (size_t word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
    if ((owned_words & (uint32_t{1} << word)) == 0) continue;
    const size_t byte_offset = word * sizeof(uint32_t);
    const size_t chunk =
        byte_offset /
        rtcore::v04::address_range_registry::kAddressChunkBytes;
    const size_t byte_in_chunk =
        byte_offset %
        rtcore::v04::address_range_registry::kAddressChunkBytes;
    material->handoff_masks[chunk] |= uint32_t{0xf} << byte_in_chunk;
  }
  static const uint64_t kRuntimeAllocationDomainId = UINT64_C(1);
  material->request.slot.allocation_domain_id = kRuntimeAllocationDomainId;
  material->request.slot.allocation_slot_id =
      static_cast<uint32_t>(common.context_window_index);
  material->request.owner.owner_hw_sid = transaction.owner_hw_sid;
  material->request.owner.dynamic_warp_id = transaction.dynamic_warp_id;
  material->request.owner.warp_id = transaction.warp_id;
  material->request.allocation_ranges.context_base =
      common_context_allocation_base;
  material->request.allocation_ranges.context_byte_count =
      common.context_allocation_bytes;
  material->request.allocation_ranges.handoff_base =
      common.handoff_window_base;
  material->request.allocation_ranges.handoff_byte_count =
      common.handoff_allocation_bytes;
  material->request.active_mask = transaction.active_mask;
  material->request.capacity_lane_slots = common.capacity_lane_slots;
  material->request.context_lane_stride_bytes =
      common.context_lane_stride_bytes;
  material->request.handoff_lane_stride_bytes =
      common.handoff_lane_slot_stride_bytes;
  material->request.handoff_allowed_publication_masks =
      material->handoff_masks.data();
  material->request.handoff_allowed_publication_mask_count =
      material->handoff_masks.size();
  material->dynamic_warp_id = transaction.dynamic_warp_id;
  return true;
}

static bool rtcore_v04_global384_pending_owner_matches(
    const rtcore_v04_global384_pending_bind_owner &owner,
    unsigned dynamic_warp_id, unsigned reserved_warp_uid,
    unsigned warp_id, unsigned active_mask) {
  return owner.dynamic_warp_id == dynamic_warp_id &&
         owner.reserved_warp_uid == reserved_warp_uid &&
         owner.warp_id == warp_id && owner.active_mask == active_mask;
}

static bool rtcore_v04_global384_pending_logical_submit_matches(
    const rtcore_v04_global384_pending_bind_owner &owner,
    unsigned dynamic_warp_id, unsigned warp_id, unsigned active_mask) {
  return owner.dynamic_warp_id == dynamic_warp_id &&
         owner.warp_id == warp_id && owner.active_mask == active_mask;
}

static bool rtcore_v04_global384_owner_plan_is_live(
    const request_owner::allocator_state_v0 &allocator,
    const request_owner::new_warp_plan_v0 &plan) {
  if (!plan.valid || plan.identity.active_mask == 0) return false;
  for (unsigned lane = 0; lane < request_owner::kLaneCapacity; ++lane) {
    if ((plan.identity.active_mask & (1u << lane)) == 0) continue;
    if (!request_owner::validate_live_binding(
            allocator, plan.lane_bindings[lane], plan.identity.warp_uid,
            plan.identity.active_mask)) {
      return false;
    }
  }
  return true;
}

static bool rtcore_v04_global384_build_private_init_plan(
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned dynamic_warp_id, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask, unsigned resident_warp_generation,
    const request_owner::new_warp_plan_v0 &owner_plan,
    const rtcore_v04_global384_bind_material &material,
    rtcore::v04::private_global_region::whole_mask_launch_plan_v0 *plan) {
  namespace global_region = rtcore::v04::private_global_region;
  namespace private_state = rtcore::v04::private_state_384;
  namespace storage = rtcore::v04::private_storage;
  namespace typed_blas = rtcore::v04::typed_blas;
  if (instruction == NULL || lane_threads == NULL || plan == NULL ||
      owner_hw_sid == UINT32_MAX ||
      !owner_plan.valid || owner_plan.identity.owner_hw_sid != owner_hw_sid ||
      owner_plan.identity.warp_uid != warp_uid ||
      owner_plan.identity.warp_id != warp_id ||
      owner_plan.identity.active_mask != active_mask ||
      owner_plan.resident_warp_slot >= global_region::kResidentWarpCapacity ||
      resident_warp_generation == 0 || active_mask == 0) {
    return false;
  }

  const operand_info &context_operand = instruction->operand_lookup(1);
  const operand_info &handoff_operand = instruction->operand_lookup(2);
  rtcore::v04::private_frontier::owner_binding_v0
      owners[global_region::kLaneCapacity] = {};
  private_state::sparse_write_plan_v1
      launch_plans[global_region::kLaneCapacity] = {};
  for (unsigned lane = 0; lane < global_region::kLaneCapacity; ++lane) {
    if ((active_mask & (1u << lane)) == 0) continue;
    ptx_thread_info *thread = lane_threads[lane];
    if (thread == NULL || thread->get_uid() == 0) return false;
    const ptx_reg_t context_value = thread->get_operand_value(
        context_operand, context_operand, B64_TYPE, thread, 1);
    const ptx_reg_t handoff_value = thread->get_operand_value(
        handoff_operand, handoff_operand, B64_TYPE, thread, 1);
    rtcore_v03_compact_context_decoded context;
    if (context_value.u64 == 0 || handoff_value.u64 == 0 ||
        (context_value.u64 & 63u) != 0 ||
        (handoff_value.u64 & 127u) != 0 ||
        !rtcore_decode_v03_compact_context_image(
            instruction, thread, context_value.u64, &context)) {
      return false;
    }
    std::array<uint8_t, rtcore::abi_v04::kLaneSlotBytes> handoff_image = {};
    if (!rtcore_copy_v04_global384_initial_handoff_acquire_lane_before_functional(
            owner_hw_sid, dynamic_warp_id, warp_uid, warp_id, active_mask,
            resident_warp_generation, lane, handoff_image.data(),
            handoff_image.size())) {
      return false;
    }
    std::array<uint32_t, rtcore::abi_v04::kWordCount> trace_words = {};
    if (!rtcore_validate_v04_shadow_trace_input(
            instruction, thread, context_value.u64, handoff_value.u64, lane,
            context, owner_hw_sid, dynamic_warp_id, warp_uid, warp_id,
            resident_warp_generation, handoff_image.data(),
            handoff_image.size(), &trace_words)) {
      return false;
    }
    rtcore::abi_v04::shadow::trace_input_values trace = {};
    if (!rtcore::abi_v04::shadow::unpack_trace_input_words(trace_words,
                                                           &trace)) {
      return false;
    }
    rtcore_tlas_binding_snapshot tlas = {};
    const char *capture_failure = "unvalidated";
    if (!VulkanRayTracing::captureTlasBinding(
            trace.traversable_reference, &tlas, &capture_failure) ||
        !tlas.valid || !tlas.live || !tlas.root_descriptor_valid ||
        tlas.root_build_generation == 0 ||
        tlas.root_bvh_profile_id != typed_blas::kGenRtDerivedProfileId ||
        tlas.root_payload_format_id != typed_blas::kGenRtPayloadFormatId ||
        tlas.root_payload_kind != typed_blas::kInternalPayloadKind ||
        tlas.root_payload_offset > tlas.size_bytes ||
        uint64_t{64} > tlas.size_bytes - tlas.root_payload_offset ||
        tlas.device_base_address > UINT64_MAX - tlas.root_payload_offset) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_INIT_FAULT "
              "phase=materialize reason=%s owner_hw_sid=%u warp_uid=%u "
              "warp_id=%u lane_id=%u\n",
              capture_failure, owner_hw_sid, warp_uid, warp_id, lane);
      fflush(stderr);
      return false;
    }

    private_state::launch_input_v1 launch = {};
    for (unsigned component = 0; component < 3; ++component) {
      launch.ray.origin[component] = rtcore_context_u32_to_float(
          trace.world_ray_origin_fp32[component]);
      launch.ray.direction[component] = rtcore_context_u32_to_float(
          trace.world_ray_direction_fp32[component]);
    }
    launch.ray.t_min = rtcore_context_u32_to_float(trace.ray_tmin_fp32);
    launch.ray.t_max =
        rtcore_context_u32_to_float(trace.launch_ray_tmax_fp32);
    launch.tlas_context.as_object_id = tlas.object_id;
    launch.tlas_context.device_base = tlas.device_base_address;
    launch.tlas_context.device_range_bytes = tlas.size_bytes;
    launch.tlas_context.as_object_generation = tlas.generation;
    launch.tlas_context.as_type = 1;
    launch.tlas_context.cull_mask = static_cast<uint8_t>(trace.cull_mask);
    launch.ray_flags = trace.ray_flags;
    launch.tlas_build_generation = tlas.root_build_generation;
    private_state::image_v1 transient_image = {};
    if (private_state::initialize_new_launch_image(
            private_state::kPrivateLayoutProfileId,
            private_state::kGenRtBvhFormatProfileId, launch,
            &transient_image, &launch_plans[lane]) !=
            private_state::kStatusOk ||
        launch_plans[lane].write_count != private_state::kLaunchWriteCount) {
      return false;
    }
    owners[lane] = request_owner::make_private_frontier_owner(
        owner_plan.lane_bindings[lane]);
  }

  global_region::region_config_v0 config = {};
  config.hidden_base = UINT64_C(0x7c00000000000000);
  config.sm_region_stride = UINT64_C(0x20000);
  config.sm_count = owner_hw_sid + 1;
  config.configured_l1_line_bytes = 128;
  global_region::status_kind global_status =
      global_region::parse_base_color(
          getenv(global_region::kBaseColorEnvironmentName),
          &config.base_color);
  if (global_status != global_region::kStatusOk) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_INIT_FAULT "
            "phase=config reason=invalid_base_color status=%s "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u\n",
            global_region::status_name(global_status), owner_hw_sid,
            warp_uid, warp_id);
    fflush(stderr);
    return false;
  }
  global_region::address_range_v0 visible_ranges[2] = {};
  visible_ranges[0].base = material.request.allocation_ranges.context_base;
  visible_ranges[0].byte_count =
      material.request.allocation_ranges.context_byte_count;
  visible_ranges[1].base = material.request.allocation_ranges.handoff_base;
  visible_ranges[1].byte_count =
      material.request.allocation_ranges.handoff_byte_count;
  const storage::status_kind status =
      storage::prepare_global384_launch_candidate_from_selector(
          getenv(storage::kSelectorEnvironmentName), config, visible_ranges,
          2, owner_hw_sid, warp_uid, warp_id,
          owner_plan.resident_warp_slot, active_mask, owners, launch_plans,
          &global_status, plan);
  if (status != storage::kStatusOk ||
      global_status != global_region::kStatusOk || !plan->valid) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_INIT_FAULT "
            "phase=plan storage_status=%s global_status=%s owner_hw_sid=%u "
            "warp_uid=%u warp_id=%u\n",
            storage::status_name(status),
            global_region::status_name(global_status), owner_hw_sid, warp_uid,
            warp_id);
    fflush(stderr);
    return false;
  }
  printf("GPGPU-Sim RTCORE_V04_GLOBAL384_REGION_CONFIG "
         "owner_hw_sid=%u base_color=%u configured_l1_line_bytes=%u "
         "hidden_base=0x%llx colored_hidden_base=0x%llx "
         "sm_region_stride=%llu region_bytes=%llu\n",
         owner_hw_sid, plan->layout.base_color,
         plan->layout.configured_l1_line_bytes,
         static_cast<unsigned long long>(plan->layout.hidden_base),
         static_cast<unsigned long long>(plan->layout.colored_hidden_base),
         static_cast<unsigned long long>(plan->layout.sm_region_stride),
         static_cast<unsigned long long>(plan->layout.region_bytes));
  fflush(stdout);
  return true;
}

static bool rtcore_v04_global384_validate_preissued_owner_plan(
    const root_node_packet::warp_input_v0 &input,
    request_owner::new_warp_plan_v0 *plan) {
  if (plan == NULL) return false;
  std::map<unsigned, rtcore_v04_global384_pending_bind_owner>::iterator pending =
      g_rtcore_v04_global384_pending_bind_by_sm.find(input.owner_hw_sid);
  if (pending == g_rtcore_v04_global384_pending_bind_by_sm.end() ||
      !pending->second.owner_plan_valid ||
      !pending->second.private_init_plan_valid ||
      pending->second.reserved_warp_uid != input.warp_uid ||
      pending->second.warp_id != input.warp_id ||
      pending->second.active_mask != input.active_mask) {
    return false;
  }
  if (!pending->second.owner_plan_committed ||
      (pending->second.timing_driver_owned
           ? !rtcore_validate_v04_global384_timing_owner_plan(
                 input.owner_hw_sid, &pending->second.owner_plan)
           : !rtcore_v04_global384_owner_plan_is_live(
                 rtcore_v04_functional_only_allocator(input.owner_hw_sid),
                 pending->second.owner_plan))) {
    return false;
  }
  const rtcore::v04::private_global_region::whole_mask_launch_plan_v0 &global =
      pending->second.private_init_plan;
  for (unsigned lane = 0; lane < root_node_packet::kLaneCapacity; ++lane) {
    if ((input.active_mask & (1u << lane)) == 0) continue;
    const root_node_packet::lane_input_v0 &lane_input = input.lanes[lane];
    rtcore::v04::private_state_384::launch_input_v1 launch = {};
    for (unsigned component = 0; component < 3; ++component) {
      launch.ray.origin[component] =
          lane_input.private_operands.mutable_ray.origin[component];
      launch.ray.direction[component] =
          lane_input.private_operands.mutable_ray.direction[component];
    }
    launch.ray.t_min = lane_input.private_operands.mutable_ray.t_min;
    launch.ray.t_max = lane_input.private_operands.mutable_ray.t_max;
    launch.tlas_context.as_object_id =
        lane_input.private_operands.decode_context.as_object.object_id;
    launch.tlas_context.device_base =
        lane_input.private_operands.decode_context.device_base;
    launch.tlas_context.device_range_bytes =
        lane_input.private_operands.decode_context.device_range_bytes;
    launch.tlas_context.as_object_generation =
        lane_input.private_operands.decode_context.as_object.generation;
    launch.tlas_context.as_type =
        lane_input.private_operands.decode_context.as_object.as_type;
    launch.tlas_context.cull_mask = lane_input.ray_policy.cull_mask;
    launch.ray_flags = lane_input.ray_policy.ray_flags;
    launch.tlas_build_generation = lane_input.root_build_generation;
    rtcore::v04::private_state_384::image_v1 image = {};
    rtcore::v04::private_state_384::sparse_write_plan_v1 sparse = {};
    if (rtcore::v04::private_state_384::initialize_new_launch_image(
            rtcore::v04::private_state_384::kPrivateLayoutProfileId,
            rtcore::v04::private_state_384::kGenRtBvhFormatProfileId, launch,
            &image, &sparse) != rtcore::v04::private_state_384::kStatusOk ||
        sparse.write_count !=
            rtcore::v04::private_state_384::kLaunchWriteCount) {
      return false;
    }
    for (unsigned chunk = 0;
         chunk < rtcore::v04::private_state_384::kLaunchWriteCount; ++chunk) {
      const rtcore::v04::private_state_384::chunk_write_v1 &expected =
          sparse.writes[chunk];
      const rtcore::v04::private_global_region::global_chunk_write_v0 &actual =
          global.lanes[lane].writes[chunk];
      if (expected.slot_byte_offset != actual.slot_byte_offset ||
          expected.byte_count != actual.byte_count ||
          expected.byte_mask != actual.byte_mask ||
          std::memcmp(expected.payload, actual.payload,
                      sizeof(expected.payload)) != 0) {
        return false;
      }
    }
  }
  unsigned current_warp_uid = 0;
  unsigned current_active_mask = 0;
  unsigned resident_generation = 0;
  unsigned resident_occupancy = 0;
  if (!rtcore_query_resident_rt_warp_record(
          input.owner_hw_sid, input.warp_id, &current_warp_uid,
          &current_active_mask, &resident_generation, &resident_occupancy) ||
      current_warp_uid != input.warp_uid ||
      current_active_mask != input.active_mask || resident_generation == 0 ||
      resident_occupancy == 0) {
    return false;
  }
  if (!rtcore_validate_v04_global384_private_init_before_functional(
          pending->second.dynamic_warp_id,
          resident_generation,
          &pending->second.private_init_plan)) {
    return false;
  }
  *plan = pending->second.owner_plan;
  return true;
}

static bool rtcore_v04_global384_consume_preissued_owner_plan(
    const root_node_packet::warp_input_v0 &input) {
  std::map<unsigned, rtcore_v04_global384_pending_bind_owner>::iterator pending =
      g_rtcore_v04_global384_pending_bind_by_sm.find(input.owner_hw_sid);
  if (pending == g_rtcore_v04_global384_pending_bind_by_sm.end() ||
      pending->second.reserved_warp_uid != input.warp_uid ||
      pending->second.warp_id != input.warp_id ||
      pending->second.active_mask != input.active_mask) {
    return false;
  }
  g_rtcore_v04_global384_pending_bind_by_sm.erase(pending);
  return true;
}

static rtcore_v04_first_submit_live_bind_preissue_status
rtcore_v04_global384_advance_private_init_after_handoff(
    rtcore_v04_first_submit_live_bind_preissue_status handoff_status,
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned dynamic_warp_id, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask, unsigned resident_warp_generation,
    const rtcore_v04_global384_bind_material &material,
    unsigned long long issue_cycle) {
  if (handoff_status != RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_HANDOFF_READY) {
    return handoff_status;
  }
  std::map<unsigned, rtcore_v04_global384_pending_bind_owner>::iterator pending =
      g_rtcore_v04_global384_pending_bind_by_sm.find(owner_hw_sid);
  if (pending == g_rtcore_v04_global384_pending_bind_by_sm.end() ||
      !pending->second.owner_plan_valid ||
      !rtcore_v04_global384_pending_owner_matches(
          pending->second, dynamic_warp_id, warp_uid, warp_id, active_mask)) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  if (!pending->second.private_init_plan_valid) {
    rtcore::v04::private_global_region::whole_mask_launch_plan_v0 plan = {};
    if (!rtcore_v04_global384_build_private_init_plan(
            instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
            warp_uid, warp_id, active_mask, resident_warp_generation,
            pending->second.owner_plan, material, &plan)) {
      return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
    }
    pending->second.private_init_plan = plan;
    pending->second.private_init_plan_valid = true;
  }
  if (!rtcore_bind_v04_global384_resident_layout(
          owner_hw_sid, warp_uid, warp_id, active_mask,
          resident_warp_generation,
          &pending->second.private_init_plan.layout)) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  return rtcore_service_v04_global384_private_init_before_issue(
      dynamic_warp_id, resident_warp_generation,
      &pending->second.private_init_plan, issue_cycle);
}

static bool rtcore_validate_v04_global384_resubmit_live_internal(
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned dynamic_warp_id, unsigned previous_warp_uid,
    unsigned warp_uid, unsigned warp_id, unsigned previous_active_mask,
    unsigned active_mask, unsigned resident_warp_generation);

static rtcore_v04_first_submit_live_bind_preissue_status
rtcore_service_v04_global384_first_submit_live_bind_internal(
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned dynamic_warp_id, unsigned expected_warp_uid,
    unsigned warp_id, unsigned active_mask,
    unsigned long long issue_cycle) {
  bool global384 = false;
  if (!rtcore_v04_global384_profile_selected(&global384)) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  if (!global384) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_NOT_APPLICABLE;
  }
  const bool functional_only =
      rtcore_v04_functional_only_engine_gate_active();
  const bool timing_driver_owned = !functional_only;
  if (!rtcore_v04_root_node_input_gate_active()) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }

  unsigned previous_warp_uid = 0;
  unsigned previous_active_mask = 0;
  unsigned previous_generation = 0;
  unsigned resident_occupancy = 0;
  const bool resident_live = rtcore_query_resident_rt_warp_record(
      owner_hw_sid, warp_id, &previous_warp_uid,
      &previous_active_mask, &previous_generation,
      &resident_occupancy);
  rtcore_v04_global384_bind_material material;
  if (!rtcore_v04_make_global384_bind_material(
          instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
          warp_id, active_mask, &material)) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  unsigned lane_request_ids[RTCORE_MAX_LANES_PER_WARP] = {};
  for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
    if ((active_mask & (1u << lane)) == 0) continue;
    if (lane_threads[lane] == NULL || lane_threads[lane]->get_uid() == 0) {
      return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
    }
    lane_request_ids[lane] = lane_threads[lane]->get_uid();
  }
  std::map<unsigned, rtcore_v04_global384_pending_bind_owner>::iterator
      pending = g_rtcore_v04_global384_pending_bind_by_sm.find(owner_hw_sid);
  if (pending != g_rtcore_v04_global384_pending_bind_by_sm.end() &&
      !rtcore_v04_global384_pending_owner_matches(
          pending->second, dynamic_warp_id, expected_warp_uid,
          warp_id, active_mask)) {
    return rtcore_v04_global384_pending_logical_submit_matches(
               pending->second, dynamic_warp_id, warp_id, active_mask)
               ? RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT
               : RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_WAIT;
  }
  if (resident_live && expected_warp_uid == previous_warp_uid) {
    if (active_mask != previous_active_mask ||
        !rtcore_validate_v04_global384_resident_warp_shell(
            owner_hw_sid, expected_warp_uid, warp_id, active_mask,
            instruction != NULL ? instruction->uid() : 0,
            previous_generation)) {
      return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
    }
    const rtcore_v04_first_submit_live_bind_preissue_status poll_status =
        rtcore_poll_v04_global384_initial_handoff_acquire_before_issue(
            owner_hw_sid, dynamic_warp_id, expected_warp_uid, warp_id,
            active_mask, previous_generation,
            material.request.allocation_ranges.handoff_base,
            material.request.handoff_lane_stride_bytes, issue_cycle);
    if (poll_status == RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_NOT_APPLICABLE) {
      return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
    }
    return rtcore_v04_global384_advance_private_init_after_handoff(
        poll_status, instruction, lane_threads, owner_hw_sid,
        dynamic_warp_id, expected_warp_uid, warp_id, active_mask,
        previous_generation, material, issue_cycle);
  }
  if (resident_live && expected_warp_uid != previous_warp_uid &&
      active_mask != 0 &&
      (active_mask & ~previous_active_mask) == 0) {
    const rtcore_v04_first_submit_live_bind_preissue_status poll_status =
        rtcore_poll_v04_global384_resubmit_handoff_acquire_before_issue(
            owner_hw_sid, dynamic_warp_id, previous_warp_uid, warp_id,
            previous_active_mask, active_mask, previous_generation,
            material.request.allocation_ranges.handoff_base,
            material.request.handoff_lane_stride_bytes, issue_cycle);
    if (poll_status !=
        RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_NOT_APPLICABLE) {
      return poll_status;
    }
    if (!rtcore_validate_v04_global384_resubmit_live_internal(
            instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
            previous_warp_uid, expected_warp_uid, warp_id,
            previous_active_mask, active_mask, previous_generation)) {
      return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
    }
    unsigned lane_request_ids[RTCORE_MAX_LANES_PER_WARP] = {};
    for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
      if ((active_mask & (1u << lane)) == 0) continue;
      if (lane_threads[lane] == NULL || lane_threads[lane]->get_uid() == 0) {
        return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
      }
      lane_request_ids[lane] = lane_threads[lane]->get_uid();
    }
    return rtcore_service_v04_global384_resubmit_handoff_acquire_before_issue(
        owner_hw_sid, dynamic_warp_id, previous_warp_uid, warp_id,
        previous_active_mask, active_mask, previous_generation,
        material.request.allocation_ranges.handoff_base,
        material.request.handoff_lane_stride_bytes, lane_request_ids,
        issue_cycle);
  }
  if (resident_live &&
      !rtcore_validate_v04_global384_resident_warp_shell(
          owner_hw_sid, expected_warp_uid, warp_id, active_mask,
          instruction != NULL ? instruction->uid() : 0,
          previous_generation)) {
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_NOT_APPLICABLE;
  }
  request_owner::new_warp_plan_v0 resource_plan = {};
  const bool create_pending =
      pending == g_rtcore_v04_global384_pending_bind_by_sm.end();
  if (create_pending) {
    request_owner::warp_identity_v0 identity = {};
    identity.owner_hw_sid = owner_hw_sid;
    identity.warp_uid = expected_warp_uid;
    identity.warp_id = warp_id;
    identity.active_mask = active_mask;
    if (timing_driver_owned) {
      const rtcore_v04_global384_timing_owner_status timing_status =
          rtcore_prepare_commit_v04_global384_timing_owner_plan(
              owner_hw_sid, expected_warp_uid, warp_id, active_mask,
              &resource_plan);
      if (timing_status != RTCORE_V04_GLOBAL384_TIMING_OWNER_READY) {
        return timing_status == RTCORE_V04_GLOBAL384_TIMING_OWNER_WAIT
                   ? RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_WAIT
                   : RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
      }
    } else {
      request_owner::allocator_state_v0 &allocator =
          rtcore_v04_functional_only_allocator(owner_hw_sid);
      const request_owner::status_kind resource_status =
          request_owner::prepare_new_warp(allocator, identity,
                                          &resource_plan);
      if (resource_status != request_owner::kStatusOk) {
        return resource_status ==
                           request_owner::kStatusResidentCapacityExceeded ||
                       resource_status ==
                           request_owner::kStatusRequestCapacityExceeded
                   ? RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_WAIT
                   : RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
      }
    }
  } else {
    if (!pending->second.owner_plan_valid ||
        !pending->second.owner_plan_committed ||
        !rtcore_v04_global384_pending_owner_matches(
            pending->second, dynamic_warp_id, expected_warp_uid,
            warp_id, active_mask) ||
        pending->second.timing_driver_owned != timing_driver_owned ||
        (timing_driver_owned
             ? !rtcore_validate_v04_global384_timing_owner_plan(
                   owner_hw_sid, &pending->second.owner_plan)
             : !rtcore_v04_global384_owner_plan_is_live(
                   rtcore_v04_functional_only_allocator(owner_hw_sid),
                   pending->second.owner_plan))) {
      return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
    }
    resource_plan = pending->second.owner_plan;
  }

  rtcore::v04::pre_submit_publication::first_submit_bind_result_v0 begin = {};
  const rtcore::v04::pre_submit_publication::status_kind begin_status =
      rtcore::v04::pre_submit_publication::shared_bridge()
          .begin_or_poll_first_submit_live_bind(material.request, &begin);
  if (begin_status != rtcore::v04::pre_submit_publication::kStatusOk) {
    if (!rtcore_v04_global384_rollback_pending_timing_owner(
            owner_hw_sid, expected_warp_uid, warp_id, active_mask,
            resource_plan, timing_driver_owned)) {
      abort();
    }
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  if (create_pending) {
    if (!timing_driver_owned) {
      request_owner::allocator_state_v0 &allocator =
          rtcore_v04_functional_only_allocator(owner_hw_sid);
      if (request_owner::commit_new_warp(&allocator, resource_plan) !=
          request_owner::kStatusOk) {
        return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
      }
    }
    rtcore_v04_global384_pending_bind_owner owner;
    owner.dynamic_warp_id = dynamic_warp_id;
    owner.reserved_warp_uid = expected_warp_uid;
    owner.warp_id = warp_id;
    owner.active_mask = active_mask;
    owner.owner_plan_valid = true;
    owner.owner_plan_committed = true;
    owner.timing_driver_owned = timing_driver_owned;
    owner.owner_plan = resource_plan;
    g_rtcore_v04_global384_pending_bind_by_sm[owner_hw_sid] = owner;
  }
  if (begin.wait_required) {
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_FIRST_SUBMIT_BIND "
           "owner_hw_sid=%u dynamic_warp_id=%u warp_id=%u "
           "active_mask=0x%08x issue_cycle=%llu resource_plan=prepared "
           "bind_started=%u preaccept_pending=%llu outstanding=%llu "
           "result=wait\n",
           owner_hw_sid, dynamic_warp_id, warp_id, active_mask,
           issue_cycle, begin.bind_started,
           static_cast<unsigned long long>(begin.preaccept_pending),
           static_cast<unsigned long long>(begin.outstanding_transactions));
    fflush(stdout);
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_WAIT;
  }

  unsigned resident_generation = 0;
  const char *resident_shell_failure = "accepted";
  if (!rtcore_prepare_v04_global384_resident_warp_shell(
          owner_hw_sid, expected_warp_uid, warp_id, active_mask,
          instruction->uid(), &resource_plan, timing_driver_owned,
          &resident_generation, &resident_shell_failure)) {
    fprintf(stderr,
            "GPGPU-Sim "
            "RTCORE_V04_GLOBAL384_FIRST_SUBMIT_BIND_DETAIL_FAULT "
            "phase=resident_shell owner_hw_sid=%u dynamic_warp_id=%u "
            "warp_uid=%u warp_id=%u active_mask=0x%08x "
            "owner_resident_occupancy=%u resident_capacity=%u reason=%s\n",
            owner_hw_sid, dynamic_warp_id, expected_warp_uid, warp_id,
            active_mask, resident_occupancy,
            request_owner::kResidentWarpCapacity, resident_shell_failure);
    fflush(stderr);
    if (!rtcore_v04_global384_rollback_pending_timing_owner(
            owner_hw_sid, expected_warp_uid, warp_id, active_mask,
            resource_plan, timing_driver_owned)) {
      abort();
    }
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  rtcore::v04::pre_submit_publication::first_submit_bind_result_v0 commit = {};
  const rtcore::v04::pre_submit_publication::status_kind commit_status =
      rtcore::v04::pre_submit_publication::shared_bridge()
          .commit_first_submit_live_bind(begin.ticket,
                                         resident_generation, &commit);
  if (commit_status != rtcore::v04::pre_submit_publication::kStatusOk ||
      commit.wait_required || !commit.live_bound ||
      commit.resident_warp_generation != resident_generation) {
    if (!rtcore_v04_global384_rollback_pending_timing_owner(
            owner_hw_sid, expected_warp_uid, warp_id, active_mask,
            resource_plan, timing_driver_owned)) {
      abort();
    }
    return RTCORE_V04_FIRST_SUBMIT_LIVE_BIND_FAULT;
  }
  printf("GPGPU-Sim RTCORE_V04_GLOBAL384_FIRST_SUBMIT_BIND "
         "owner_hw_sid=%u dynamic_warp_id=%u warp_uid=%u warp_id=%u "
         "active_mask=0x%08x issue_cycle=%llu resource_plan=prepared "
         "resident_generation=%u exact_ranges=validated "
         "result=live_ready\n",
         owner_hw_sid, dynamic_warp_id, expected_warp_uid, warp_id,
         active_mask, issue_cycle, resident_generation);
  fflush(stdout);
  const rtcore_v04_first_submit_live_bind_preissue_status acquire_status =
      rtcore_service_v04_global384_initial_handoff_acquire_before_issue(
      owner_hw_sid, dynamic_warp_id, expected_warp_uid, warp_id, active_mask,
      resident_generation, material.request.allocation_ranges.handoff_base,
      material.request.handoff_lane_stride_bytes, lane_request_ids,
      issue_cycle);
  return rtcore_v04_global384_advance_private_init_after_handoff(
      acquire_status, instruction, lane_threads, owner_hw_sid,
      dynamic_warp_id, expected_warp_uid, warp_id, active_mask,
      resident_generation, material, issue_cycle);
}

static bool
rtcore_validate_v04_global384_first_submit_live_bind_internal(
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned dynamic_warp_id, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask) {
  bool global384 = false;
  if (!rtcore_v04_global384_profile_selected(&global384)) return false;
  if (!global384) return true;
  rtcore_v04_global384_bind_material material;
  if (!rtcore_v04_make_global384_bind_material(
          instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
          warp_id, active_mask, &material)) {
    return false;
  }
  unsigned current_warp_uid = 0;
  unsigned current_active_mask = 0;
  unsigned resident_generation = 0;
  unsigned resident_occupancy = 0;
  if (!rtcore_query_resident_rt_warp_record(
          owner_hw_sid, warp_id, &current_warp_uid,
          &current_active_mask, &resident_generation,
          &resident_occupancy) || current_warp_uid != warp_uid ||
      current_active_mask != active_mask || resident_occupancy == 0 ||
      !rtcore_validate_v04_global384_resident_warp_shell(
          owner_hw_sid, warp_uid, warp_id, active_mask,
          instruction->uid(), resident_generation)) {
    return false;
  }
  rtcore::v04::pre_submit_publication::first_submit_bind_result_v0 result = {};
  return rtcore::v04::pre_submit_publication::shared_bridge()
                 .validate_first_submit_live_bind(
                     material.request, resident_generation, &result) ==
             rtcore::v04::pre_submit_publication::kStatusOk &&
         result.live_bound && !result.wait_required;
}

static bool rtcore_validate_v04_global384_resubmit_live_internal(
    const ptx_instruction *instruction,
    ptx_thread_info *const *lane_threads, unsigned owner_hw_sid,
    unsigned dynamic_warp_id, unsigned previous_warp_uid,
    unsigned warp_uid, unsigned warp_id, unsigned previous_active_mask,
    unsigned active_mask, unsigned resident_warp_generation) {
  bool global384 = false;
  if (!rtcore_v04_global384_profile_selected(&global384)) return false;
  if (!global384) return true;
  if (!rtcore_v04_root_node_input_gate_active() || instruction == NULL ||
      lane_threads == NULL || previous_warp_uid == 0 || warp_uid == 0 ||
      previous_warp_uid == warp_uid || previous_active_mask == 0 ||
      active_mask == 0 || (active_mask & ~previous_active_mask) != 0 ||
      resident_warp_generation == 0) {
    return false;
  }

  for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
    if ((active_mask & (1u << lane)) == 0) continue;
    if (lane_threads[lane] == NULL) return false;
  }

  rtcore_v04_global384_bind_material material;
  if (!rtcore_v04_make_global384_bind_material(
          instruction, lane_threads, owner_hw_sid, dynamic_warp_id,
          warp_id, active_mask, &material)) {
    return false;
  }
  rtcore::v04::pre_submit_publication::resubmit_live_validation_result_v0
      result = {};
  const rtcore::v04::pre_submit_publication::status_kind status =
      rtcore::v04::pre_submit_publication::shared_bridge()
          .validate_resubmit_live_subset(
              material.request, previous_active_mask,
              resident_warp_generation, &result);
  const bool valid =
      status == rtcore::v04::pre_submit_publication::kStatusOk &&
      result.live_bound && result.public_active_mask != 0 &&
      result.previous_active_mask == previous_active_mask &&
      result.selected_active_mask == active_mask &&
      result.resident_warp_generation == resident_warp_generation &&
      result.identity.owner.owner_hw_sid == owner_hw_sid &&
      result.identity.owner.dynamic_warp_id == dynamic_warp_id &&
      result.identity.owner.warp_id == warp_id;
  printf("GPGPU-Sim RTCORE_V04_GLOBAL384_RESUBMIT_LIVE_VALIDATION "
         "owner_hw_sid=%u dynamic_warp_id=%u previous_warp_uid=%u "
         "warp_uid=%u warp_id=%u public_active_mask=0x%08x "
         "previous_active_mask=0x%08x next_active_mask=0x%08x "
         "resident_generation=%u allocation_record_id=%llu "
         "launch_generation=%u window_generation=%u "
         "bridge_status=%s authority_status=%s registry_status=%s "
         "functional_reads_started=0 memory_traffic_started=0 result=%s\n",
         owner_hw_sid, dynamic_warp_id, previous_warp_uid, warp_uid,
         warp_id, result.public_active_mask, previous_active_mask,
         active_mask, resident_warp_generation,
         static_cast<unsigned long long>(result.identity.record_id),
         result.identity.launch_allocation_generation,
         result.identity.window_generation,
         rtcore::v04::pre_submit_publication::status_name(status),
         rtcore::v04::allocation_identity::status_name(
             result.authority_status),
         rtcore::v04::address_range_registry::status_name(
             result.registry_status),
         valid ? "validated" : "fault");
  fflush(stdout);
  return valid;
}

enum rtcore_traversal_source_provider {
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_LEGACY_FUNCTIONAL = 0,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_STUB = 1,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_REJECT = 2,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_EMPTY = 3,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_DEFAULT_MISS = 4,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_STATS_MISS = 5,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_LANE_STATS_MISS = 6,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_STUB = 7,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EMPTY = 8,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_DEFAULT_MISS = 9,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_STATS_MISS = 10,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_LANE_STATS_MISS = 11,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EXISTING_TRAVERSAL = 12,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_V04_FUNCTIONAL_ONLY = 13,
  RTCORE_TRAVERSAL_SOURCE_PROVIDER_UNSUPPORTED = 14
};

static const char *rtcore_traversal_source_provider_name(
    rtcore_traversal_source_provider provider) {
  switch (provider) {
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_LEGACY_FUNCTIONAL:
      return "legacy_functional";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_STUB:
      return "rtcore_stub";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_REJECT:
      return "rtcore_reject";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_EMPTY:
      return "rtcore_empty";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_DEFAULT_MISS:
      return "rtcore_default_miss";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_STATS_MISS:
      return "rtcore_stats_miss";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_LANE_STATS_MISS:
      return "rtcore_lane_stats_miss";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_STUB:
      return "rtcore_custom_stub";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EMPTY:
      return "rtcore_custom_empty";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_DEFAULT_MISS:
      return "rtcore_custom_default_miss";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_STATS_MISS:
      return "rtcore_custom_stats_miss";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_LANE_STATS_MISS:
      return "rtcore_custom_lane_stats_miss";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EXISTING_TRAVERSAL:
      return "rtcore_custom_existing_traversal";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_V04_FUNCTIONAL_ONLY:
      return "rtcore_v04_functional_only";
    case RTCORE_TRAVERSAL_SOURCE_PROVIDER_UNSUPPORTED:
    default:
      return "unsupported";
  }
}

static bool rtcore_traversal_source_provider_override_unset(
    const char *value) {
  return value == NULL || value[0] == '\0' || strcmp(value, "0") == 0;
}

static rtcore_traversal_source_provider
rtcore_select_default_traversal_source_provider() {
  const char *policy =
      getenv("VULKAN_SIM_RTCORE_TRAVERSAL_DEFAULT_POLICY");
  if (rtcore_traversal_source_provider_override_unset(policy)) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EXISTING_TRAVERSAL;
  }
  if (strcmp(policy, "legacy") == 0 ||
      strcmp(policy, "legacy_functional") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_LEGACY_FUNCTIONAL;
  }
  if (strcmp(policy, "rtcore_custom_existing_traversal") == 0 ||
      strcmp(policy, "rtcore_backend_existing_traversal") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EXISTING_TRAVERSAL;
  }
  return RTCORE_TRAVERSAL_SOURCE_PROVIDER_UNSUPPORTED;
}

static rtcore_traversal_source_provider
rtcore_select_traversal_source_provider() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_TRAVERSAL_SOURCE_PROVIDER");
  if (rtcore_traversal_source_provider_override_unset(value)) {
    return rtcore_select_default_traversal_source_provider();
  }
  if (strcmp(value, "legacy") == 0 ||
      strcmp(value, "legacy_functional") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_LEGACY_FUNCTIONAL;
  }
  if (strcmp(value, "rtcore_stub") == 0 || strcmp(value, "rtcore") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_STUB;
  }
  if (strcmp(value, "rtcore_reject") == 0 ||
      strcmp(value, "rtcore_supported_reject") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_REJECT;
  }
  if (strcmp(value, "rtcore_empty") == 0 ||
      strcmp(value, "rtcore_accepted_empty") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_EMPTY;
  }
  if (strcmp(value, "rtcore_default_miss") == 0 ||
      strcmp(value, "rtcore_miss") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_DEFAULT_MISS;
  }
  if (strcmp(value, "rtcore_stats_miss") == 0 ||
      strcmp(value, "rtcore_stats_default_miss") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_STATS_MISS;
  }
  if (strcmp(value, "rtcore_lane_stats_miss") == 0 ||
      strcmp(value, "rtcore_per_lane_stats_miss") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_LANE_STATS_MISS;
  }
  if (strcmp(value, "rtcore_custom_stub") == 0 ||
      strcmp(value, "rtcore_backend_stub") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_STUB;
  }
  if (strcmp(value, "rtcore_custom_empty") == 0 ||
      strcmp(value, "rtcore_backend_empty") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EMPTY;
  }
  if (strcmp(value, "rtcore_custom_default_miss") == 0 ||
      strcmp(value, "rtcore_backend_default_miss") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_DEFAULT_MISS;
  }
  if (strcmp(value, "rtcore_custom_stats_miss") == 0 ||
      strcmp(value, "rtcore_backend_stats_miss") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_STATS_MISS;
  }
  if (strcmp(value, "rtcore_custom_lane_stats_miss") == 0 ||
      strcmp(value, "rtcore_backend_lane_stats_miss") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_LANE_STATS_MISS;
  }
  if (strcmp(value, "rtcore_custom_existing_traversal") == 0 ||
      strcmp(value, "rtcore_backend_existing_traversal") == 0) {
    return RTCORE_TRAVERSAL_SOURCE_PROVIDER_RTCORE_CUSTOM_EXISTING_TRAVERSAL;
  }
  return RTCORE_TRAVERSAL_SOURCE_PROVIDER_UNSUPPORTED;
}

