static rtcore_provider_payload_consumption_preflight_record
rtcore_make_provider_payload_consumption_preflight_record(
    const rtcore_provider_facing_registry_payload_shadow
        *registry_payload_shadow) {
  rtcore_provider_payload_consumption_preflight_record preflight;
  preflight.valid = true;
  preflight.default_custom_path =
      rtcore_provider_payload_consumption_default_custom_path();
  preflight.admission_allowed =
      rtcore_registry_payload_consumption_admission_policy_allows(
          "provider-payload-consumption-opt-in-preflight");
  preflight.has_registry_payload_shadow = registry_payload_shadow != NULL;
  preflight.consumption_policy_enabled =
      rtcore_provider_payload_consumption_policy_enabled();
  preflight.evidence_source =
      rtcore_get_provider_payload_consumption_evidence_source();
  preflight.uses_runtime_evidence =
      preflight.evidence_source ==
      RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_EVIDENCE_SOURCE_RUNTIME_SHADOW;
  if (preflight.uses_runtime_evidence) {
    const rtcore_provider_payload_consumption_runtime_evidence_record
        runtime_evidence =
            rtcore_make_provider_payload_consumption_runtime_evidence_record(
                registry_payload_shadow, false);
    preflight.parity_evidence_available =
        runtime_evidence.runtime_parity_evidence_available;
    preflight.resource_evidence_available =
        runtime_evidence.runtime_resource_evidence_available;
  } else {
    preflight.parity_evidence_available =
        rtcore_provider_payload_consumption_parity_evidence_available();
    preflight.resource_evidence_available =
        rtcore_provider_payload_consumption_resource_evidence_available();
  }

  if (registry_payload_shadow != NULL && registry_payload_shadow->valid) {
    preflight.observed_valid_shadow = true;
    preflight.field_coverage_complete =
        rtcore_provider_payload_shadow_has_complete_field_coverage(
            registry_payload_shadow);
    const bool registry_fields_owned_with_lifetime =
        registry_payload_shadow
            ->provider_consumed_input_fields_all_owned_with_lifetime;
    const bool registry_runtime_lifetime_ready =
        registry_payload_shadow->driver_runtime_context_window_lifetime_ready;
    const bool registry_provider_payload_runtime_lifetime_ready =
        registry_payload_shadow->provider_payload_runtime_lifetime_ready;
    preflight.owner_lifetime_ok =
        registry_fields_owned_with_lifetime &&
        registry_runtime_lifetime_ready &&
        registry_provider_payload_runtime_lifetime_ready;
  }

  preflight.provider_payload_consumption_preflight_passed =
      preflight.default_custom_path && preflight.admission_allowed &&
      preflight.consumption_policy_enabled &&
      preflight.observed_valid_shadow && preflight.field_coverage_complete &&
      preflight.owner_lifetime_ok && preflight.parity_evidence_available &&
      preflight.resource_evidence_available;

  if (!preflight.default_custom_path) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_NOT_DEFAULT_CUSTOM_PATH;
  } else if (!preflight.admission_allowed) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_ADMISSION_DISABLED;
  } else if (!preflight.consumption_policy_enabled) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_CONSUMPTION_POLICY_DISABLED;
  } else if (!preflight.observed_valid_shadow) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_REGISTRY_SHADOW_MISSING;
  } else if (!preflight.field_coverage_complete) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_FIELD_COVERAGE_INCOMPLETE;
  } else if (!preflight.owner_lifetime_ok) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_OWNER_LIFETIME_BLOCKED;
  } else if (!preflight.parity_evidence_available) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_PARITY_EVIDENCE_MISSING;
  } else if (!preflight.resource_evidence_available) {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_RESOURCE_EVIDENCE_MISSING;
  } else {
    preflight.fail_reason =
        RTCORE_PROVIDER_PAYLOAD_CONSUMPTION_PREFLIGHT_NONE;
  }
  return preflight;
}

struct rtcore_compiler_driver_runtime_consumption_readiness_record {
  rtcore_compiler_driver_runtime_consumption_readiness_record()
      : valid(false),
        provider(RTCORE_TRAVERSAL_SOURCE_PROVIDER_UNSUPPORTED),
        context_ptr(0),
        handoff_window_base(0),
        lane_slot_index(0),
        compiler_publication_ready(false),
        driver_runtime_allocation_ready(false),
        driver_runtime_context_window_lifetime_ready(false),
        context_window_owner_seq_matches_lifetime(false),
        token_lifetime_key_ready(false),
        owner_lifetime_ready(false),
        registry_payload_ready(false),
        provider_policy_ready(false),
        parity_ready(false),
        resource_ready(false),
        provider_preflight_ready(false),
        backend_route_input_ready(false),
        provider_payload_consumption_enabled(false),
        compiler_driver_runtime_consumption_ready(false),
        context_window_owner(RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        allocation_ownership_source(
            RTCORE_DRIVER_RUNTIME_OWNERSHIP_SOURCE_DEFAULT) {}

  bool valid;
  rtcore_traversal_source_provider provider;
  unsigned long long context_ptr;
  unsigned long long handoff_window_base;
  unsigned lane_slot_index;
  ptx_thread_info::rtcore_current_warp_metadata warp_metadata;
  bool compiler_publication_ready;
  bool driver_runtime_allocation_ready;
  bool driver_runtime_context_window_lifetime_ready;
  bool context_window_owner_seq_matches_lifetime;
  bool token_lifetime_key_ready;
  bool owner_lifetime_ready;
  bool registry_payload_ready;
  bool provider_policy_ready;
  bool parity_ready;
  bool resource_ready;
  bool provider_preflight_ready;
  bool backend_route_input_ready;
  bool provider_payload_consumption_enabled;
  bool compiler_driver_runtime_consumption_ready;
  rtcore_decoded_input_field_owner_class context_window_owner;
  const char *allocation_ownership_source;
};

static bool
rtcore_provider_payload_shadow_compiler_publication_ready(
    const rtcore_provider_facing_registry_payload_shadow *shadow) {
  if (shadow == NULL || !shadow->valid) {
    return false;
  }
  return shadow->has_ray_origin_direction_tmin_tmax &&
         shadow->ray_origin_direction_tmin_tmax_owner ==
             RTCORE_DECODED_INPUT_OWNER_COMPILER_DRIVER_PUBLICATION &&
         shadow->has_ray_flags_cull_mask &&
         shadow->ray_flags_cull_mask_owner ==
             RTCORE_DECODED_INPUT_OWNER_COMPILER_DRIVER_PUBLICATION &&
         shadow->has_launch_context_input &&
         shadow->launch_context_input_owner ==
             RTCORE_DECODED_INPUT_OWNER_COMPILER_DRIVER_PUBLICATION;
}

static bool rtcore_provider_payload_shadow_proxy_fields_ready(
    const rtcore_provider_facing_registry_payload_shadow *shadow) {
  if (shadow == NULL || !shadow->valid) {
    return false;
  }
  return shadow->has_traversable_root_proxy &&
         shadow->traversable_root_proxy_owner ==
             RTCORE_DECODED_INPUT_OWNER_SIMULATOR_PROXY &&
         shadow->has_bvh_format_profile &&
         shadow->bvh_format_profile_owner ==
             RTCORE_DECODED_INPUT_OWNER_SIMULATOR_PROXY;
}

static rtcore_compiler_driver_runtime_consumption_readiness_record
rtcore_make_compiler_driver_runtime_consumption_readiness_record(
    const rtcore_traversal_work_descriptor &descriptor) {
  rtcore_compiler_driver_runtime_consumption_readiness_record record;
  record.provider = descriptor.provider;
  record.context_ptr = descriptor.context_ptr;
  record.handoff_window_base = descriptor.handoff_window_base;
  record.lane_slot_index = descriptor.lane_slot_index;
  record.warp_metadata = descriptor.warp_metadata;
  record.provider_payload_consumption_enabled =
      descriptor.provider_payload_consumption_enabled;

  const rtcore_provider_payload_consumption_preflight_record preflight =
      rtcore_make_provider_payload_consumption_preflight_record(
          descriptor.registry_payload_shadow);
  if (!preflight.default_custom_path) {
    return record;
  }

  const rtcore_runtime_context_window_allocation_record allocation_record =
      rtcore_make_runtime_context_window_allocation_record(
          descriptor.context_ptr, descriptor.handoff_window_base,
          descriptor.lane_slot_index);
  const bool allocation_source_is_bootstrap =
      strcmp(allocation_record.ownership_source,
             RTCORE_DRIVER_RUNTIME_OWNERSHIP_SOURCE_BOOTSTRAP_COMPAT) == 0;
  const bool allocation_source_is_legacy =
      strcmp(allocation_record.ownership_source,
             RTCORE_DRIVER_RUNTIME_OWNERSHIP_SOURCE_LEGACY_OPT_OUT) == 0;

  record.valid = true;
  record.context_window_owner = RTCORE_DECODED_INPUT_OWNER_DRIVER_RUNTIME;
  record.allocation_ownership_source = allocation_record.ownership_source;
  record.compiler_publication_ready =
      rtcore_provider_payload_shadow_compiler_publication_ready(
          descriptor.registry_payload_shadow) &&
      rtcore_provider_payload_shadow_proxy_fields_ready(
          descriptor.registry_payload_shadow);
  record.driver_runtime_allocation_ready =
      allocation_record.enabled && allocation_record.valid &&
      !allocation_source_is_bootstrap && !allocation_source_is_legacy;
  if (descriptor.registry_payload_shadow != NULL &&
      descriptor.registry_payload_shadow->valid) {
    record.driver_runtime_context_window_lifetime_ready =
        descriptor.registry_payload_shadow
            ->driver_runtime_context_window_lifetime_ready;
    record.context_window_owner_seq_matches_lifetime =
        descriptor.registry_payload_shadow
            ->context_window_owner_seq_matches_lifetime;
    record.token_lifetime_key_ready =
        descriptor.registry_payload_shadow->token_lifetime_key_ready;
  }
  record.owner_lifetime_ready = preflight.owner_lifetime_ok;
  record.registry_payload_ready = preflight.observed_valid_shadow &&
                                  preflight.field_coverage_complete &&
                                  preflight.admission_allowed;
  record.provider_policy_ready = preflight.consumption_policy_enabled;
  record.parity_ready = preflight.parity_evidence_available;
  record.resource_ready = preflight.resource_evidence_available;
  record.provider_preflight_ready =
      preflight.provider_payload_consumption_preflight_passed;
  record.backend_route_input_ready =
      descriptor.provider_payload_consumption_enabled &&
      descriptor.has_provider_payload_consumed_input &&
      descriptor.provider_payload_consumed_input.valid;
  record.compiler_driver_runtime_consumption_ready =
      record.valid && record.compiler_publication_ready &&
      record.driver_runtime_allocation_ready &&
      record.driver_runtime_context_window_lifetime_ready &&
      record.owner_lifetime_ready &&
      record.registry_payload_ready && record.provider_policy_ready &&
      record.parity_ready && record.resource_ready &&
      record.provider_preflight_ready && record.backend_route_input_ready;
  return record;
}

static void
rtcore_log_compiler_driver_runtime_consumption_readiness_record(
    const rtcore_traversal_work_descriptor &descriptor) {
  const rtcore_compiler_driver_runtime_consumption_readiness_record record =
      rtcore_make_compiler_driver_runtime_consumption_readiness_record(
          descriptor);
  if (!record.valid) {
    return;
  }

  printf("GPGPU-Sim PTX: RT_SUBMIT "
         "compiler-driver-runtime-consumption-readiness=1, "
         "provider=%s, context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, warp_uid=%u, active_mask=0x%08x, "
         "compiler_publication_ready=%u, "
         "driver_runtime_allocation_ready=%u, "
         "driver_runtime_context_window_lifetime_ready=%u, "
         "context_window_owner_seq_matches_lifetime=%u, "
         "token_lifetime_key_ready=%u, "
         "context_window_owner=%s, allocation_ownership_source=%s, "
         "owner_lifetime_ready=%u, registry_payload_ready=%u, "
         "provider_policy_ready=%u, parity_ready=%u, resource_ready=%u, "
         "provider_preflight_ready=%u, backend_route_input_ready=%u, "
         "provider_payload_consumption_enabled=%u, "
         "compiler_driver_runtime_consumption_ready=%u, "
         "legacy_switchable=1, existing_traversal_backend_reused=1, "
         "claims_new_hardware_bvh_engine=0, "
         "compiler_driver_runtime_consumption_readiness_consumes_traversal_behavior=0\n",
         rtcore_traversal_source_provider_name(record.provider),
         record.context_ptr, record.handoff_window_base,
         record.lane_slot_index, record.warp_metadata.warp_uid,
         record.warp_metadata.active_mask,
         record.compiler_publication_ready ? 1 : 0,
         record.driver_runtime_allocation_ready ? 1 : 0,
         record.driver_runtime_context_window_lifetime_ready ? 1 : 0,
         record.context_window_owner_seq_matches_lifetime ? 1 : 0,
         record.token_lifetime_key_ready ? 1 : 0,
         rtcore_decoded_input_field_owner_class_name(
             record.context_window_owner),
         record.allocation_ownership_source,
         record.owner_lifetime_ready ? 1 : 0,
         record.registry_payload_ready ? 1 : 0,
         record.provider_policy_ready ? 1 : 0, record.parity_ready ? 1 : 0,
         record.resource_ready ? 1 : 0,
         record.provider_preflight_ready ? 1 : 0,
         record.backend_route_input_ready ? 1 : 0,
         record.provider_payload_consumption_enabled ? 1 : 0,
         record.compiler_driver_runtime_consumption_ready ? 1 : 0);
  fflush(stdout);
}

static rtcore_provider_decoded_input_observation
rtcore_make_provider_decoded_input_observation(
    const rtcore_provider_facing_registry_payload_shadow
        *registry_payload_shadow) {
  rtcore_provider_decoded_input_observation observation;
  if (registry_payload_shadow == NULL || !registry_payload_shadow->valid) {
    return observation;
  }

  observation.valid = true;
  observation.from_registry_payload_shadow = true;
  observation.has_ray_origin_direction_tmin_tmax =
      registry_payload_shadow->has_ray_origin_direction_tmin_tmax;
  observation.ray_origin_direction_tmin_tmax_owner =
      registry_payload_shadow->ray_origin_direction_tmin_tmax_owner;
  observation.has_ray_flags_cull_mask =
      registry_payload_shadow->has_ray_flags_cull_mask;
  observation.ray_flags_cull_mask_owner =
      registry_payload_shadow->ray_flags_cull_mask_owner;
  observation.ray_origin = registry_payload_shadow->ray_origin;
  observation.ray_direction = registry_payload_shadow->ray_direction;
  observation.ray_tmin = registry_payload_shadow->ray_tmin;
  observation.ray_tmax = registry_payload_shadow->ray_tmax;
  observation.ray_flags = registry_payload_shadow->ray_flags;
  observation.cull_mask = registry_payload_shadow->cull_mask;
  observation.has_launch_context_input =
      registry_payload_shadow->has_launch_context_input;
  observation.launch_context_input_owner =
      registry_payload_shadow->launch_context_input_owner;
  observation.bridge_trace_replay_top_level_as =
      registry_payload_shadow->bridge_trace_replay_top_level_as;
  observation.sbt_record_offset = registry_payload_shadow->sbt_record_offset;
  observation.sbt_record_stride = registry_payload_shadow->sbt_record_stride;
  observation.miss_index = registry_payload_shadow->miss_index;
  observation.has_traversable_root_proxy =
      registry_payload_shadow->has_traversable_root_proxy;
  observation.traversable_root_proxy_owner =
      registry_payload_shadow->traversable_root_proxy_owner;
  observation.traversable_proxy_id = registry_payload_shadow->traversable_proxy_id;
  observation.root_proxy_id = registry_payload_shadow->root_proxy_id;
  observation.has_bvh_format_profile =
      registry_payload_shadow->has_bvh_format_profile;
  observation.bvh_format_profile_owner =
      registry_payload_shadow->bvh_format_profile_owner;
  observation.bvh_format_version = registry_payload_shadow->bvh_format_version;
  observation.provider_consumed_input_fields_all_owned_with_lifetime =
      registry_payload_shadow
          ->provider_consumed_input_fields_all_owned_with_lifetime;
  observation.provider_payload_runtime_lifetime_ready =
      registry_payload_shadow->provider_payload_runtime_lifetime_ready;
  observation.context_window_owner_seq_matches_lifetime =
      registry_payload_shadow->context_window_owner_seq_matches_lifetime;
  observation.token_lifetime_key_ready =
      registry_payload_shadow->token_lifetime_key_ready;
  observation.provider_payload_consumption_owner_lifetime_blocked =
      !observation.provider_consumed_input_fields_all_owned_with_lifetime;
  return observation;
}

static bool rtcore_provider_payload_consumption_effective_enabled(
    const rtcore_provider_facing_registry_payload_shadow
        *registry_payload_shadow) {
  const rtcore_provider_payload_consumption_preflight_record preflight =
      rtcore_make_provider_payload_consumption_preflight_record(
          registry_payload_shadow);
  return preflight.provider_payload_consumption_preflight_passed;
}

