static void
rtcore_apply_top_level_as_proxy_resolve_adapter_snapshot_to_decoded_snapshot(
    rtcore_decoded_traversal_input_snapshot *decoded_input_snapshot,
    const rtcore_top_level_as_proxy_resolve_adapter_snapshot &snapshot) {
  if (decoded_input_snapshot == NULL || !snapshot.valid) {
    return;
  }
  decoded_input_snapshot->traversable_proxy_id = snapshot.traversable_proxy_id;
  decoded_input_snapshot->root_proxy_id = snapshot.root_proxy_id;
  decoded_input_snapshot->has_traversable_root_proxy = snapshot.has_proxy_token;
  decoded_input_snapshot->traversable_root_proxy_owner =
      snapshot.has_proxy_token ? RTCORE_DECODED_INPUT_OWNER_SIMULATOR_PROXY
                               : RTCORE_DECODED_INPUT_OWNER_FORBIDDEN;
  decoded_input_snapshot->bvh_format_version = snapshot.bvh_format_version;
  decoded_input_snapshot->has_bvh_format_version =
      snapshot.has_bvh_format_profile;
  decoded_input_snapshot->bvh_format_profile_owner =
      snapshot.has_bvh_format_profile
          ? RTCORE_DECODED_INPUT_OWNER_SIMULATOR_PROXY
          : RTCORE_DECODED_INPUT_OWNER_FORBIDDEN;
}

struct rtcore_default_compiler_driver_publication_route_record {
  rtcore_default_compiler_driver_publication_route_record()
      : publication_enabled(false),
        valid(false),
        context_ptr(0),
        handoff_window_base(0),
        lane_slot_index(0),
        route_source("disabled"),
        compiler_fields_source("unavailable"),
        runtime_context_window_source("unavailable"),
        proxy_fields_source("unavailable"),
        proxy_delegation_source("unavailable"),
        top_level_as_proxy_resolve_adapter_source("unavailable"),
        proxy_token_source("unavailable"),
        source_publication_seq(0),
        source_owner_tuple_match(false),
        has_source_context_window_key(false),
        source_context_window_match(false),
        has_ray_origin_direction_tmin_tmax(false),
        has_ray_flags_cull_mask(false),
        has_launch_context_input(false),
        context_window_owner_seq_owner(RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        ray_origin_direction_tmin_tmax_owner(
            RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        ray_flags_cull_mask_owner(RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        launch_context_input_owner(RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        traversable_root_proxy_owner(RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        bvh_format_profile_owner(RTCORE_DECODED_INPUT_OWNER_FORBIDDEN),
        compiler_fields_complete(false),
        runtime_context_window_complete(false),
        proxy_fields_complete(false),
        proxy_delegation_gate_required(false),
        proxy_delegation_gate_passed(false),
        top_level_as_proxy_resolve_adapter_gate_passed(false),
        proxy_fields_actual_abi_evidence(false),
        provider_consumption_policy_enabled(false),
        provider_consumption_default_disabled(true) {}

  bool publication_enabled;
  bool valid;
  unsigned long long context_ptr;
  unsigned long long handoff_window_base;
  unsigned lane_slot_index;
  const char *route_source;
  const char *compiler_fields_source;
  const char *runtime_context_window_source;
  const char *proxy_fields_source;
  const char *proxy_delegation_source;
  const char *top_level_as_proxy_resolve_adapter_source;
  const char *proxy_token_source;
  unsigned long long source_publication_seq;
  bool source_owner_tuple_match;
  bool has_source_context_window_key;
  bool source_context_window_match;
  bool has_ray_origin_direction_tmin_tmax;
  bool has_ray_flags_cull_mask;
  bool has_launch_context_input;
  rtcore_decoded_input_field_owner_class context_window_owner_seq_owner;
  rtcore_decoded_input_field_owner_class ray_origin_direction_tmin_tmax_owner;
  rtcore_decoded_input_field_owner_class ray_flags_cull_mask_owner;
  rtcore_decoded_input_field_owner_class launch_context_input_owner;
  rtcore_decoded_input_field_owner_class traversable_root_proxy_owner;
  rtcore_decoded_input_field_owner_class bvh_format_profile_owner;
  bool compiler_fields_complete;
  bool runtime_context_window_complete;
  bool proxy_fields_complete;
  bool proxy_delegation_gate_required;
  bool proxy_delegation_gate_passed;
  bool top_level_as_proxy_resolve_adapter_gate_passed;
  bool proxy_fields_actual_abi_evidence;
  bool provider_consumption_policy_enabled;
  bool provider_consumption_default_disabled;
};

static rtcore_default_compiler_driver_publication_route_record
rtcore_make_default_compiler_driver_publication_route_record(
    const rtcore_launch_context_input_publication_record
        &launch_context_input_publication_record,
    const rtcore_decoded_traversal_input_snapshot &decoded_input_snapshot) {
  rtcore_default_compiler_driver_publication_route_record record;
  record.publication_enabled =
      rtcore_compiler_driver_publication_source_enabled() &&
      launch_context_input_publication_record.publication_enabled;
  record.context_ptr = launch_context_input_publication_record.context_ptr;
  record.handoff_window_base =
      launch_context_input_publication_record.handoff_window_base;
  record.lane_slot_index =
      launch_context_input_publication_record.lane_slot_index;
  record.route_source = record.publication_enabled
                            ? launch_context_input_publication_record.source
                            : "disabled";
  record.source_publication_seq =
      launch_context_input_publication_record.source_publication_seq;
  record.source_owner_tuple_match =
      launch_context_input_publication_record.source_owner_tuple_match;
  record.has_source_context_window_key =
      launch_context_input_publication_record.has_source_context_window_key;
  record.source_context_window_match =
      launch_context_input_publication_record.source_context_window_match;
  record.has_ray_origin_direction_tmin_tmax =
      launch_context_input_publication_record.has_ray_origin_direction_tmin_tmax;
  record.has_ray_flags_cull_mask =
      launch_context_input_publication_record.has_ray_flags_cull_mask;
  record.has_launch_context_input =
      launch_context_input_publication_record.has_launch_context_input;
  record.context_window_owner_seq_owner =
      decoded_input_snapshot.context_window_owner_seq_owner;
  record.ray_origin_direction_tmin_tmax_owner =
      decoded_input_snapshot.ray_origin_direction_tmin_tmax_owner;
  record.ray_flags_cull_mask_owner =
      decoded_input_snapshot.ray_flags_cull_mask_owner;
  record.launch_context_input_owner =
      decoded_input_snapshot.launch_context_input_owner;
  record.traversable_root_proxy_owner =
      decoded_input_snapshot.traversable_root_proxy_owner;
  record.bvh_format_profile_owner =
      decoded_input_snapshot.bvh_format_profile_owner;
  record.provider_consumption_policy_enabled =
      rtcore_provider_payload_consumption_policy_enabled();
  record.provider_consumption_default_disabled =
      !record.provider_consumption_policy_enabled;

  if (!record.publication_enabled) {
    return record;
  }

  const bool compiler_driver_source =
      strcmp(record.route_source, "context_abi_byte_image") == 0;
  record.compiler_fields_source =
      compiler_driver_source ? "context_abi_byte_image"
                             : "unexpected_source";
  record.runtime_context_window_source = "driver_runtime";
  record.proxy_delegation_source = rtcore_proxy_delegation_source_label();
  record.top_level_as_proxy_resolve_adapter_source =
      rtcore_top_level_as_proxy_resolve_adapter_source_label();
  record.proxy_token_source = rtcore_top_level_as_proxy_token_source_label();
  record.proxy_delegation_gate_required = true;
  record.compiler_fields_complete =
      compiler_driver_source &&
      decoded_input_snapshot.has_ray_origin_direction_tmin_tmax &&
      decoded_input_snapshot.ray_origin_direction_tmin_tmax_owner ==
          RTCORE_DECODED_INPUT_OWNER_COMPILER_DRIVER_PUBLICATION &&
      decoded_input_snapshot.has_ray_flags_cull_mask &&
      decoded_input_snapshot.ray_flags_cull_mask_owner ==
          RTCORE_DECODED_INPUT_OWNER_COMPILER_DRIVER_PUBLICATION &&
      decoded_input_snapshot.has_launch_context_input &&
      decoded_input_snapshot.launch_context_input_owner ==
          RTCORE_DECODED_INPUT_OWNER_COMPILER_DRIVER_PUBLICATION &&
      launch_context_input_publication_record.valid &&
      launch_context_input_publication_record.source_owner_tuple_match &&
      launch_context_input_publication_record.has_source_context_window_key &&
      launch_context_input_publication_record.source_context_window_match;
  record.runtime_context_window_complete =
      decoded_input_snapshot.valid &&
      decoded_input_snapshot.has_context_window_owner_seq &&
      decoded_input_snapshot.context_window_owner_seq_owner ==
          RTCORE_DECODED_INPUT_OWNER_DRIVER_RUNTIME &&
      decoded_input_snapshot.context_window_owner_seq.valid &&
      decoded_input_snapshot.context_window_owner_seq.context_ptr ==
          launch_context_input_publication_record.context_ptr &&
      decoded_input_snapshot.context_window_owner_seq.handoff_window_base ==
          launch_context_input_publication_record.handoff_window_base &&
      decoded_input_snapshot.context_window_owner_seq.lane_slot_index ==
          launch_context_input_publication_record.lane_slot_index;
  record.proxy_delegation_gate_passed =
      rtcore_proxy_delegation_gate_passed_for_proxy_fields(
          decoded_input_snapshot.has_traversable_root_proxy,
          decoded_input_snapshot.traversable_root_proxy_owner,
          decoded_input_snapshot.has_bvh_format_version,
          decoded_input_snapshot.bvh_format_profile_owner);
  record.proxy_fields_actual_abi_evidence = rtcore_actual_producer_root_descriptor_fields_ready(
          decoded_input_snapshot.has_traversable_root_proxy,
          decoded_input_snapshot.traversable_root_proxy_owner,
          decoded_input_snapshot.has_bvh_format_version,
          decoded_input_snapshot.bvh_format_profile_owner);
  record.proxy_fields_source =
      record.proxy_fields_actual_abi_evidence
          ? rtcore_backend_root_descriptor_selected_source_label(true)
          : "simulator_proxy";
  record.proxy_fields_complete =
      record.proxy_delegation_gate_passed ||
      record.proxy_fields_actual_abi_evidence;
  record.top_level_as_proxy_resolve_adapter_gate_passed =
      record.proxy_delegation_gate_passed && record.has_launch_context_input;
  record.valid = record.compiler_fields_complete &&
                 record.runtime_context_window_complete &&
                 (record.proxy_delegation_gate_passed || record.proxy_fields_actual_abi_evidence);
  return record;
}

static bool
rtcore_default_compiler_driver_publication_route_record_is_complete(
    const rtcore_default_compiler_driver_publication_route_record &record) {
  return !record.publication_enabled || record.valid;
}

static void rtcore_log_default_compiler_driver_publication_route_record(
    const ptx_instruction *pI,
    const rtcore_default_compiler_driver_publication_route_record &record) {
  if (!record.publication_enabled) {
    return;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT "
         "default-compiler-driver-publication-route (%s:%u), "
         "default_publication_route=1, valid=%u, "
         "route_source=%s, compiler_fields_source=%s, "
         "runtime_context_window_source=%s, proxy_fields_source=%s, "
         "proxy_delegation_source=%s, proxy_delegation_gate_required=%u, "
         "proxy_delegation_gate_passed=%u, "
         "top_level_as_proxy_resolve_adapter_source=%s, "
         "proxy_token_source=%s, "
         "top_level_as_proxy_resolve_adapter_gate_passed=%u, "
         "actual_abi_evidence_for_proxy_fields=%u, "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, source_publication_seq=%llu, "
         "source_owner_tuple_match=%u, has_source_context_window_key=%u, "
         "source_context_window_match=%u, "
         "has_ray_origin_direction_tmin_tmax=%u, "
         "has_ray_flags_cull_mask=%u, has_launch_context_input=%u, "
         "context_window_owner_seq_owner=%s, "
         "ray_origin_direction_tmin_tmax_owner=%s, "
         "ray_flags_cull_mask_owner=%s, launch_context_input_owner=%s, "
         "traversable_root_proxy_owner=%s, bvh_format_profile_owner=%s, "
         "compiler_fields_complete=%u, "
         "runtime_context_window_complete=%u, proxy_fields_complete=%u, "
         "provider_consumption_policy_enabled=%u, "
         "provider_consumption_default_disabled=%u\n",
         pI->source_file(), pI->source_line(), record.valid ? 1 : 0,
         record.route_source, record.compiler_fields_source,
         record.runtime_context_window_source, record.proxy_fields_source,
         record.proxy_delegation_source,
         record.proxy_delegation_gate_required ? 1 : 0,
         record.proxy_delegation_gate_passed ? 1 : 0,
         record.top_level_as_proxy_resolve_adapter_source,
         record.proxy_token_source,
         record.top_level_as_proxy_resolve_adapter_gate_passed ? 1 : 0,
         record.proxy_fields_actual_abi_evidence ? 1 : 0,
         record.context_ptr, record.handoff_window_base,
         record.lane_slot_index, record.source_publication_seq,
         record.source_owner_tuple_match ? 1 : 0,
         record.has_source_context_window_key ? 1 : 0,
         record.source_context_window_match ? 1 : 0,
         record.has_ray_origin_direction_tmin_tmax ? 1 : 0,
         record.has_ray_flags_cull_mask ? 1 : 0,
         record.has_launch_context_input ? 1 : 0,
         rtcore_decoded_input_field_owner_class_name(
             record.context_window_owner_seq_owner),
         rtcore_decoded_input_field_owner_class_name(
             record.ray_origin_direction_tmin_tmax_owner),
         rtcore_decoded_input_field_owner_class_name(
             record.ray_flags_cull_mask_owner),
         rtcore_decoded_input_field_owner_class_name(
             record.launch_context_input_owner),
         rtcore_decoded_input_field_owner_class_name(
             record.traversable_root_proxy_owner),
         rtcore_decoded_input_field_owner_class_name(
             record.bvh_format_profile_owner),
         record.compiler_fields_complete ? 1 : 0,
         record.runtime_context_window_complete ? 1 : 0,
         record.proxy_fields_complete ? 1 : 0,
         record.provider_consumption_policy_enabled ? 1 : 0,
         record.provider_consumption_default_disabled ? 1 : 0);
  fflush(stdout);
}

static bool
rtcore_fail_closed_on_default_compiler_driver_publication_route_record(
    const ptx_instruction *pI,
    const rtcore_default_compiler_driver_publication_route_record &record) {
  if (rtcore_default_compiler_driver_publication_route_record_is_complete(
          record)) {
    return false;
  }
  const bool proxy_delegation_gate_not_ready =
      record.compiler_fields_complete &&
      record.runtime_context_window_complete &&
      !record.proxy_delegation_gate_passed;
  const char *fail_reason =
      proxy_delegation_gate_not_ready
          ? "PROXY_DELEGATION_GATE_NOT_READY"
          : "DEFAULT_COMPILER_DRIVER_PUBLICATION_ROUTE_PARTIAL";
  printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
         "reason=%s, "
         "legacy_reason=DEFAULT_COMPILER_DRIVER_PUBLICATION_ROUTE_PARTIAL, "
         "legacy_partial_marker=LAUNCH_CONTEXT_INPUT_PUBLICATION_PARTIAL, "
         "compiler_publication_negative_default_consumption=1, "
         "proxy_delegation_gate_fail_closed=%u, "
         "before_registry_payload_shadow=1, "
         "before_provider_consumed_input=1, before_backend_input_route=1, "
         "before_traversal_completion=1, before_completion_release=1, "
         "default_publication_route=1, valid=%u, route_source=%s, "
         "compiler_fields_complete=%u, runtime_context_window_complete=%u, "
         "proxy_fields_complete=%u, proxy_delegation_source=%s, "
         "proxy_delegation_gate_required=%u, "
         "proxy_delegation_gate_passed=%u, "
         "top_level_as_proxy_resolve_adapter_source=%s, "
         "proxy_token_source=%s, "
         "top_level_as_proxy_resolve_adapter_gate_passed=%u, "
         "actual_abi_evidence_for_proxy_fields=%u, "
         "provider_consumption_default_disabled=%u, "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, source_publication_seq=%llu, "
         "source_owner_tuple_match=%u, has_source_context_window_key=%u, "
         "source_context_window_match=%u, "
         "has_ray_origin_direction_tmin_tmax=%u, "
         "has_ray_flags_cull_mask=%u, has_launch_context_input=%u\n",
         pI->source_file(), pI->source_line(), fail_reason,
         proxy_delegation_gate_not_ready ? 1 : 0, record.valid ? 1 : 0,
         record.route_source, record.compiler_fields_complete ? 1 : 0,
         record.runtime_context_window_complete ? 1 : 0,
         record.proxy_fields_complete ? 1 : 0, record.proxy_delegation_source,
         record.proxy_delegation_gate_required ? 1 : 0,
         record.proxy_delegation_gate_passed ? 1 : 0,
         record.top_level_as_proxy_resolve_adapter_source,
         record.proxy_token_source,
         record.top_level_as_proxy_resolve_adapter_gate_passed ? 1 : 0,
         record.proxy_fields_actual_abi_evidence ? 1 : 0,
         record.provider_consumption_default_disabled ? 1 : 0,
         record.context_ptr, record.handoff_window_base,
         record.lane_slot_index, record.source_publication_seq,
         record.source_owner_tuple_match ? 1 : 0,
         record.has_source_context_window_key ? 1 : 0,
         record.source_context_window_match ? 1 : 0,
         record.has_ray_origin_direction_tmin_tmax ? 1 : 0,
         record.has_ray_flags_cull_mask ? 1 : 0,
         record.has_launch_context_input ? 1 : 0);
  fflush(stdout);
  return true;
}

static void
rtcore_update_decoded_traversal_input_from_pre_provider_traversal_data_snapshot(
    rtcore_decoded_traversal_input_snapshot *decoded_input_snapshot,
    const rtcore_pre_provider_traversal_data_snapshot
        &pre_provider_traversal_data_snapshot) {
  if (decoded_input_snapshot == NULL ||
      !pre_provider_traversal_data_snapshot.valid) {
    return;
  }

  // Provider-facing source request, work descriptor, and provider bridge
  // payloads remain unchanged; this only publishes input-field availability.
  rtcore_traversal_source_snapshot source_snapshot;
  source_snapshot.has_traversal_data = true;
  source_snapshot.traversal_snapshot =
      pre_provider_traversal_data_snapshot.traversal_snapshot;
  rtcore_update_decoded_traversal_input_ray_proxy_snapshot(
      decoded_input_snapshot, source_snapshot);
  rtcore_update_decoded_traversal_input_flags_mask_proxy_snapshot(
      decoded_input_snapshot, source_snapshot);
  rtcore_update_decoded_traversal_input_launch_context_snapshot(
      decoded_input_snapshot, source_snapshot);
  rtcore_update_decoded_traversal_input_traversable_root_proxy_snapshot(
      decoded_input_snapshot, source_snapshot);
  rtcore_update_decoded_traversal_input_bvh_format_profile_snapshot(
      decoded_input_snapshot, source_snapshot);
}

static void
rtcore_update_decoded_traversal_input_proxy_profile_from_pre_provider_snapshot(
    rtcore_decoded_traversal_input_snapshot *decoded_input_snapshot,
    const rtcore_pre_provider_traversal_data_snapshot
        &pre_provider_traversal_data_snapshot) {
  if (decoded_input_snapshot == NULL ||
      !pre_provider_traversal_data_snapshot.valid) {
    return;
  }

  rtcore_traversal_source_snapshot source_snapshot;
  source_snapshot.has_traversal_data = true;
  source_snapshot.traversal_snapshot =
      pre_provider_traversal_data_snapshot.traversal_snapshot;
  rtcore_update_decoded_traversal_input_traversable_root_proxy_snapshot(
      decoded_input_snapshot, source_snapshot);
  rtcore_update_decoded_traversal_input_bvh_format_profile_snapshot(
      decoded_input_snapshot, source_snapshot);
}

struct rtcore_pre_provider_decoded_input_publication_map {
  rtcore_pre_provider_decoded_input_publication_map()
      : valid(false),
        has_context_window_owner_seq(false),
        has_provider_selection_metadata(false),
        provider(RTCORE_TRAVERSAL_SOURCE_PROVIDER_UNSUPPORTED),
        has_ray_origin_direction_tmin_tmax(false),
        has_ray_flags_cull_mask(false),
        has_launch_context_input(false),
        has_sbt_dispatch_input(false),
        has_pipeline_profile(false),
        has_traversable_root_proxy(false),
        has_bvh_format_profile(false) {}

  bool valid;
  bool has_context_window_owner_seq;
  bool has_provider_selection_metadata;
  rtcore_traversal_source_provider provider;
  bool has_ray_origin_direction_tmin_tmax;
  bool has_ray_flags_cull_mask;
  bool has_launch_context_input;
  bool has_sbt_dispatch_input;
  bool has_pipeline_profile;
  bool has_traversable_root_proxy;
  bool has_bvh_format_profile;
};

static rtcore_pre_provider_decoded_input_publication_map
rtcore_make_pre_provider_decoded_input_publication_map(
    const rtcore_decoded_traversal_input_snapshot &decoded_input_snapshot,
    const rtcore_traversal_source_request &request) {
  rtcore_pre_provider_decoded_input_publication_map publication_map;
  publication_map.has_context_window_owner_seq =
      decoded_input_snapshot.has_context_window_owner_seq;
  publication_map.has_provider_selection_metadata = true;
  publication_map.provider = request.provider;
  publication_map.valid = decoded_input_snapshot.valid &&
                          publication_map.has_context_window_owner_seq &&
                          publication_map.has_provider_selection_metadata;
  publication_map.has_ray_origin_direction_tmin_tmax =
      decoded_input_snapshot.has_ray_origin_direction_tmin_tmax;
  publication_map.has_ray_flags_cull_mask =
      decoded_input_snapshot.has_ray_flags_cull_mask;
  publication_map.has_launch_context_input =
      decoded_input_snapshot.has_launch_context_input;
  publication_map.has_sbt_dispatch_input =
      decoded_input_snapshot.has_sbt_dispatch_input;
  publication_map.has_pipeline_profile =
      decoded_input_snapshot.has_pipeline_profile;
  publication_map.has_traversable_root_proxy =
      decoded_input_snapshot.has_traversable_root_proxy;
  publication_map.has_bvh_format_profile =
      decoded_input_snapshot.has_bvh_format_version;
  return publication_map;
}

static void
rtcore_bind_input_provenance_registry_publication_to_pre_provider_decoded_input_publication_map(
    rtcore_input_provenance_registry_publication_snapshot *publication_snapshot,
    const rtcore_pre_provider_decoded_input_publication_map
        &publication_map) {
  if (publication_snapshot == NULL) {
    return;
  }
  rtcore_input_provenance_registry_entry &entry =
      publication_snapshot->entry;
  entry.valid = publication_map.valid;
  entry.owned_fields.has_ray_origin_direction_tmin_tmax =
      publication_map.has_ray_origin_direction_tmin_tmax;
  entry.owned_fields.has_ray_flags_cull_mask =
      publication_map.has_ray_flags_cull_mask;
  entry.owned_fields.has_launch_context_input =
      publication_map.has_launch_context_input;
  entry.owned_fields.has_sbt_dispatch_input =
      publication_map.has_sbt_dispatch_input;
  entry.owned_fields.has_pipeline_profile =
      publication_map.has_pipeline_profile;
  entry.owned_fields.has_traversable_root_proxy =
      publication_map.has_traversable_root_proxy;
  entry.owned_fields.has_bvh_format_profile =
      publication_map.has_bvh_format_profile;
}

static rtcore_input_provenance_registry_publication_snapshot
rtcore_publish_input_provenance_registry_entry_snapshot_from_pre_provider_decoded_input_publication_map(
    const rtcore_traversal_source_request &request,
    const rtcore_context_window_owner_seq_snapshot &owner_seq_snapshot,
    const rtcore_pre_provider_decoded_input_publication_map
        &publication_map) {
  rtcore_input_provenance_registry_publication_snapshot snapshot =
      rtcore_publish_input_provenance_registry_entry_snapshot(
          request, owner_seq_snapshot);
  rtcore_bind_input_provenance_registry_publication_to_pre_provider_decoded_input_publication_map(
      &snapshot, publication_map);
  return snapshot;
}

static rtcore_input_provenance_registry_publication_snapshot
rtcore_publish_input_provenance_registry_entry_snapshot_from_decoded_input(
    const rtcore_traversal_source_request &request,
    const rtcore_context_window_owner_seq_snapshot &owner_seq_snapshot,
    const rtcore_decoded_traversal_input_snapshot &decoded_input_snapshot) {
  rtcore_pre_provider_decoded_input_publication_map publication_map =
      rtcore_make_pre_provider_decoded_input_publication_map(
          decoded_input_snapshot, request);
  return rtcore_publish_input_provenance_registry_entry_snapshot_from_pre_provider_decoded_input_publication_map(
      request, owner_seq_snapshot, publication_map);
}

