extern "C" rtcore_v04_retire_live_release_status
rtcore_service_v04_global384_retire_live_release(
    unsigned owner_hw_sid, unsigned retire_warp_uid,
    unsigned warp_id, unsigned resident_warp_generation,
    unsigned active_mask, unsigned long long service_cycle) {
  const auto reject = [&](const char *failure) {
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_RETIRE_LIVE_RELEASE "
           "owner_hw_sid=%u retire_warp_uid=%u warp_id=%u "
           "active_mask=0x%08x resident_generation=%u "
           "service_cycle=%llu preflight_status=%s result=fault\n",
           owner_hw_sid, retire_warp_uid, warp_id, active_mask,
           resident_warp_generation, service_cycle, failure);
    fflush(stdout);
    return RTCORE_V04_RETIRE_LIVE_RELEASE_FAULT;
  };
  bool global384 = false;
  if (!rtcore_v04_global384_profile_selected(&global384)) {
    return reject("profile_lookup_failed");
  }
  if (!global384) return RTCORE_V04_RETIRE_LIVE_RELEASE_NOT_APPLICABLE;
  if (!rtcore_v04_root_node_input_gate_active())
    return reject("root_node_input_gate_disabled");
  if (resident_warp_generation == 0)
    return reject("resident_generation_missing");
  if (active_mask == 0) return reject("active_mask_empty");

  std::map<unsigned, rtcore_symbolic_retire_transaction>::const_iterator
      transaction =
          g_rtcore_symbolic_retire_transactions.find(retire_warp_uid);
  if (transaction == g_rtcore_symbolic_retire_transactions.end() ||
      !transaction->second.valid || !transaction->second.claimed ||
      transaction->second.owner_hw_sid != owner_hw_sid ||
      transaction->second.warp_uid != retire_warp_uid ||
      transaction->second.warp_id != warp_id ||
      transaction->second.active_mask != active_mask) {
    return reject("retire_transaction_mismatch");
  }

  rtcore_v04_global384_bind_material material;
  const char *material_failure = "accepted";
  if (!rtcore_v04_make_global384_retire_release_material(
          transaction->second, &material, &material_failure)) {
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_RETIRE_LIVE_RELEASE "
           "owner_hw_sid=%u retire_warp_uid=%u warp_id=%u "
           "active_mask=0x%08x resident_generation=%u "
           "service_cycle=%llu material_status=%s result=fault\n",
           owner_hw_sid, retire_warp_uid, warp_id, active_mask,
           resident_warp_generation, service_cycle, material_failure);
    fflush(stdout);
    return RTCORE_V04_RETIRE_LIVE_RELEASE_FAULT;
  }
  rtcore::v04::pre_submit_publication::retire_live_release_result_v0 result =
      {};
  const rtcore::v04::pre_submit_publication::status_kind status =
      rtcore::v04::pre_submit_publication::shared_bridge()
          .begin_or_poll_retire_live_release(
              material.request, resident_warp_generation, &result);
  if (status != rtcore::v04::pre_submit_publication::kStatusOk) {
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_RETIRE_LIVE_RELEASE "
           "owner_hw_sid=%u dynamic_warp_id=%u retire_warp_uid=%u "
           "warp_id=%u active_mask=0x%08x resident_generation=%u "
           "service_cycle=%llu bridge_status=%s authority_status=%s "
           "registry_status=%s result=fault\n",
           owner_hw_sid, material.dynamic_warp_id, retire_warp_uid,
           warp_id, active_mask, resident_warp_generation, service_cycle,
           rtcore::v04::pre_submit_publication::status_name(status),
           rtcore::v04::allocation_identity::status_name(
               result.authority_status),
           rtcore::v04::address_range_registry::status_name(
               result.registry_status));
    fflush(stdout);
    return RTCORE_V04_RETIRE_LIVE_RELEASE_FAULT;
  }
  if (result.wait_required) {
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_RETIRE_LIVE_RELEASE "
           "owner_hw_sid=%u dynamic_warp_id=%u retire_warp_uid=%u "
           "warp_id=%u active_mask=0x%08x resident_generation=%u "
           "service_cycle=%llu release_started=%u outstanding=%llu "
           "result=wait\n",
           owner_hw_sid, material.dynamic_warp_id, retire_warp_uid,
           warp_id, active_mask, resident_warp_generation, service_cycle,
           result.release_started,
           static_cast<unsigned long long>(result.outstanding_transactions));
    fflush(stdout);
    return RTCORE_V04_RETIRE_LIVE_RELEASE_WAIT;
  }
  if (!result.released) return RTCORE_V04_RETIRE_LIVE_RELEASE_FAULT;
  const rtcore::v04::pre_submit_publication::bridge_snapshot_v0 snapshot =
      rtcore::v04::pre_submit_publication::shared_bridge().snapshot();
  printf("GPGPU-Sim RTCORE_V04_GLOBAL384_RETIRE_LIVE_RELEASE "
         "owner_hw_sid=%u dynamic_warp_id=%u retire_warp_uid=%u "
         "warp_id=%u active_mask=0x%08x resident_generation=%u "
         "service_cycle=%llu release_started=%u exact_ranges=validated "
         "released_record_id=%llu launch_generation=%u "
         "window_generation=%u owner_group_released=1 "
         "remaining_registered_groups=%zu remaining_live_ranges=%zu "
         "remaining_active_allocations=%zu result=released\n",
         owner_hw_sid, material.dynamic_warp_id, retire_warp_uid,
         warp_id, active_mask, resident_warp_generation, service_cycle,
         result.release_started,
         static_cast<unsigned long long>(result.identity.record_id),
         result.identity.launch_allocation_generation,
         result.identity.window_generation,
         snapshot.registered_group_count,
         snapshot.registry.live_count,
         snapshot.authority.active_record_count);
  fflush(stdout);
  return RTCORE_V04_RETIRE_LIVE_RELEASE_READY;
}

void rt_submit_impl(const ptx_instruction *pI, ptx_thread_info *thread) {
  if (rtcore_fail_closed_on_invalid_path_mode(pI)) {
    return;
  }
  if (!rtcore_custom_submit_continuation_contract_valid()) {
    const char *model = getenv("VULKAN_SIM_RTCORE_CONTINUATION_MODEL");
    printf("GPGPU-Sim PTX: RT_SUBMIT continuation-contract violation "
           "(%s:%u), continuation_model=%s, action=fail-closed, "
           "required_model=oracle_shader_boundary, "
           "fallback_path_mode=legacy\n",
           pI->source_file(), pI->source_line(),
           model != NULL && model[0] != '\0' ? model : "<unset>");
    fflush(stdout);
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  assert(pI->get_num_operands() == 3);

  bool v04_shadow_consumer_enabled = false;
  if (!rtcore_v04_shadow_consumer_configuration_valid(
          pI, &v04_shadow_consumer_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  bool v04_shadow_boundary_publication_enabled = false;
  if (!rtcore_v04_shadow_boundary_publication_configuration_valid(
          pI, v04_shadow_consumer_enabled,
          &v04_shadow_boundary_publication_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  bool v04_live_handoff_publication_enabled = false;
  if (!rtcore_v04_live_handoff_publication_configuration_valid(
          pI, v04_shadow_boundary_publication_enabled,
          &v04_live_handoff_publication_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  bool v04_tlas_binding_enforcement_enabled = false;
  if (!rtcore_v04_tlas_binding_enforcement_configuration_valid(
          pI, v04_shadow_boundary_publication_enabled,
          &v04_tlas_binding_enforcement_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  if (!rtcore_v04_shadow_shader_return_configuration_valid(
          pI, v04_shadow_boundary_publication_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  if (!rtcore_v04_functional_shader_return_configuration_valid(
          pI, v04_shadow_consumer_enabled,
          v04_shadow_boundary_publication_enabled,
          v04_live_handoff_publication_enabled,
          v04_tlas_binding_enforcement_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  if (!rtcore_v04_functional_only_configuration_valid(
          pI, v04_shadow_consumer_enabled,
          v04_shadow_boundary_publication_enabled,
          v04_live_handoff_publication_enabled,
          v04_tlas_binding_enforcement_enabled)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  const operand_info &result = pI->operand_lookup(0);
  const operand_info &context_ptr = pI->operand_lookup(1);
  const operand_info &handoff_window_base = pI->operand_lookup(2);

  ptx_reg_t context_ptr_data =
      thread->get_operand_value(context_ptr, context_ptr, B64_TYPE, thread, 1);
  ptx_reg_t handoff_window_base_data = thread->get_operand_value(
      handoff_window_base, handoff_window_base, B64_TYPE, thread, 1);
  const unsigned lane_slot_index = rtcore_lane_slot_index(thread);
  if (lane_slot_index == 0 && rtcore_env_flag_enabled(
                                  "VULKAN_SIM_RTCORE_TEST_CONTEXT_LANE_ALIAS")) {
    context_ptr_data.u64 += RTCORE_CONTEXT_BYTES_PER_LANE;
    printf("GPGPU-Sim PTX: RT_SUBMIT test-context-lane-alias "
           "(%s:%u), context_ptr=0x%llx, lane_slot_index=%u\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)context_ptr_data.u64, lane_slot_index);
    fflush(stdout);
  }

  if (rtcore_fail_closed_on_invalid_driver_runtime_handle_scaffold(
          pI, context_ptr_data.u64, handoff_window_base_data.u64,
          lane_slot_index)) {
    return;
  }

  if (!rtcore_submit_operands_are_valid(context_ptr_data.u64,
                                        handoff_window_base_data.u64)) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)context_ptr_data.u64,
           (unsigned long long)handoff_window_base_data.u64,
           lane_slot_index);
    fflush(stdout);
    inst_not_implemented(pI);
    return;
  }

  ptx_thread_info::rtcore_current_warp_metadata current_warp_metadata;
  thread->get_rtcore_current_warp_metadata(&current_warp_metadata);
  if (!rtcore_current_warp_metadata_is_valid(
          "RT_SUBMIT", pI, thread, &current_warp_metadata, lane_slot_index)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  if (!rtcore_symbolic_submit_lane_is_active(
          pI, lane_slot_index, context_ptr_data.u64,
          handoff_window_base_data.u64, current_warp_metadata.active_mask)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  if (!rtcore_submit_handoff_window_class_is_valid(
          pI, context_ptr_data.u64, handoff_window_base_data.u64,
          lane_slot_index)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  const rtcore_runtime_context_window_allocation_record allocation_record =
      rtcore_make_runtime_context_window_allocation_record(
          context_ptr_data.u64, handoff_window_base_data.u64, lane_slot_index);
  rtcore_v03_compact_context_decoded admission_context;
  bool admission_context_valid = false;
  if (rtcore_compiler_driver_publication_source_enabled()) {
    if (!rtcore_decode_v03_compact_context_image(
            pI, thread, context_ptr_data.u64, &admission_context)) {
      printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
             "reason=COMPACT_CONTEXT_ADMISSION_INVALID, "
             "context_ptr=0x%llx, handoff_window_base=0x%llx, "
             "lane_slot_index=%u, lifetime_mutated=0\n",
             pI->source_file(), pI->source_line(),
             (unsigned long long)context_ptr_data.u64,
             (unsigned long long)handoff_window_base_data.u64,
             lane_slot_index);
      fflush(stdout);
      inst_not_implemented(pI);
      return;
    }
    admission_context_valid = true;
  }

  const rtcore_symbolic_resource_profile resource_profile =
      rtcore_get_symbolic_resource_profile();
  rtcore_log_symbolic_resource_profile_once(resource_profile);

  const rtcore_synthetic_handoff_key key = rtcore_make_synthetic_handoff_key(
      handoff_window_base_data.u64, lane_slot_index, thread);
  const rtcore_symbolic_rt_token_key token_key =
      rtcore_make_symbolic_rt_token_key(context_ptr_data.u64,
                                        handoff_window_base_data.u64,
                                        lane_slot_index, thread);
  const rtcore_symbolic_resubmit_action resubmit_action =
      rtcore_try_commit_symbolic_resubmit(
          pI, thread, context_ptr_data.u64, handoff_window_base_data.u64,
          lane_slot_index, current_warp_metadata, key, token_key);
  if (resubmit_action == RTCORE_SYMBOLIC_RESUBMIT_REJECTED) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  if (resubmit_action == RTCORE_SYMBOLIC_RESUBMIT_PENDING_WHOLE_MASK ||
      resubmit_action == RTCORE_SYMBOLIC_RESUBMIT_COMMITTED) {
    return;
  }

  std::array<uint32_t, rtcore::abi_v04::kWordCount>
      v04_shadow_trace_input_words = {};
  std::array<uint8_t, rtcore::abi_v04::kLaneSlotBytes>
      v04_initial_handoff_acquire_image = {};
  const unsigned char *v04_initial_handoff_acquire_bytes = NULL;
  unsigned v04_initial_handoff_acquire_byte_count = 0;
  unsigned v04_initial_resident_generation = 0;
  bool global384_profile = false;
  if (!rtcore_v04_global384_profile_selected(&global384_profile)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }
  const bool v04_initial_handoff_acquire_consumer =
      global384_profile && rtcore_v04_functional_only_engine_gate_active();
  if (v04_initial_handoff_acquire_consumer) {
    unsigned resident_warp_uid = 0;
    unsigned resident_active_mask = 0;
    unsigned resident_occupancy = 0;
    if (!rtcore_query_resident_rt_warp_record(
            current_warp_metadata.owner_hw_sid,
            current_warp_metadata.warp_id, &resident_warp_uid,
            &resident_active_mask, &v04_initial_resident_generation,
            &resident_occupancy) ||
        resident_warp_uid != current_warp_metadata.warp_uid ||
        resident_active_mask != current_warp_metadata.active_mask ||
        resident_occupancy == 0 ||
        !rtcore_copy_v04_global384_initial_handoff_acquire_lane_before_functional(
            current_warp_metadata.owner_hw_sid,
            current_warp_metadata.dynamic_warp_id,
            current_warp_metadata.warp_uid, current_warp_metadata.warp_id,
            current_warp_metadata.active_mask, v04_initial_resident_generation,
            lane_slot_index, v04_initial_handoff_acquire_image.data(),
            v04_initial_handoff_acquire_image.size())) {
      rtcore_reject_symbolic_submit(pI);
      return;
    }
    v04_initial_handoff_acquire_bytes =
        v04_initial_handoff_acquire_image.data();
    v04_initial_handoff_acquire_byte_count =
        v04_initial_handoff_acquire_image.size();
  }
  if (v04_shadow_consumer_enabled &&
      (!admission_context_valid ||
       !rtcore_validate_v04_shadow_trace_input(
           pI, thread, context_ptr_data.u64, handoff_window_base_data.u64,
           lane_slot_index, admission_context,
           current_warp_metadata.owner_hw_sid,
           current_warp_metadata.dynamic_warp_id,
           current_warp_metadata.warp_uid,
           current_warp_metadata.warp_id,
           v04_initial_resident_generation,
           v04_initial_handoff_acquire_bytes,
           v04_initial_handoff_acquire_byte_count,
           &v04_shadow_trace_input_words))) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=V04_SHADOW_TRACE_INPUT_MISMATCH, context_ptr=0x%llx, "
           "handoff_window_base=0x%llx, lane_slot_index=%u, "
           "admission_context_valid=%u, lifetime_mutated=0, "
           "traversal_consumed=0\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)context_ptr_data.u64,
           (unsigned long long)handoff_window_base_data.u64,
           lane_slot_index, admission_context_valid ? 1u : 0u);
    fflush(stdout);
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  if (!rtcore_symbolic_submit_has_capacity(
          pI, resource_profile, lane_slot_index, context_ptr_data.u64,
          handoff_window_base_data.u64)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  if (!rtcore_symbolic_submit_lane_slot_available(
          pI, key, context_ptr_data.u64)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  if (!rtcore_symbolic_submit_token_available(pI, token_key)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  const rtcore_symbolic_rt_token_reservation_key reservation_key =
      rtcore_make_symbolic_rt_token_reservation_key(
          current_warp_metadata, context_ptr_data.u64,
          handoff_window_base_data.u64);
  if (!rtcore_symbolic_submit_token_reservation_available(
          pI, resource_profile, reservation_key, token_key, lane_slot_index)) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  bool lifetime_record_created = false;
  const rtcore_launch_allocation_lifetime_record *lifetime_record =
      rtcore_get_or_create_launch_allocation_lifetime_record(
          allocation_record, current_warp_metadata.active_mask,
          &lifetime_record_created);
  rtcore_log_launch_allocation_lifetime_submit(
      pI, allocation_record, lifetime_record, lifetime_record_created);
  if (allocation_record.enabled && lifetime_record == NULL) {
    printf("GPGPU-Sim PTX: RT_SUBMIT fail-closed (%s:%u), "
           "reason=LAUNCH_ALLOCATION_LIFETIME_TABLE_MISSING, "
           "context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)context_ptr_data.u64,
           (unsigned long long)handoff_window_base_data.u64,
           lane_slot_index);
    fflush(stdout);
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  if (v04_initial_handoff_acquire_consumer &&
      !rtcore_consume_v04_global384_initial_handoff_acquire_lane_before_functional(
          current_warp_metadata.owner_hw_sid,
          current_warp_metadata.dynamic_warp_id,
          current_warp_metadata.warp_uid, current_warp_metadata.warp_id,
          current_warp_metadata.active_mask, v04_initial_resident_generation,
          lane_slot_index, thread->get_uid())) {
    rtcore_reject_symbolic_submit(pI);
    return;
  }

  rtcore_traversal_completion_adapter_publish(
      pI, thread, result, context_ptr_data.u64, handoff_window_base_data.u64,
      allocation_record, lifetime_record,
      v04_shadow_boundary_publication_enabled,
      v04_tlas_binding_enforcement_enabled,
      v04_shadow_boundary_publication_enabled
          ? &v04_shadow_trace_input_words
          : NULL);
}

static bool rtcore_publish_symbolic_retire_intent(
    const ptx_instruction *pI,
    const ptx_thread_info::rtcore_current_warp_metadata &metadata,
    unsigned lane_slot_index, unsigned thread_uid,
    unsigned long long context_ptr, unsigned long long handoff_window_base,
    const rtcore_synthetic_handoff_key &handoff_key,
    const rtcore_symbolic_rt_token_key &token_key,
    const rtcore_runtime_context_window_allocation_record &allocation_record,
    unsigned token_id, unsigned token_allocator_generation,
    unsigned window_generation, const char **failure_reason) {
  const char *reason = "accepted";
  const unsigned lane_mask =
      lane_slot_index < RTCORE_MAX_LANES_PER_WARP
          ? 1u << lane_slot_index
          : 0;
  if (lane_mask == 0 || (metadata.active_mask & lane_mask) == 0) {
    reason = "RETIRE_INTENT_LANE_NOT_ACTIVE";
  }

  rtcore_symbolic_retire_transaction &transaction =
      g_rtcore_symbolic_retire_transactions[metadata.warp_uid];
  if (!transaction.valid && strcmp(reason, "accepted") == 0) {
    transaction.valid = true;
    transaction.instruction = pI;
    transaction.owner_hw_sid = metadata.owner_hw_sid;
    transaction.warp_uid = metadata.warp_uid;
    transaction.dynamic_warp_id = metadata.dynamic_warp_id;
    transaction.warp_id = metadata.warp_id;
    transaction.static_inst_uid = metadata.static_inst_uid;
  } else if (transaction.valid &&
             (transaction.claimed ||
              transaction.owner_hw_sid != metadata.owner_hw_sid ||
              transaction.warp_uid != metadata.warp_uid ||
              transaction.dynamic_warp_id != metadata.dynamic_warp_id ||
              transaction.warp_id != metadata.warp_id ||
              transaction.static_inst_uid != metadata.static_inst_uid)) {
    reason = "RETIRE_INTENT_TRANSACTION_IDENTITY_MISMATCH";
  }
  if (strcmp(reason, "accepted") == 0 &&
      (transaction.seen_lane_mask & lane_mask) != 0) {
    reason = "RETIRE_INTENT_DUPLICATE_LANE";
  }

  if (strcmp(reason, "accepted") == 0) {
    rtcore_symbolic_retire_lane_intent &intent =
        transaction.lane[lane_slot_index];
    intent.valid = true;
    intent.thread_uid = thread_uid;
    intent.context_ptr = context_ptr;
    intent.handoff_window_base = handoff_window_base;
    intent.token_id = token_id;
    intent.token_allocator_generation = token_allocator_generation;
    intent.window_generation = window_generation;
    intent.handoff_key = handoff_key;
    intent.token_key = token_key;
    intent.allocation_record = allocation_record;
    transaction.seen_lane_mask |= lane_mask;
    transaction.validated_lane_mask |= lane_mask;
    printf("GPGPU-Sim RTCORE_RETIRE_INTENT_PUBLISH "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
           "active_mask=0x%08x seen_lane_mask=0x%08x "
           "validated_lane_mask=0x%08x resource_release_deferred=1\n",
           metadata.owner_hw_sid, metadata.warp_uid, metadata.warp_id,
           lane_slot_index, metadata.active_mask,
           transaction.seen_lane_mask, transaction.validated_lane_mask);
    fflush(stdout);
  } else if (!transaction.valid || transaction.seen_lane_mask == 0) {
    g_rtcore_symbolic_retire_transactions.erase(metadata.warp_uid);
  }
  if (failure_reason) {
    *failure_reason = reason;
  }
  return strcmp(reason, "accepted") == 0;
}

extern "C" bool rtcore_claim_symbolic_retire_transaction(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask, unsigned long long claim_cycle,
    const char **failure_reason) {
  const char *reason = "accepted";
  std::map<unsigned, rtcore_symbolic_retire_transaction>::iterator it =
      g_rtcore_symbolic_retire_transactions.find(warp_uid);
  if (it == g_rtcore_symbolic_retire_transactions.end() ||
      !it->second.valid) {
    reason = "RETIRE_INTENT_TRANSACTION_MISSING";
  }
  rtcore_symbolic_retire_transaction *transaction =
      strcmp(reason, "accepted") == 0 ? &it->second : NULL;
  if (transaction &&
      (transaction->claimed || transaction->owner_hw_sid != owner_hw_sid ||
       transaction->warp_id != warp_id || active_mask == 0)) {
    reason = "RETIRE_INTENT_CLAIM_IDENTITY_MISMATCH";
  }
  if (transaction && strcmp(reason, "accepted") == 0 &&
      (transaction->seen_lane_mask != active_mask ||
       transaction->validated_lane_mask != active_mask)) {
    reason = "RETIRE_INTENT_WHOLE_MASK_INCOMPLETE";
  }
  if (transaction && strcmp(reason, "accepted") == 0) {
    transaction->active_mask = active_mask;
    transaction->claimed = true;
    transaction->claim_cycle = claim_cycle;
    printf("GPGPU-Sim RTCORE_RETIRE_INTENT_CLAIM "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u "
           "active_mask=0x%08x seen_lane_mask=0x%08x "
           "validated_lane_mask=0x%08x claim_cycle=%llu\n",
           owner_hw_sid, warp_uid, warp_id, active_mask,
           transaction->seen_lane_mask, transaction->validated_lane_mask,
           claim_cycle);
    fflush(stdout);
  }
  if (failure_reason) {
    *failure_reason = reason;
  }
  return strcmp(reason, "accepted") == 0;
}

static bool rtcore_v04_functional_only_release_warp(
    unsigned owner_hw_sid, unsigned warp_id, unsigned active_mask) {
  const rtcore_v04_functional_only_warp_key key =
      std::make_pair(owner_hw_sid, warp_id);
  std::map<rtcore_v04_functional_only_warp_key,
           rtcore_v04_functional_only_warp_record>::iterator warp =
      g_rtcore_v04_functional_only_live_warps.find(key);
  if (warp == g_rtcore_v04_functional_only_live_warps.end() ||
      !warp->second.valid ||
      warp->second.bound_lane_mask != active_mask) {
    return false;
  }
  const unsigned submit_warp_uid = warp->second.warp_uid;
  const unsigned current_active_mask = warp->second.active_mask;
  request_owner::allocator_state_v0 &allocator =
      rtcore_v04_functional_only_allocator(owner_hw_sid);
  request_owner::release_warp_plan_v0 plan = {};
  if (request_owner::prepare_release_warp(
          allocator, warp->second.resident_warp_slot, owner_hw_sid,
          submit_warp_uid, warp_id, &plan) != request_owner::kStatusOk ||
      request_owner::commit_release_warp(
          &allocator, plan) != request_owner::kStatusOk) {
    return false;
  }
  const rtcore_v04_functional_only_warp_record released = warp->second;
  rtcore_v04_functional_only_record_warp_or_abort(
      rtcore::v04::conservation::kEventTerminalRelease, released,
      submit_warp_uid, current_active_mask);
  rtcore_v04_functional_only_record_warp_or_abort(
      rtcore::v04::conservation::kEventRetire, released,
      submit_warp_uid, current_active_mask);
  g_rtcore_v04_functional_only_live_warps.erase(warp);
  printf("GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_WARP_RELEASE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u "
         "active_mask=0x%08x bound_lane_mask=0x%08x "
         "timing_state_mutated=0\n",
         owner_hw_sid, submit_warp_uid, warp_id,
         current_active_mask, active_mask);
  fflush(stdout);
  return true;
}

extern "C" bool rtcore_commit_symbolic_retire_transaction(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask, unsigned long long commit_cycle,
    unsigned *released_lane_mask, const char **failure_reason) {
  const char *reason = "accepted";
  std::map<unsigned, rtcore_symbolic_retire_transaction>::iterator it =
      g_rtcore_symbolic_retire_transactions.find(warp_uid);
  if (it == g_rtcore_symbolic_retire_transactions.end() ||
      !it->second.valid || !it->second.claimed) {
    reason = "RETIRE_INTENT_TRANSACTION_NOT_CLAIMED";
  }
  rtcore_symbolic_retire_transaction *transaction =
      strcmp(reason, "accepted") == 0 ? &it->second : NULL;
  if (transaction &&
      (transaction->owner_hw_sid != owner_hw_sid ||
       transaction->warp_id != warp_id ||
       transaction->active_mask != active_mask ||
       transaction->seen_lane_mask != active_mask ||
       transaction->validated_lane_mask != active_mask)) {
    reason = "RETIRE_INTENT_COMMIT_IDENTITY_MISMATCH";
  }

  if (transaction && strcmp(reason, "accepted") == 0) {
    for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
      const unsigned lane_mask = 1u << lane;
      if ((active_mask & lane_mask) == 0) {
        continue;
      }
      const rtcore_symbolic_retire_lane_intent &intent =
          transaction->lane[lane];
      std::map<rtcore_synthetic_handoff_key,
               rtcore_v03_handoff_lane_slot>::const_iterator window =
          g_rtcore_synthetic_handoff_windows.find(intent.handoff_key);
      std::map<rtcore_symbolic_rt_token_key,
               rtcore_symbolic_rt_token_record>::const_iterator token =
          g_rtcore_symbolic_rt_tokens.find(intent.token_key);
      const bool window_matches =
          intent.valid &&
          window != g_rtcore_synthetic_handoff_windows.end() &&
          window->second.context_ptr == intent.context_ptr &&
          window->second.handoff_window_base == intent.handoff_window_base &&
          window->second.lane_slot_index == lane &&
          window->second.owner_hw_sid == intent.handoff_key.owner_hw_sid &&
          window->second.owner_hw_wid == intent.handoff_key.owner_hw_wid &&
          window->second.submit_transaction_id == intent.window_generation &&
          window->second.window_state == RTCORE_WINDOW_STATE_COMPLETE;
      const bool token_matches =
          token != g_rtcore_symbolic_rt_tokens.end() &&
          token->second.token_id == intent.token_id &&
          token->second.allocator_generation ==
              intent.token_allocator_generation &&
          token->second.completed &&
          rtcore_symbolic_rt_token_allocator_record_matches(token->second);
      const bool lifetime_matches =
          rtcore_preflight_launch_allocation_lifetime_retire(
              intent.allocation_record);
      if (!window_matches || !token_matches || !lifetime_matches ||
          !rtcore_symbolic_rt_token_can_retire(transaction->instruction,
                                                intent.token_key)) {
        reason = !window_matches
                     ? "RETIRE_COMMIT_WINDOW_STALE"
                     : (!token_matches
                            ? "RETIRE_COMMIT_TOKEN_STALE"
                            : "RETIRE_COMMIT_RUNTIME_LIFETIME_STALE");
        break;
      }
    }
  }

  unsigned released_mask = 0;
  if (transaction && strcmp(reason, "accepted") == 0) {
    for (unsigned lane = 0; lane < RTCORE_MAX_LANES_PER_WARP; ++lane) {
      const unsigned lane_mask = 1u << lane;
      if ((active_mask & lane_mask) == 0) {
        continue;
      }
      const rtcore_symbolic_retire_lane_intent &intent =
          transaction->lane[lane];
      const bool released_window =
          rtcore_release_synthetic_handoff_window(intent.handoff_key);
      const bool released_token =
          rtcore_release_symbolic_rt_token(intent.token_key);
      if (!released_window || !released_token) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_RETIRE_RESOURCE_COMMIT_INVARIANT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                "released_window=%u released_token=%u\n",
                owner_hw_sid, warp_uid, warp_id, lane,
                released_window ? 1u : 0u, released_token ? 1u : 0u);
        fflush(stderr);
        abort();
      }
      const bool lifetime_retire_committed =
          rtcore_mark_launch_allocation_lifetime_retire(
          transaction->instruction, intent.allocation_record, active_mask,
          released_window, released_token);
      if (!lifetime_retire_committed) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_RETIRE_RESOURCE_COMMIT_INVARIANT "
                "reason=RETIRE_COMMIT_RUNTIME_LIFETIME_STALE "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u\n",
                owner_hw_sid, warp_uid, warp_id, lane);
        fflush(stderr);
        abort();
      }
      rtcore_log_runtime_context_window_allocation_retire(
          transaction->instruction, intent.allocation_record,
          released_window, released_token,
          rtcore_synthetic_handoff_window_count(),
          rtcore_symbolic_rt_token_count(),
          rtcore_symbolic_rt_token_allocator_live_count());
      released_mask |= lane_mask;
    }

    printf("GPGPU-Sim RTCORE_RETIRE_EXTERNAL_LIFECYCLE_COMMIT "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u "
           "active_mask=0x%08x released_lane_mask=0x%08x "
           "remaining_windows=%zu remaining_tokens=%zu "
           "remaining_allocator_live=%zu commit_cycle=%llu\n",
           owner_hw_sid, warp_uid, warp_id, active_mask, released_mask,
           rtcore_synthetic_handoff_window_count(),
           rtcore_symbolic_rt_token_count(),
           rtcore_symbolic_rt_token_allocator_live_count(), commit_cycle);
    fflush(stdout);
    if (rtcore_v04_functional_only_engine_gate_active() &&
        !rtcore_v04_functional_only_release_warp(
            owner_hw_sid, warp_id, active_mask)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_RELEASE_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u "
              "active_mask=0x%08x\n",
              owner_hw_sid, warp_uid, warp_id, active_mask);
      fflush(stderr);
      abort();
    }
    g_rtcore_symbolic_retire_transactions.erase(it);
  }
  if (released_lane_mask) {
    *released_lane_mask = released_mask;
  }
  if (failure_reason) {
    *failure_reason = reason;
  }
  return strcmp(reason, "accepted") == 0 && released_mask == active_mask;
}

void rt_retire_context_impl(const ptx_instruction *pI, ptx_thread_info *thread) {
  assert(pI->get_num_operands() == 2);
  const operand_info &context_ptr = pI->operand_lookup(0);
  const operand_info &handoff_window_base = pI->operand_lookup(1);

  ptx_reg_t context_ptr_data =
      thread->get_operand_value(context_ptr, context_ptr, B64_TYPE, thread, 1);
  ptx_reg_t handoff_window_base_data = thread->get_operand_value(
      handoff_window_base, handoff_window_base, B64_TYPE, thread, 1);

  const bool operands_are_valid = rtcore_submit_operands_are_valid(
      context_ptr_data.u64, handoff_window_base_data.u64);
  const unsigned lane_slot_index = rtcore_lane_slot_index(thread);
  ptx_thread_info::rtcore_current_warp_metadata current_warp_metadata;
  thread->get_rtcore_current_warp_metadata(&current_warp_metadata);
  const unsigned lane_thread_mask = rtcore_lane_thread_mask(lane_slot_index);
  const bool test_active_mask_override =
      rtcore_test_inactive_lane_retire_enabled();
  if (test_active_mask_override) {
    current_warp_metadata.active_mask &= ~lane_thread_mask;
  }
  const bool retire_metadata_valid = rtcore_current_warp_metadata_is_valid(
      "RT_RETIRE_CONTEXT", pI, thread, &current_warp_metadata, lane_slot_index);
  const bool timing_rt_unit_available =
      thread->get_core() != NULL && thread->get_core()->get_gpu() != NULL &&
      !thread->get_core()->get_gpu()->is_functional_sim();
  if (!timing_rt_unit_available) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "reason=STAGED_RETIRE_REQUIRES_TIMING_RT_UNIT, "
           "retire_phase=preflight, consumed=0\n",
           pI->source_file(), pI->source_line());
    fflush(stdout);
    inst_not_implemented(pI);
    return;
  }
  const rtcore_synthetic_handoff_key key = rtcore_make_synthetic_handoff_key(
      handoff_window_base_data.u64, lane_slot_index, thread);
  const rtcore_symbolic_rt_token_key token_key =
      rtcore_make_symbolic_rt_token_key(context_ptr_data.u64,
                                        handoff_window_base_data.u64,
                                        lane_slot_index, thread);
  const rtcore_v03_handoff_lane_slot *window =
      operands_are_valid
          ? rtcore_acquire_synthetic_handoff_window(
                g_rtcore_synthetic_handoff_windows, key)
          : NULL;
  const bool tracked_window = window != NULL;
  const bool matching_context =
      tracked_window && window->context_ptr == context_ptr_data.u64;
  const bool owner_tuple_matches =
      tracked_window &&
      rtcore_synthetic_owner_tuple_matches(*window, key, context_ptr_data.u64,
                                           pI, thread);
  const rtcore_runtime_context_window_allocation_record allocation_record =
      rtcore_make_runtime_context_window_allocation_record(
          context_ptr_data.u64, handoff_window_base_data.u64, lane_slot_index);
  const bool token_can_retire =
      operands_are_valid && retire_metadata_valid && tracked_window &&
      matching_context && owner_tuple_matches &&
      rtcore_symbolic_rt_token_can_retire(pI, token_key);

  if (!operands_are_valid || !retire_metadata_valid || !tracked_window ||
      !matching_context || !owner_tuple_matches || !token_can_retire) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u, valid=%u, metadata_valid=%u, tracked=%u, "
           "matching_context=%u, owner_tuple_match=%u, token_can_retire=%u\n",
           pI->source_file(), pI->source_line(),
           (unsigned long long)context_ptr_data.u64,
           (unsigned long long)handoff_window_base_data.u64,
           lane_slot_index, operands_are_valid ? 1 : 0,
           retire_metadata_valid ? 1 : 0, tracked_window ? 1 : 0,
           matching_context ? 1 : 0, owner_tuple_matches ? 1 : 0,
           token_can_retire ? 1 : 0);
    fflush(stdout);
    inst_not_implemented(pI);
    return;
  }

  rtcore_log_v02_lsu_retire_side_observation(
      pI, context_ptr_data.u64, handoff_window_base_data.u64, lane_slot_index,
      window, tracked_window, matching_context, owner_tuple_matches, token_key,
      token_can_retire);

  std::map<rtcore_symbolic_rt_token_key,
           rtcore_symbolic_rt_token_record>::const_iterator resident_token =
      g_rtcore_symbolic_rt_tokens.find(token_key);
  const bool resident_token_found =
      resident_token != g_rtcore_symbolic_rt_tokens.end();
  const unsigned resident_token_id =
      resident_token_found ? resident_token->second.token_id : 0;
  const unsigned resident_token_generation =
      resident_token_found ? resident_token->second.allocator_generation : 0;
  const unsigned resident_window_generation = window->submit_transaction_id;
  const char *resident_retire_preflight_failure = "accepted";
  const bool resident_retire_preflight_accepted =
      resident_token_found &&
      rtcore_preflight_retire_resident_rt_warp_lane(
          current_warp_metadata.owner_hw_sid,
          current_warp_metadata.warp_id, lane_slot_index, thread->get_uid(),
          context_ptr_data.u64, handoff_window_base_data.u64,
          resident_token_id, resident_token_generation,
          resident_window_generation, &resident_retire_preflight_failure);
  if (!resident_retire_preflight_accepted) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "reason=%s, context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u, resident_token_found=%u, "
           "retire_phase=preflight, consumed=0\n",
           pI->source_file(), pI->source_line(),
           resident_retire_preflight_failure,
           (unsigned long long)context_ptr_data.u64,
           (unsigned long long)handoff_window_base_data.u64, lane_slot_index,
           resident_token_found ? 1u : 0u);
    fflush(stdout);
    inst_not_implemented(pI);
    return;
  }

  const char *retire_intent_failure = "accepted";
  const bool retire_intent_published =
      resident_token_found &&
      rtcore_publish_symbolic_retire_intent(
          pI, current_warp_metadata, lane_slot_index, thread->get_uid(),
          context_ptr_data.u64, handoff_window_base_data.u64, key, token_key,
          allocation_record, resident_token_id, resident_token_generation,
          resident_window_generation, &retire_intent_failure);
  if (!retire_intent_published) {
    printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT fail-closed (%s:%u), "
           "reason=%s, context_ptr=0x%llx, handoff_window_base=0x%llx, "
           "lane_slot_index=%u, retire_phase=intent_publication, consumed=0\n",
           pI->source_file(), pI->source_line(), retire_intent_failure,
           (unsigned long long)context_ptr_data.u64,
           (unsigned long long)handoff_window_base_data.u64,
           lane_slot_index);
    fflush(stdout);
    inst_not_implemented(pI);
    return;
  }

  printf("GPGPU-Sim PTX: RT_RETIRE_CONTEXT synthetic-retire (%s:%u), "
         "context_ptr=0x%llx, handoff_window_base=0x%llx, "
         "lane_slot_index=%u, owner_tuple_match=%u, released=%u, "
         "released_token=%u, remaining_windows=%zu, remaining_tokens=%zu, "
         "remaining_allocator_live=%zu, retire_phase=intent_publication, "
         "resource_release_deferred=1\n",
         pI->source_file(), pI->source_line(),
         (unsigned long long)context_ptr_data.u64,
         (unsigned long long)handoff_window_base_data.u64, lane_slot_index,
         owner_tuple_matches ? 1 : 0, 0u, 0u,
         rtcore_synthetic_handoff_window_count(),
         rtcore_symbolic_rt_token_count(),
         rtcore_symbolic_rt_token_allocator_live_count());
  fflush(stdout);
}

